window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0079", [{"word":"mutant","ipa_uk":"/ˈmjuːtənt/","ipa_us":"/ˈmjuːtənt/","definition_zh":"突变体；突变型；突变的；突变株","definition_en":"an organism whose genes have changed, or a form produced by such a change","core_image":"同一批种子长出的苗里，有一株叶片明显更宽、颜色更深","scene":"实验室的记录本上，同一批种子长出了两株不一样的苗。观察员把那株宽叶的单独移进一个托盘，说：The mutant keeps broader leaves than its siblings.","sceneCN":"这里指「携带突变、表现出新性状的生物体」（第 1 个义项：基因发生改变因而带有新性状的个体）；句意为这株突变体一直比同批的其他苗叶片更宽。","pos":[{"tag":"n.","zh":"突变体；突变型；突变株（可数，复数 mutants）"},{"tag":"adj.","zh":"突变的；由突变产生的"}],"collocations":[{"phrase":"mutant gene","zh":"突变基因"},{"phrase":"mutant strain","zh":"突变株；突变品系"},{"phrase":"mutant allele","zh":"突变等位基因"},{"phrase":"mutant organism","zh":"突变生物体"},{"phrase":"induced mutant","zh":"诱发突变体"},{"phrase":"mutant population","zh":"突变群体"},{"phrase":"mutant form","zh":"突变型"}],"forms":[{"label":"复数","form":"mutants"},{"label":"比较级（形容词，较少用）","form":"more mutant"},{"label":"最高级（形容词，较少用）","form":"most mutant"},{"label":"相关名词（突变）","form":"mutation（突变）"},{"label":"相关动词（使突变）","form":"mutate（突变；使突变）"},{"label":"相关形容词（突变的）","form":"mutational（突变引起的）"}],"derivatives":[{"word":"mutation","pos":"n.","zh":"突变；变化"},{"word":"mutate","pos":"v.","zh":"突变；使发生变化"},{"word":"mutational","pos":"adj.","zh":"突变引起的"},{"word":"mutable","pos":"adj.","zh":"可变的；易变的"},{"word":"mutability","pos":"n.","zh":"可变性；易变性"},{"word":"mutagen","pos":"n.","zh":"诱变剂"}],"senses":[{"no":"01","title":"An organism carrying a mutation","titleCN":"携带突变的生物体","definition":"an organism that has a changed gene and therefore a new trait","definitionCN":"基因发生改变、因而表现出新性状的生物体","example":"This mutant has broader leaves than its siblings.","exampleCN":"这株突变体比同批的其他苗叶片更宽。","why":"Mutant names the carrier, not the change itself: the change happens in the gene, and the whole organism is labelled by it.","whyCN":"突变体命名的是携带者，而非变化本身：变化发生在基因里，整株生物却因此被贴上标签。"},{"no":"02","title":"A laboratory strain kept for study","titleCN":"实验室保存的突变品系","definition":"a strain of an organism maintained in the laboratory because of a specific mutation","definitionCN":"因带有特定突变而在实验室中保存的品系","example":"The team stores the mutant at minus eighty degrees.","exampleCN":"团队把该突变品系保存在零下八十度。","why":"Once a mutation proves useful, the organism becomes a stock item, and the noun shifts from a natural oddity to a laboratory material.","whyCN":"一旦某个突变被证明有用，这个生物就成了库存材料，名词也从自然界的异常个体转指实验材料。"},{"no":"03","title":"An individual showing a new trait","titleCN":"表现出新性状的个体","definition":"an individual whose visible features differ because of a gene change","definitionCN":"因基因改变而外观特征不同的个体","example":"The dark-eyed mutant stood out in the field.","exampleCN":"那只深色眼的突变个体在田里很显眼。","why":"Phenotype is what observers see first, so the word often points to the visible difference rather than the hidden gene.","whyCN":"观察者最先看到的是表型，所以这个词常指向可见差异，而非看不见的基因。"},{"no":"04","title":"Changed by mutation as an adjective","titleCN":"突变的（形容词用法）","definition":"produced by or carrying a mutation","definitionCN":"由突变产生或携带突变的","example":"A mutant gene can spread quickly in a small population.","exampleCN":"突变基因在小群体中可能迅速扩散。","why":"As an adjective the word moves from the whole organism to its parts: a gene, a protein or a cell can be mutant.","whyCN":"作形容词时，这个词从整个生物体移到它的部件：基因、蛋白质或细胞都可以是突变的。"},{"no":"05","title":"A microbial mutant strain","titleCN":"微生物突变株","definition":"a bacterium, virus or fungus whose genome has been altered","definitionCN":"基因组被改变的细菌、病毒或真菌","example":"The antibiotic-resistant mutant survived the treatment.","exampleCN":"抗药性突变株在治疗中存活下来。","why":"Microbiology uses the noun for clonal populations with a defined change, because such strains are handled as units.","whyCN":"微生物学把这个名词用于带明确改变的克隆群体，因为这类菌株是作为单位来操作的。"},{"no":"06","title":"A crop or livestock mutant","titleCN":"作物与畜禽的突变体","definition":"a plant or farm animal selected because a mutation gives a useful trait","definitionCN":"因突变带来有用性状而被选留的植物或畜禽","example":"Breeders released a mutant that ripens two weeks early.","exampleCN":"育种者推出了一个提前两周成熟的突变体。","why":"Breeding turns a rare mutation into a product, so the word enters agriculture as a commercial label.","whyCN":"育种把罕见的突变变成产品，于是这个词作为商业标签进入农业。"},{"no":"07","title":"A figurative oddity","titleCN":"比喻：怪异的个体","definition":"a person or thing that seems strangely different from the rest","definitionCN":"与其余同类相比显得怪异的人或物","example":"Among the plain offices, that glass tower is a mutant.","exampleCN":"在一排朴素的办公楼中，那座玻璃塔楼像个异类。","why":"The genetic idea of a departure from the standard type is borrowed for anything that breaks the pattern.","whyCN":"遗传学里偏离标准类型的观念，被借用来形容任何打破模式的东西。"},{"no":"08","title":"A fictional variant being","titleCN":"科幻作品中的变种人","definition":"in fiction, a being with powers that come from altered genes","definitionCN":"虚构作品中因基因改变而获得特殊能力的生物","example":"The comic follows a mutant who can control weather.","exampleCN":"这部漫画讲述一个能操控天气的变种人。","why":"Popular fiction takes the scientific noun and adds power, turning a mutation into a superhero origin.","whyCN":"流行文艺把科学名词加上超能力，把突变变成了超级英雄的出身。"}],"etymology":{"intro":{"en":"Mutant is the present participle of Latin mutare 'to change', used in English as an adjective and then as a noun. Its biological sense grew with early genetics around 1900. Dates are approximate.","cn":"mutant 是拉丁 mutare「改变」的现在分词，在英语中先作形容词，后作名词。它的生物学义项随 1900 年前后的早期遗传学而发展。年代均为约数。"},"items":[{"era":"LATIN MUTARE","en":"Mutare meant 'to change, alter, exchange'. Its present participle mutans, mutant- supplies the -ant ending of English mutant, and the same verb gives mutation and mutate.","cn":"mutare 意为「改变、更动、交换」。它的现在分词 mutans（词干 mutant-）提供了英语 mutant 的 -ant 结尾，同一动词还衍生 mutation 与 mutate。"},{"era":"LATIN MUTARE'S ORIGIN","en":"The deeper source of mutare is generally connected with a root meaning 'to change, exchange', seen in Latin mutuus 'mutual, exchanged', but the reconstruction is not settled.","cn":"mutare 的更深来源一般与表示「改变、交换」的词根联系起来，拉丁 mutuus「相互的、交换的」也属这一组，但这一重构尚无定论。"},{"era":"EARLY ENGLISH MUTATION","en":"Mutation entered English in the fourteenth century with the general sense 'change'. The biological sense, a sudden heritable change in an organism, dates from about 1900.","cn":"mutation 在 14 世纪进入英语，泛指「变化」。表示生物体突然发生可遗传改变的生物学义项，约始于 1900 年。"},{"era":"GENETIC MUTANT","en":"The noun mutant for an individual carrying such a change is dated to the early twentieth century, when experimental genetics needed a name for the altered stock.","cn":"指携带这种改变的个体的名词 mutant，年代定在 20 世纪初；当时实验遗传学需要一个名称来指被改变的品系。"},{"era":"MODERN ENGLISH","en":"Modern English uses mutant as both adjective and noun. The figurative sense 'oddity' belongs to the later twentieth century, helped by fiction and film.","cn":"现代英语中 mutant 兼作形容词与名词。表示「异类」的比喻义属于 20 世纪后期，小说与电影推动了这一用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root and first dates): the link of mutare to an Indo-European root is a reconstruction with competing accounts, and the earliest use of mutant in its genetic sense is known only approximately.","cn":"来源不确定（词根与首见年代）：把 mutare 追溯到某个印欧词根属重构形式，存在不同假说；mutant 遗传学义项的最早使用也只有大致年代。"}]},"similar":{"note":{"en":"Group one holds words built on the same change-root that are easily confused; group two holds neighbouring biological terms for altered organisms.","cn":"第一组是同出「改变」词根、容易混淆的词；第二组是表示生物体被改变的邻近术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mutate","ipa":"/ˈmjuːteɪt/","tag":"the verb","definition":"To change genetically, or to cause such a change. Mutant is the organism or the adjective; mutate is the event.","definitionCN":"指发生基因改变或使发生改变；mutant 指生物体或形容词，mutate 指改变这件事。"},{"word":"mutation","ipa":"/mjuːˈteɪʃn/","tag":"the change itself","definition":"The change in the gene, not the carrier. A mutation produces a mutant.","definitionCN":"指基因中的改变本身，而非携带者；突变产生突变体。"},{"word":"mutagen","ipa":"/ˈmjuːtədʒən/","tag":"the cause","definition":"An agent such as radiation or a chemical that raises the rate of mutation; it is not the resulting organism.","definitionCN":"指辐射或化学物质等提高突变率的因素，不是突变产生的生物体。"},{"word":"mutual","ipa":"/ˈmjuːtʃuəl/","tag":"same Latin family","definition":"Shared by two sides. It comes from the same Latin exchange-root but has nothing to do with genes.","definitionCN":"指双方共同的；它同出拉丁「交换」词根，但与基因无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"variant","ipa":"/ˈværiənt/","tag":"a version, not a carrier","definition":"A form that differs from a standard; in genetics it may be a version of a gene, while mutant stresses the changed organism.","definitionCN":"指与标准不同的形式；在遗传学中可指基因的一个版本，而 mutant 强调被改变的生物体。"},{"word":"sport","ipa":"/spɔːt/","tag":"old horticultural term","definition":"An old gardening word for a plant that suddenly differs from its parent, now largely replaced by mutant.","definitionCN":"园艺学旧称，指突然与亲本不同的植株，现多由 mutant 取代。"},{"word":"monstrosity","ipa":"/mɒnˈstrɒsəti/","tag":"judgement added","definition":"A severely abnormal form; it adds horror or disapproval that the neutral scientific term avoids.","definitionCN":"指严重畸形的个体；带有惊恐或贬斥，而中性的科学术语不带。"},{"word":"aberration","ipa":"/ˌæbəˈreɪʃn/","tag":"deviation from type","definition":"A departure from the normal type; it may be temporary or chromosomal, and is not always inherited.","definitionCN":"指偏离正常类型；可以是暂时的或染色体的，且不一定遗传。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mut- 'change' + -ant 'the one doing it': the one that has changed.","cn":"mut-「改变」+ -ant「做这件事的（人或物）」：发生了改变的那一个。"},{"en":"The family runs mutate, mutation, mutational, mutable, mutability, mutagen.","cn":"同族词包括 mutate、mutation、mutational、mutable、mutability、mutagen。"},{"en":"Fixed phrases mark the lab sense: mutant strain, mutant gene, mutant allele.","cn":"固定搭配标出实验义：突变株、突变基因、突变等位基因。"},{"en":"A mutant is the carrier; a mutation is the event; a mutagen is the cause.","cn":"突变体是携带者，突变是事件，诱变剂是原因。"},{"en":"In genetics the word pairs with wild type: mutant versus wild-type.","cn":"遗传学中这个词与野生型相对：突变型对野生型。"}],"abstract":[{"en":"Picture one tile in a mosaic replaced by a tile of another color.","cn":"想象马赛克中有一块被换成了另一种颜色。"},{"en":"Picture a copied page where one letter changes and the whole sentence reads differently.","cn":"想象一页抄稿中有一个字母被改，整句读起来就不同了。"},{"en":"Picture a key cut with one extra notch that no longer fits the old lock.","cn":"想象一把钥匙多刻了一个齿，再也插不进原来的锁。"}]},"examples":[{"en":"The mutant was isolated because its roots grew twice as deep.","cn":"这株突变体被单独分离出来，因为它的根长得有两倍深。"},{"en":"Researchers compared the mutant with the wild type under salt stress.","cn":"研究人员在盐胁迫下比较了突变体与野生型。"},{"en":"A single mutant can change the direction of a breeding program.","cn":"一个突变体就能改变一个育种计划的方向。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「缪坦特」——像被换过一块的拼图，样子和同伴不一样 → 突变体","word":"mutant"},"root":"拉丁 mutare「改变」的现在分词 mutans（词干 mutant-）；mutare 的更深词根属重构，一说与「交换」义相关。","sensesIntro":{"en":"Eight senses follow one carrier: a gene changes, and the changed organism is then named in the lab, in the field, in medicine, in farming, in metaphor and in fiction.","cn":"八个义项围绕同一个携带者展开：基因改变之后，这个被改变的生物体依次在实验室、田间、医学、农业、比喻与虚构中获得名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seedling in a tray looks different from its siblings.","cn":"核心意象：托盘里有一株苗和同批的苗长得不一样。"},"chain":["GENE CHANGED","TRAIT SHOWN","CARRIER NAMED","STOCK KEPT","STRAIN USED","LABEL EXTENDED"],"branches":[{"senses":"S1 · S3","en":"CARRIER AND PHENOTYPE: the basic noun and the visible individual are two views of the same organism.","cn":"携带者与表型：基本名词与可见个体是同一生物体的两个视角。"},{"senses":"S2 · S5 · S6","en":"LAB, CLINIC AND FARM: the changed organism becomes a stored strain, a microbial stock or a breeding product.","cn":"实验室、临床与农场：被改变的生物体成为保存品系、微生物菌株或育种产品。"},{"senses":"S4","en":"ADJECTIVAL SHIFT: the word moves from the whole organism to its gene, protein or cell.","cn":"形容词转移：这个词从整个生物体移到它的基因、蛋白质或细胞。"},{"senses":"S7","en":"METAPHOR: any departure from the standard pattern can be called a mutant.","cn":"比喻：任何偏离标准模式的东西都可以被称为异类。"},{"senses":"S8","en":"FICTION: popular stories turn the mutation into a source of power.","cn":"虚构：流行故事把突变变成能力的来源。"}]},"affixes":{"intro":{"en":"Mutant is a Latin participial form: the root mut- supplies 'change' and the suffix -ant marks the one undergoing or doing it.","cn":"mutant 是拉丁分词形式：词根 mut- 提供「改变」，后缀 -ant 标记正在经历或实施这一动作的人或物。"},"latinIntro":{"en":"Latin mutare gives the family mutate, mutation, mutable and mutant; the same verb's participle is the direct source of the English adjective.","cn":"拉丁 mutare 衍生 mutate、mutation、mutable 与 mutant；同一动词的分词就是英语形容词的直接来源。"},"items":[{"word":"mut-","structure":"Latin mutare (to change) used as a root","meaning":"change; exchange","meaningCN":"改变；交换","example":"The root appears in mutate and mutation.","exampleCN":"这个词根出现在 mutate 与 mutation 中。"},{"word":"-ant","structure":"Latin present participle ending -ans, -ant-","meaning":"the one doing or undergoing an action","meaningCN":"正在做或经历某动作的人或物","example":"Mutant literally means 'the changing one'.","exampleCN":"mutant 字面义就是「正在改变的那一个」。"},{"word":"mutate","structure":"mut- + -ate (verb-forming suffix)","meaning":"to undergo or cause a genetic change","meaningCN":"发生突变；使发生突变","example":"The virus mutates under drug pressure.","exampleCN":"病毒在药物压力下发生突变。"},{"word":"mutation","structure":"mutat- + -ion (action or result)","meaning":"the act or result of changing","meaningCN":"改变的动作或结果","example":"One mutation changed the coat color.","exampleCN":"一个突变改变了毛色。"},{"word":"mutational","structure":"mutation + -al (relating to)","meaning":"relating to a mutation","meaningCN":"与突变相关的","example":"Mutational load can reduce fitness.","exampleCN":"突变负荷可能降低适合度。"},{"word":"mutable","structure":"mut- + -able (able to be)","meaning":"able to change","meaningCN":"可改变的；易变的","example":"The trait is mutable under heat stress.","exampleCN":"该性状在热胁迫下可以改变。"},{"word":"mutability","structure":"mutable + -ity (state of)","meaning":"the quality of being changeable","meaningCN":"可变的性质","example":"Mutability is high in short-lived species.","exampleCN":"短寿命物种的可变性很高。"},{"word":"mutagen","structure":"mut- + -gen (producing)","meaning":"an agent that causes mutations","meaningCN":"引起突变的因素","example":"Ultraviolet light is a mutagen.","exampleCN":"紫外线是一种诱变剂。"},{"word":"mutagenesis","structure":"mutagen + -esis (process)","meaning":"the process of producing mutations","meaningCN":"诱变过程","example":"The lab studies mutagenesis in bacteria.","exampleCN":"该实验室研究细菌的诱变过程。"}],"latinEntries":[{"word":"mutare","structure":"mutare, muto, mutavi, mutatum (verb, first conjugation)","meaning":"to change, alter, exchange","meaningCN":"改变；更动；交换"},{"word":"mutans","structure":"mutans, mutantis (present participle of mutare)","meaning":"changing; the changing one","meaningCN":"正在改变的；正在改变的那一个"},{"word":"mutuus","structure":"mutuus, mutua, mutuum (adjective)","meaning":"mutual, exchanged","meaningCN":"相互的；交换的"},{"word":"mutatio","structure":"mutatio, mutationis (noun, third declension)","meaning":"a change, alteration","meaningCN":"改变；更动"}]}},{"word":"variation","ipa_uk":"/ˌværiˈeɪʃn/","ipa_us":"/ˌveriˈeɪʃn/","definition_zh":"变化；变动；变异；变体；变奏；偏差","definition_en":"the act or fact of changing, or a form that differs from another","core_image":"同一段旋律换了几种伴奏，主题仍在，外形却不断改变","scene":"合唱团把同一段旋律换了几种伴奏重新排练。指挥说：The theme returns as a variation in the final movement.","sceneCN":"这里指「变奏」（第 4 个义项：同一主题经过节奏、和声或音型改变后的再次呈现）；句意为主题在末乐章以变奏形式再次出现。","pos":[{"tag":"n.","zh":"变化；变动；变异；变体；变奏；偏差（可数或不可数，复数 variations）"}],"collocations":[{"phrase":"genetic variation","zh":"遗传变异"},{"phrase":"seasonal variation","zh":"季节性变化"},{"phrase":"slight variation","zh":"细微变化"},{"phrase":"variation in temperature","zh":"温度变化"},{"phrase":"wide variation","zh":"大幅差异"},{"phrase":"cultural variation","zh":"文化差异"},{"phrase":"variation on a theme","zh":"主题变奏"}],"forms":[{"label":"复数","form":"variations"},{"label":"相关动词","form":"vary（变化；使不同）"},{"label":"相关形容词","form":"variable（可变的；变量）"},{"label":"相关名词（可变性）","form":"variability（可变性）"},{"label":"相关形容词（变异的）","form":"variational（变分的；变异的）"},{"label":"同根名词（变体）","form":"variant（变体）"}],"derivatives":[{"word":"vary","pos":"v.","zh":"变化；使多样化"},{"word":"variable","pos":"adj./n.","zh":"可变的 / 变量"},{"word":"variability","pos":"n.","zh":"可变性；变异性"},{"word":"variant","pos":"n./adj.","zh":"变体 / 不同的"},{"word":"various","pos":"adj.","zh":"各种各样的"},{"word":"variously","pos":"adv.","zh":"以不同方式；分别地"}],"senses":[{"no":"01","title":"The fact of changing","titleCN":"变化的事实","definition":"the fact or state of being different at different times","definitionCN":"在不同时间呈现不同状态的事实","example":"Prices show wide variation from store to store.","exampleCN":"各家商店的价格差异很大。","why":"Variation begins as the abstract noun of vary: it names the state of not staying the same.","whyCN":"variation 最初是 vary 的抽象名词，命名的是「不保持不变」这一状态。"},{"no":"02","title":"Biological differences among individuals","titleCN":"生物个体间的差异","definition":"differences in traits or genes among members of one species","definitionCN":"同一物种成员在性状或基因上的差异","example":"Color variation helps the moths hide on different bark.","exampleCN":"颜色变异帮助蛾子躲在不同树皮上。","why":"Biology counts differences among individuals of one species, so the abstract noun becomes a measurable property of populations.","whyCN":"生物学统计同一物种个体间的差异，于是这个抽象名词变成群体的一种可测属性。"},{"no":"03","title":"A differing form or version","titleCN":"变体；不同的形式","definition":"a form of something that differs from the usual one","definitionCN":"与通常形式不同的一个版本","example":"The recipe has a vegetarian variation.","exampleCN":"这道菜有一个素食版本。","why":"When the abstract change is treated as a thing, it becomes a version you can choose.","whyCN":"当抽象的变化被当成一个东西，它就变成一个可以选择的具体版本。"},{"no":"04","title":"Musical variation","titleCN":"变奏","definition":"a passage in which a theme is repeated with changed rhythm, harmony or figuration","definitionCN":"主题以改变的节奏、和声或音型重复出现的段落","example":"The theme returns as a variation in the final movement.","exampleCN":"主题在末乐章以变奏形式再次出现。","why":"Music turns the idea of a changed form into a genre: the theme is kept while its surface is rewritten.","whyCN":"音乐把「改变形式」的观念发展成一种体裁：主题保留，表面被重写。"},{"no":"05","title":"A measured deviation","titleCN":"测量偏差","definition":"a difference between a measured value and a standard or expected value","definitionCN":"测量值与标准值或预期值之间的差异","example":"The instrument shows a variation of two degrees.","exampleCN":"仪器显示出两度的偏差。","why":"In measurement the abstract fact of difference is quantified as a deviation from a standard.","whyCN":"在测量中，抽象的差异被量化为偏离标准的一个数值。"},{"no":"06","title":"Degree or extent of change","titleCN":"变化幅度","definition":"the amount or range of difference in something","definitionCN":"某事物差异的大小或范围","example":"There is little variation in rainfall between the two seasons.","exampleCN":"两个季节之间的降雨量变化很小。","why":"The noun can name not a version but the size of the difference, which is why it appears with wide, slight and little.","whyCN":"这个名词也可以不指某个版本，而指差异的大小，所以常与「大、微小、几乎没有」这类词连用。"},{"no":"07","title":"Calculus of variations","titleCN":"变分法","definition":"the branch of mathematics that finds functions making an integral stationary","definitionCN":"求使积分取驻值的函数的数学分支","example":"The calculus of variations finds the path of least energy.","exampleCN":"变分法求出能量最小的路径。","why":"Mathematics fixes the word for the problem of finding a function that makes an integral stationary, a specialized descendant of 'change'.","whyCN":"数学用这个词固定表示「求使积分取驻值的函数」这一问题，是「变化」义的专门化后裔。"},{"no":"08","title":"Language variation","titleCN":"语言变异","definition":"structured differences in speech between groups or situations","definitionCN":"不同群体或场合之间言语的系统性差异","example":"Sociolinguists study variation between speakers of the same city.","exampleCN":"社会语言学家研究同一城市不同说话者之间的变异。","why":"Language changes by group and situation, so the same noun names patterned differences in speech.","whyCN":"语言因群体与场合而变化，因此同一个名词也用来指言语中有规律的差异。"}],"etymology":{"intro":{"en":"Variation comes from Latin variatio, from variare 'to change', itself from varius 'varied, various'. It reached English through Old French in the fourteenth century. Dates are approximate.","cn":"variation 来自拉丁 variatio，出自 variare「改变」，而 variare 又出自 varius「多样的、不同的」。它经古法语在 14 世纪进入英语。年代均为约数。"},"items":[{"era":"LATIN VARIARE","en":"Variare meant 'to change, alter, make different'. Its noun variatio named a difference or a changing, and English took the word through French variation.","cn":"variare 意为「改变、更动、使不同」。其名词 variatio 指差异或改变，英语经法语 variation 借入。"},{"era":"LATIN VARIUS","en":"Varius meant 'variegated, various, different'. It is the adjective behind vary, various, variety and variable.","cn":"varius 意为「杂色的、多样的、不同的」，是 vary、various、variety 与 variable 背后的形容词。"},{"era":"MIDDLE ENGLISH","en":"Variation is recorded in English in the fourteenth century with the sense 'difference, divergence'. The older spelling kept the French ending -acioun.","cn":"variation 在 14 世纪见于英语，义为「差异、偏离」。较早拼写保留了法语词尾 -acioun。"},{"era":"MUSICAL SENSE","en":"The musical sense, a repeat of a theme with altered detail, developed in the sixteenth century and became a standard form in the Baroque era.","cn":"音乐义项指主题以改变细节的方式重复，16 世纪发展起来，在巴洛克时期成为标准形式。"},{"era":"SCIENTIFIC SENSE","en":"The biological and statistical senses expanded in the nineteenth and twentieth centuries, when variation became something counted and measured.","cn":"生物学与统计学的义项在 19 至 20 世纪扩展，variation 从此成为可以计数和测量的对象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the origin of Latin varius is disputed; one account links it to varus 'bent, crooked', another to a different Indo-European root, so the deeper etymology is a reconstruction.","cn":"来源不确定（词根）：拉丁 varius 的来源有争议，一说与 varus「弯曲的」相关，一说来自另一印欧词根，更深词源属重构形式。"}]},"similar":{"note":{"en":"Group one holds words of the same vary family that differ in grammatical role; group two holds near neighbours that also describe difference.","cn":"第一组是同出 vary 词族、但语法角色不同的词；第二组是同样描述差异的邻近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"variant","ipa":"/ˈværiənt/","tag":"a countable version","definition":"A specific version that differs from the standard; variation may name the abstract fact or the whole range.","definitionCN":"指一个具体的、与标准不同的版本；variation 可指抽象事实或整个差异范围。"},{"word":"variance","ipa":"/ˈværiəns/","tag":"statistical term","definition":"A precise statistical measure of spread around a mean; it is a number, not a general difference.","definitionCN":"指围绕均值离散程度的精确统计量，是一个数值，而非泛泛的差异。"},{"word":"variety","ipa":"/vəˈraɪəti/","tag":"many kinds","definition":"The quality of including many different kinds, or a cultivated kind of plant; it stresses plurality, not change over time.","definitionCN":"指包含许多不同种类的性质，或栽培品种；强调多样，而非随时间改变。"},{"word":"variate","ipa":"/ˈværiət/","tag":"a statistical variable","definition":"A random variable in statistics; it looks like variant but belongs to mathematical vocabulary.","definitionCN":"统计学中的随机变量；外形像 variant，但属数学词汇。"}]},{"heading":"NEAR MEANING","entries":[{"word":"change","ipa":"/tʃeɪndʒ/","tag":"the general word","definition":"Any becoming different; variation is narrower and often implies a range or a repeat with differences.","definitionCN":"泛指任何变的不同；variation 更窄，常暗示一个范围或带差异的重复。"},{"word":"fluctuation","ipa":"/ˌflʌktʃuˈeɪʃn/","tag":"up and down","definition":"Irregular rising and falling, especially in numbers; it stresses movement rather than difference of form.","definitionCN":"尤指数值不规则地上下起伏；强调运动，而非形式差异。"},{"word":"deviation","ipa":"/ˌdiːviˈeɪʃn/","tag":"departure from a standard","definition":"A measured departure from a norm or planned course; variation need not imply a norm.","definitionCN":"指对规范或计划路线的偏离，且常可测量；variation 不一定预设一个规范。"},{"word":"diversity","ipa":"/daɪˈvɜːsəti/","tag":"variety in a group","definition":"The presence of many different kinds in a place or group; it is a state, while variation is also the process.","definitionCN":"指某地或某群体中存在许多不同种类，是一种状态；variation 也可指过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vari- 'change' + -ation 'the act of': the act of changing.","cn":"vari-「改变」+ -ation「……的行为」：改变的行为。"},{"en":"Latin varius 'varied' also gives various, variety, variable and vary.","cn":"拉丁 varius「多样的」还衍生 various、variety、variable 与 vary。"},{"en":"Musical variations keep the theme and rewrite its surface.","cn":"音乐变奏保留主题，改写表面。"},{"en":"In statistics, variance measures how far values vary.","cn":"统计中，方差衡量数值偏离多远。"},{"en":"Fixed phrases mark the range: genetic variation, seasonal variation, slight variation.","cn":"固定搭配标出差异范围：遗传变异、季节性变化、细微变化。"}],"abstract":[{"en":"Picture one tune dressed in five different outfits.","cn":"想象同一支曲子换上五套不同的外衣。"},{"en":"Picture a river that keeps its course but changes its width each season.","cn":"想象一条河保持走向，却随季节改变宽度。"},{"en":"Picture fingerprints: one pattern, endless small differences.","cn":"想象指纹：同一个图案，无穷的小差异。"}]},"examples":[{"en":"Genetic variation is the raw material of natural selection.","cn":"遗传变异是自然选择的原材料。"},{"en":"The study found wide variation in how quickly the drug works.","cn":"研究发现药物起效快慢存在很大差异。"},{"en":"The composer wrote a set of variations on a folk song.","cn":"作曲家写了一组基于民歌的变奏曲。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「哇瑞」——同一首歌哇地换了个唱法，还是那首歌 → 变奏、变化","word":"variation"},"root":"拉丁 variare「改变」+ -tio（名词后缀），出自 varius「多样的、不同的」；varius 的更深来源存疑，一说与 varus「弯曲的」相关，属重构形式。","sensesIntro":{"en":"Eight senses follow one idea: something stays recognisable while its form or amount changes, from genes to music to mathematics.","cn":"八个义项沿同一个观念展开：某事物保持可辨识，而形式或数量在变，从基因一直到音乐与数学。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same theme heard through different arrangements.","cn":"核心意象：同一主题经过不同编排被听见。"},"chain":["SAME CORE","DIFFERENT FORM","COUNTED DIFFERENCE","MEASURED DEVIATION","STYLED REPEAT","GROUP PATTERN"],"branches":[{"senses":"S1 · S6","en":"GENERAL CHANGE AND ITS AMOUNT: the plain fact of changing, and the size of that change.","cn":"总体变化及其幅度：变化这一朴素事实，以及变化的规模。"},{"senses":"S2 · S8","en":"POPULATIONS AND SPEAKERS: differences among organisms and among language users are both counted as variation.","cn":"群体与说话者：生物个体间的差异与语言使用者之间的差异都被计为变异。"},{"senses":"S3 · S4","en":"A VERSION AND A REWRITE: a chosen version, and a theme deliberately restated with changes.","cn":"版本与重写：一个是可选的具体版本，一个是主题被有意改变后重述。"},{"senses":"S5","en":"MEASUREMENT: difference is turned into a deviation from a standard value.","cn":"测量：差异被转化为相对标准值的偏差。"},{"senses":"S7","en":"MATHEMATICS: the word is fixed as the name of a variational problem.","cn":"数学：这个词被固定为一个变分问题的名称。"}]},"affixes":{"intro":{"en":"Variation combines the Latin root vari- 'change, varied' with the noun suffix -ation, which names an action or its result.","cn":"variation 把拉丁词根 vari-「改变、多样」与名词后缀 -ation 结合，后者表示动作或其结果。"},"latinIntro":{"en":"Latin variare and its adjective varius supply the whole family: vary, various, variety, variable, variance and variation.","cn":"拉丁 variare 及其形容词 varius 提供整个词族：vary、various、variety、variable、variance 与 variation。"},"items":[{"word":"vari-","structure":"Latin varius (varied, different) used as a root","meaning":"varied; different","meaningCN":"多样的；不同的","example":"The root opens various and variety.","exampleCN":"这个词根出现在 various 与 variety 开头。"},{"word":"-ation","structure":"Latin -atio, -ation- (action or result)","meaning":"the act or result of doing something","meaningCN":"做某事的行为或结果","example":"Variation is the act or result of varying.","exampleCN":"variation 就是变化的行为或结果。"},{"word":"vary","structure":"vari- + -y (verb ending from French -ier)","meaning":"to change or make different","meaningCN":"变化；使不同","example":"Temperatures vary across the valley.","exampleCN":"山谷各处的温度不同。"},{"word":"variable","structure":"vari- + -able (able to be)","meaning":"able to change; a quantity that can change","meaningCN":"可变的；变量","example":"Rainfall is the least variable factor.","exampleCN":"降雨是最不稳定的因素。"},{"word":"variability","structure":"variable + -ity (state of)","meaning":"the quality of being variable","meaningCN":"可变的性质","example":"Variability in yield worries farmers.","exampleCN":"产量的不稳定性让农民担忧。"},{"word":"variant","structure":"vari- + -ant (present participle ending)","meaning":"a differing form","meaningCN":"不同的形式；变体","example":"A new variant spread through the city.","exampleCN":"一个新变体在城市中传播。"},{"word":"variance","structure":"vari- + -ance (state or quality)","meaning":"difference; a statistical measure of spread","meaningCN":"差异；统计上的方差","example":"The variance of the sample was small.","exampleCN":"样本的方差很小。"},{"word":"various","structure":"vari- + -ous (full of)","meaning":"of several different kinds","meaningCN":"各种各样的","example":"Various species share the pond.","exampleCN":"多种物种共享这个池塘。"},{"word":"variation","structure":"vari- + -ation","meaning":"the act of changing or a differing form","meaningCN":"变化的行为或不同的形式","example":"Seasonal variation reshapes the coast.","exampleCN":"季节性变化重塑海岸。"}],"latinEntries":[{"word":"variare","structure":"variare, vario, variavi, variatum (verb, first conjugation)","meaning":"to change, make different","meaningCN":"改变；使不同"},{"word":"varius","structure":"varius, varia, varium (adjective)","meaning":"varied, various, spotted","meaningCN":"多样的；杂色的"},{"word":"varietas","structure":"varietas, varietatis (noun, third declension)","meaning":"variety, difference","meaningCN":"多样性；差异"},{"word":"variabilis","structure":"variare + -bilis (able to be)","meaning":"changeable","meaningCN":"可改变的"}]}},{"word":"variant","ipa_uk":"/ˈværiənt/","ipa_us":"/ˈveriənt/","definition_zh":"变体；变种；变异株；异体；不同的","definition_en":"a form or version that differs from the standard one, or differing from a standard","core_image":"同一份说明书的两个版本，页边多了几处不同的批注","scene":"同一份说明书在两个城市印出了两种版式。编辑指着南方版说：The southern edition uses a variant of the same logo.","sceneCN":"这里指「变体／略有不同的版本」（第 1 个义项：与标准形式不同的一个版本）；句意为南方版使用了同一标志的一个变体。","pos":[{"tag":"n.","zh":"变体；变种；变异株；异体（可数，复数 variants）"},{"tag":"adj.","zh":"不同的；变异的；替代的"}],"collocations":[{"phrase":"genetic variant","zh":"遗传变异型"},{"phrase":"new variant","zh":"新变体；新变异株"},{"phrase":"variant form","zh":"变体形式"},{"phrase":"spelling variant","zh":"拼写异体"},{"phrase":"variant of concern","zh":"值得关注的变异株"},{"phrase":"common variant","zh":"常见变异型"},{"phrase":"variant name","zh":"异名；别名"}],"forms":[{"label":"复数","form":"variants"},{"label":"比较级（形容词）","form":"more variant"},{"label":"最高级（形容词）","form":"most variant"},{"label":"相关名词（变化）","form":"variation（变化；变异）"},{"label":"相关动词","form":"vary（变化）"},{"label":"相关名词（可变性）","form":"variability（可变性）"}],"derivatives":[{"word":"vary","pos":"v.","zh":"变化；使不同"},{"word":"variation","pos":"n.","zh":"变化；变异；变奏"},{"word":"variable","pos":"adj./n.","zh":"可变的 / 变量"},{"word":"variability","pos":"n.","zh":"可变性；变异性"},{"word":"various","pos":"adj.","zh":"各种各样的"},{"word":"invariant","pos":"adj./n.","zh":"不变的 / 不变量"}],"senses":[{"no":"01","title":"A differing version","titleCN":"变体；略有不同的版本","definition":"a version of something that differs in some details from the standard","definitionCN":"在某些细节上与标准不同的一个版本","example":"The southern edition uses a variant of the same logo.","exampleCN":"南方版使用了同一标志的一个变体。","why":"Variant treats difference as a countable thing: one standard, and beside it another version.","whyCN":"variant 把差异当成可数的东西：有一个标准，旁边另有某个版本。"},{"no":"02","title":"A genetic variant","titleCN":"遗传变异型","definition":"a version of a gene or DNA sequence that differs from the reference","definitionCN":"与参照序列不同的基因或脱氧核糖核酸序列版本","example":"This genetic variant lowers the risk of heart disease.","exampleCN":"这种遗传变异型降低心脏病风险。","why":"Genetics applies the general idea of a differing version to a segment of DNA, counted against a reference genome.","whyCN":"遗传学把「不同版本」的一般观念用到一段脱氧核糖核酸上，以参照基因组为基准来计数。"},{"no":"03","title":"A viral variant","titleCN":"病毒变异株","definition":"a virus lineage that carries a set of mutations distinguishing it from others","definitionCN":"携带一组突变、因而与其他谱系不同的病毒谱系","example":"The new variant spreads faster but causes milder illness.","exampleCN":"新变异株传播更快，但致病较轻。","why":"Public health needs a countable label for lineages, so the general word becomes the standard term for a mutated virus.","whyCN":"公共卫生需要给谱系一个可数的标签，于是这个一般词成为指变异病毒的标准术语。"},{"no":"04","title":"A spelling variant","titleCN":"拼写异体","definition":"an accepted alternative spelling of the same word","definitionCN":"同一个词被接受的另一种拼写","example":"The dictionary lists both spellings as variants.","exampleCN":"词典把两种拼写都列为异体。","why":"Language tolerates two written forms of one word, and the noun marks them as equal versions rather than errors.","whyCN":"语言容许同一个词有两种书写形式，这个名词把它们标为平等的版本，而非错误。"},{"no":"05","title":"An alternative product version","titleCN":"产品的替代版本","definition":"a model or configuration of a product that differs from the main one","definitionCN":"与主版本不同的产品型号或配置","example":"The cheaper variant lacks the heated seats.","exampleCN":"较便宜的版本没有加热座椅。","why":"Manufacturers sell one design in several configurations, and each configuration is a variant of the same model.","whyCN":"厂商把同一设计做成多种配置，每种配置都是同一型号的一个变体。"},{"no":"06","title":"A textual variant","titleCN":"文本异文","definition":"a reading in a manuscript or edition that differs from another reading","definitionCN":"手稿或版本中与另一读法不同的文字","example":"Editors recorded every variant across the surviving copies.","exampleCN":"编辑记录了现存各本中的每一处异文。","why":"Manuscripts of one work drift apart, and scholarship needs a word for each differing reading.","whyCN":"同一作品的手稿会彼此偏离，学术研究需要一个词来指每一种不同的读法。"},{"no":"07","title":"Differing as an adjective","titleCN":"不同的（形容词用法）","definition":"showing variation from a standard form","definitionCN":"表现出与标准形式不同的","example":"A variant reading changes the meaning of the line.","exampleCN":"一个不同的读法会改变这一行的意思。","why":"As an adjective the word describes the form itself rather than naming a version as a noun.","whyCN":"作形容词时，这个词描述形式本身，而不是把某个版本作为名词命名出来。"},{"no":"08","title":"A nonstandard form","titleCN":"非标准形式","definition":"a form used by some speakers but not accepted as the standard","definitionCN":"被部分使用者采用、但未被接受为标准的形式","example":"The teacher marked the variant as acceptable but informal.","exampleCN":"老师把这个非标准形式标为可接受但不正式。","why":"Once a standard is fixed, everything beside it is called a variant, whether or not it is wrong.","whyCN":"一旦标准被固定，旁边的一切都被称为变体，不论它是否错误。"}],"etymology":{"intro":{"en":"Variant comes from Latin variantem, the present participle of variare 'to change', and entered English through French in the eighteenth century. The genetic and viral senses are modern. Dates are approximate.","cn":"variant 来自拉丁 variantem，即 variare「改变」的现在分词，经法语在 18 世纪进入英语。遗传学与病毒学的义项属现代用法。年代均为约数。"},"items":[{"era":"LATIN VARIARE","en":"Variare 'to change' has the present participle varians, variant-. English variant is this participle used as adjective and noun.","cn":"variare「改变」的现在分词是 varians（词干 variant-）。英语 variant 就是这个词形，兼作形容词与名词。"},{"era":"LATIN VARIUS","en":"The verb rests on varius 'varied, various', the same adjective behind variety and various.","cn":"这个动词建立在 varius「多样的、不同的」之上，同一形容词也衍生 variety 与 various。"},{"era":"FRENCH AND ENGLISH","en":"French variant passed into English in the eighteenth century as a term for a differing form, especially in printing and manuscripts.","cn":"法语 variant 在 18 世纪进入英语，指不同的形式，尤用于印刷与手稿。"},{"era":"SCIENTIFIC SENSE","en":"In the twentieth century the word was adopted for differing gene sequences and, later, for viral lineages.","cn":"20 世纪，这个词被用来指不同的基因序列，后来又指病毒谱系。"},{"era":"MODERN ENGLISH","en":"Modern English uses variant as a neutral noun for any alternative version and as an adjective meaning 'differing'.","cn":"现代英语中 variant 作中性名词指任何替代版本，也作形容词表示「不同的」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root and first dates): the deeper origin of Latin varius is disputed, and the earliest English use of variant is dated only within the eighteenth century.","cn":"来源不确定（词根与首见年代）：拉丁 varius 的更深来源有争议；variant 在英语中的最早使用只能定在 18 世纪之内。"}]},"similar":{"note":{"en":"Group one holds words from the same vary family that are easily swapped; group two holds general words for alternative versions.","cn":"第一组是同出 vary 词族、容易被混用的词；第二组是表示替代版本的一般词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"variation","ipa":"/ˌværiˈeɪʃn/","tag":"the abstract process","definition":"The fact or degree of changing; variant is a countable version, while variation may be uncountable.","definitionCN":"指变化的事实或程度；variant 是可数的版本，而 variation 可以不可数。"},{"word":"variety","ipa":"/vəˈraɪəti/","tag":"many kinds","definition":"A range of different kinds, or a cultivated plant kind; it does not mean one alternative version.","definitionCN":"指多种不同种类，或栽培品种；不表示某一个替代版本。"},{"word":"variance","ipa":"/ˈværiəns/","tag":"statistics","definition":"A numerical measure of spread, or a formal disagreement; it is not a physical version.","definitionCN":"指离散程度的数值，或正式分歧；不是具体的版本。"},{"word":"variate","ipa":"/ˈværiət/","tag":"random variable","definition":"A statistical variable; the spelling differs by one letter but the field is mathematics.","definitionCN":"指统计变量；拼写只差一个字母，但所属领域是数学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"version","ipa":"/ˈvɜːʃn/","tag":"general word","definition":"Any form of something from a particular point of view; it is broader and needs no standard.","definitionCN":"指从某一角度看某事物的任一形式；范围更广，也不预设标准。"},{"word":"form","ipa":"/fɔːm/","tag":"shape or type","definition":"The shape or arrangement of something; it names structure rather than difference from a standard.","definitionCN":"指事物的形状或安排；命名结构，而非与标准的差异。"},{"word":"strain","ipa":"/streɪn/","tag":"biological lineage","definition":"A genetic lineage within a species; in microbiology it is close to variant but usually implies a cultured stock.","definitionCN":"指物种内的一个遗传谱系；在微生物学中接近 variant，但通常暗示培养的品系。"},{"word":"edition","ipa":"/ɪˈdɪʃn/","tag":"published form","definition":"One published form of a text; a variant is a differing reading, while an edition is the whole printing.","definitionCN":"指文本的一个出版形式；variant 是一处不同读法，edition 是整个印本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vari- 'different' + -ant 'the one being': the one that differs.","cn":"vari-「不同」+ -ant「处于某种状态的那一个」：不同的那一个。"},{"en":"The family runs vary, variation, variable, variability, various.","cn":"同族词包括 vary、variation、variable、variability、various。"},{"en":"Fixed phrases mark the technical senses: genetic variant, new variant, spelling variant.","cn":"固定搭配标出专业义：遗传变异型、新变异株、拼写异体。"},{"en":"A variant is one countable version; variation is the fact or range of difference.","cn":"variant 是一个可数的版本；variation 是差异的事实或范围。"},{"en":"In manuscripts, editors list variants; in genetics, databases list variants.","cn":"在手稿研究中，编辑列出异文；在遗传学中，数据库列出变异型。"}],"abstract":[{"en":"Picture two keys that open the same door but have different notches.","cn":"想象两把钥匙能开同一扇门，齿形却不同。"},{"en":"Picture one song released in a radio cut and a longer album cut.","cn":"想象同一首歌发行了电台版和更长的专辑版。"},{"en":"Picture a map reprinted with one road renamed.","cn":"想象一张地图重印时有一条路改了名。"}]},"examples":[{"en":"The variant differs from the reference sequence at one position.","cn":"该变异型在参照序列的一个位置上不同。"},{"en":"Both variants of the software are still supported.","cn":"该软件的两个版本仍在维护。"},{"en":"Historians compare variants of the same letter.","cn":"历史学家比较同一封信的不同文本。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「维瑞恩特」——同一个东西换了个版本，像同款衣服的另一种颜色 → 变体","word":"variant"},"root":"拉丁 variare「改变」的现在分词 varians（词干 variant-），出自 varius「多样的」；varius 的更深来源存疑。","sensesIntro":{"en":"Eight senses follow one move: a standard is fixed, and beside it a differing version is counted, whether in genes, viruses, spelling, products or manuscripts.","cn":"八个义项沿同一个动作展开：先有标准，旁边再数出一个不同的版本，可用于基因、病毒、拼写、产品或手稿。"},"semanticMap":{"core":{"en":"CORE IMAGE: two printings of one document with small differences in the margin.","cn":"核心意象：同一份文件的两个印本，页边有细小差别。"},"chain":["A STANDARD","A DIFFERENT COPY","COUNTED VERSION","TECHNICAL LABEL","CATEGORY EXTENDED","ADJECTIVAL USE"],"branches":[{"senses":"S1 · S8","en":"VERSION AND NONSTANDARD FORM: a neutral different version, and one accepted only informally.","cn":"版本与非标准形式：一个是中性的不同版本，一个只在非正式场合被接受。"},{"senses":"S2 · S3","en":"GENES AND VIRUSES: the countable version becomes a DNA sequence or a viral lineage.","cn":"基因与病毒：可数的版本变成一段脱氧核糖核酸序列或一个病毒谱系。"},{"senses":"S4 · S6","en":"WORDS AND TEXTS: spelling and manuscript readings are catalogued as variants.","cn":"文字与文本：拼写与手稿读法被编目为异文。"},{"senses":"S5","en":"PRODUCTS: one design sold in several configurations.","cn":"产品：同一设计以多种配置出售。"},{"senses":"S7","en":"ADJECTIVE: the word describes the differing form itself.","cn":"形容词：这个词直接描述那个不同的形式。"}]},"affixes":{"intro":{"en":"Variant is a Latin present participle in form: vari- supplies the meaning 'different' and -ant marks the thing that differs.","cn":"variant 在形式上是拉丁现在分词：vari- 提供「不同」的意思，-ant 标记那个不同的事物。"},"latinIntro":{"en":"The same Latin verb variare underlies variation, variable and vary; variant is its participial branch.","cn":"同一拉丁动词 variare 支撑 variation、variable 与 vary；variant 是它的分词分支。"},"items":[{"word":"vari-","structure":"Latin varius (varied, different) as a root","meaning":"different; varied","meaningCN":"不同的；多样的","example":"The root opens various and variety.","exampleCN":"这个词根出现在 various 与 variety 开头。"},{"word":"-ant","structure":"Latin present participle ending -ans, -ant-","meaning":"the one that is or does","meaningCN":"处于某状态或做某事的那一个","example":"Variant marks the version that differs.","exampleCN":"variant 标记那个不同的版本。"},{"word":"vary","structure":"vari- + verb ending -y","meaning":"to change or differ","meaningCN":"变化；不同","example":"The two copies vary in one line.","exampleCN":"两个本子在一行上不同。"},{"word":"variation","structure":"vari- + -ation (action or result)","meaning":"the fact of changing","meaningCN":"变化的事实","example":"Variation across the range is wide.","exampleCN":"整个范围内的差异很大。"},{"word":"variable","structure":"vari- + -able (able to be)","meaning":"changeable; a quantity that changes","meaningCN":"可变的；变量","example":"The variable affects the final score.","exampleCN":"这个变量影响最终得分。"},{"word":"variance","structure":"vari- + -ance (state)","meaning":"difference; statistical spread","meaningCN":"差异；统计离散度","example":"The variance between samples was small.","exampleCN":"样本间的方差很小。"},{"word":"variant","structure":"vari- + -ant","meaning":"a differing version","meaningCN":"不同的版本；变体","example":"One variant lacks the final paragraph.","exampleCN":"有一个版本缺少最后一段。"},{"word":"variability","structure":"variable + -ity (state of)","meaning":"the quality of being changeable","meaningCN":"可变的性质","example":"Variability makes forecasting hard.","exampleCN":"多变性使预测困难。"},{"word":"invariant","structure":"in- (not) + variant","meaning":"not changing; a quantity that stays fixed","meaningCN":"不变的；不变量","example":"The ratio is invariant under rotation.","exampleCN":"这个比值在旋转下不变。"}],"latinEntries":[{"word":"variare","structure":"variare, vario, variavi, variatum (verb, first conjugation)","meaning":"to change, make different","meaningCN":"改变；使不同"},{"word":"varians","structure":"varians, variantis (present participle of variare)","meaning":"changing, differing","meaningCN":"正在改变的；有差异的"},{"word":"varius","structure":"varius, varia, varium (adjective)","meaning":"varied, various, spotted","meaningCN":"多样的；杂色的"},{"word":"varietas","structure":"varietas, varietatis (noun, third declension)","meaning":"variety, difference","meaningCN":"多样性；差异"}]}},{"word":"genetic variation","ipa_uk":"/dʒəˈnetɪk ˌværiˈeɪʃn/","ipa_us":"/dʒəˈnetɪk ˌveriˈeɪʃn/","definition_zh":"遗传变异；遗传差异","definition_en":"differences in genes and gene frequencies among individuals of a population","core_image":"同一批种子撒进同一块田，长出的植株却高矮不一、叶色深浅不同","scene":"同一批种子撒在同一块田里，长出的植株却高矮不一。研究员记录：Genetic variation within the population helps it survive drought.","sceneCN":"这里指「群体内部的遗传变异」（第 1 个义项：同一群体个体间基因与等位基因频率的差异）；句意为群体内的遗传变异有助于它度过干旱。","pos":[{"tag":"n.","zh":"遗传变异；遗传差异（不可数；指多种变异时偶用复数 genetic variations）"}],"collocations":[{"phrase":"genetic variation within a population","zh":"群体内部的遗传变异"},{"phrase":"maintain genetic variation","zh":"维持遗传变异"},{"phrase":"loss of genetic variation","zh":"遗传变异的丧失"},{"phrase":"genetic variation and natural selection","zh":"遗传变异与自然选择"},{"phrase":"measure genetic variation","zh":"测量遗传变异"},{"phrase":"natural genetic variation","zh":"天然遗传变异"},{"phrase":"genetic variation in humans","zh":"人类的遗传变异"}],"forms":[{"label":"复数（少见，指多种变异）","form":"genetic variations"},{"label":"相关名词（遗传学）","form":"genetics（遗传学）"},{"label":"相关名词（基因）","form":"gene（基因）"},{"label":"相关名词（变异）","form":"variation（变异；变化）"},{"label":"相关形容词","form":"genetic（遗传的）"},{"label":"反义说法","form":"genetic uniformity（遗传一致性）"}],"derivatives":[{"word":"gene","pos":"n.","zh":"基因"},{"word":"genetics","pos":"n.","zh":"遗传学"},{"word":"geneticist","pos":"n.","zh":"遗传学家"},{"word":"genetic","pos":"adj.","zh":"遗传的；基因的"},{"word":"variation","pos":"n.","zh":"变异；变化"},{"word":"vary","pos":"v.","zh":"变化；使不同"}],"senses":[{"no":"01","title":"Differences within a population","titleCN":"群体内部的遗传变异","definition":"differences in genes and gene frequencies among members of one population","definitionCN":"同一群体成员之间基因与等位基因频率的差异","example":"Genetic variation within the population helps it survive drought.","exampleCN":"群体内的遗传变异有助于它度过干旱。","why":"The phrase joins a cause (genes) to a result (difference), naming the raw diversity that a population already carries.","whyCN":"这个短语把原因（基因）与结果（差异）并置，命名群体已经携带的原始多样性。"},{"no":"02","title":"Differences between individuals","titleCN":"个体之间的基因差异","definition":"genetic differences between two or more individuals","definitionCN":"两个或多个个体之间的基因差异","example":"Genetic variation between the twins came from different mutations.","exampleCN":"这对双胞胎之间的遗传差异来自不同的突变。","why":"At the smallest scale the phrase compares individuals, and any two genomes differ at many positions.","whyCN":"在最小尺度上，这个短语比较个体，而任意两个基因组在许多位置上都有差异。"},{"no":"03","title":"Genetic diversity of a species","titleCN":"物种层面的遗传多样性","definition":"the total genetic diversity carried by a species across its range","definitionCN":"一个物种在其分布范围内携带的全部遗传多样性","example":"The species retains high genetic variation across its mountain range.","exampleCN":"该物种在整条山脉中保持着高度的遗传变异。","why":"Summed over many populations, individual differences become a species-level resource.","whyCN":"把许多群体加总，个体差异就变成物种层面的资源。"},{"no":"04","title":"Heritable variation","titleCN":"可遗传的变异","definition":"variation that can be passed from parents to offspring","definitionCN":"能够由亲代传给后代的变异","example":"Only heritable genetic variation responds to selection.","exampleCN":"只有可遗传的遗传变异才会回应选择。","why":"The adjective genetic narrows variation to what sits in the genes, so it can be inherited.","whyCN":"形容词「遗传的」把变异限定在基因之中，因此它可以被继承。"},{"no":"05","title":"Its sources: mutation and recombination","titleCN":"变异来源：突变与重组","definition":"the new variation produced by mutation, recombination and gene flow","definitionCN":"由突变、重组与基因流动产生的新变异","example":"Mutation creates the genetic variation on which recombination acts.","exampleCN":"突变产生遗传变异，重组再对它起作用。","why":"Variation is not self-generating: the phrase points back to the processes that write new differences into DNA.","whyCN":"变异不会自己产生：这个短语回溯到那些把新差异写进脱氧核糖核酸的过程。"},{"no":"06","title":"A measurable quantity","titleCN":"可测量的量","definition":"a quantity estimated from allele frequencies or trait measurements","definitionCN":"由等位基因频率或性状测量估算出的量","example":"The team measured genetic variation at a thousand sites.","exampleCN":"团队在一千个位点上测量了遗传变异。","why":"Once variation is counted, it becomes a number that can be compared across populations and years.","whyCN":"一旦变异被计数，它就成了可以在群体与年份之间比较的数值。"},{"no":"07","title":"The raw material of evolution","titleCN":"进化的原材料","definition":"the differences that natural selection can act on over generations","definitionCN":"自然选择可以在世代间作用其上的差异","example":"Without genetic variation, a population cannot adapt.","exampleCN":"没有遗传变异，群体就无法适应。","why":"Evolution needs alternatives to sort; genetic variation supplies those alternatives.","whyCN":"进化需要可供筛选的备选，遗传变异提供这些备选。"},{"no":"08","title":"The basis of breeding selection","titleCN":"育种选择的基础","definition":"the variation that breeders use to improve crops or livestock","definitionCN":"育种者用来改良作物或畜禽的变异","example":"Breeders depend on genetic variation to raise yield.","exampleCN":"育种者依靠遗传变异来提高产量。","why":"Artificial selection is natural selection put to work, and it also needs heritable differences to choose among.","whyCN":"人工选择是被投入使用的自然选择，同样需要可遗传的差异可供挑选。"}],"etymology":{"intro":{"en":"Genetic goes back to Greek genesis 'origin, generation', while variation comes from Latin variare 'to change'. The phrase became standard with population genetics in the twentieth century. Dates are approximate.","cn":"genetic 追溯到希腊 genesis「起源、生成」，variation 来自拉丁 variare「改变」。这个短语随 20 世纪的群体遗传学成为标准说法。年代均为约数。"},"items":[{"era":"GREEK GENESIS","en":"Genesis meant 'origin, source, generation'. It comes from gignesthai 'to be born' and is related to genos 'race, kind'.","cn":"genesis 意为「起源、来源、生成」，出自 gignesthai「出生」，与 genos「种族、种类」相关。"},{"era":"GENETIC AND GENETICS","en":"The adjective genetic entered English in the nineteenth century; the noun genetics for the science is generally dated to about 1905 and is associated with William Bateson.","cn":"形容词 genetic 在 19 世纪进入英语；指这门科学的名词 genetics 一般定在 1905 年前后，与 William Bateson 相关。"},{"era":"LATIN VARIARE","en":"Variation comes from Latin variare 'to change' and varius 'varied'; it names difference rather than origin.","cn":"variation 来自拉丁 variare「改变」与 varius「多样的」，命名的是差异，而非起源。"},{"era":"POPULATION GENETICS","en":"The exact phrase genetic variation spread in the early twentieth century with the study of allele frequencies in populations.","cn":"genetic variation 这一确切短语在 20 世纪初随群体中等位基因频率的研究而传播。"},{"era":"MODERN USE","en":"Modern biology treats the phrase as a measurable property and links it to mutation, recombination, gene flow and selection.","cn":"现代生物学把这个短语当作一种可测属性，并把它与突变、重组、基因流动和选择联系起来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and root): the earliest printed use of the full phrase is not established, and the deeper origin of Latin varius is a reconstruction.","cn":"来源不确定（首见年代与词根）：完整短语的最早印刷使用没有定论；拉丁 varius 的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds phrases built on the same gene or variation stock that are easily swapped; group two holds neighbouring concepts that also describe biological difference.","cn":"第一组是同出 gene 或 variation 词干、容易被替换的短语；第二组是同样描述生物差异的邻近概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genetic diversity","ipa":"/dʒəˈnetɪk daɪˈvɜːsəti/","tag":"the state, not the differences","definition":"The variety of genes within a group, viewed as a resource or a state; genetic variation stresses the differences themselves.","definitionCN":"指一个群体内基因的多样，被看作资源或状态；genetic variation 强调差异本身。"},{"word":"genetic difference","ipa":"/dʒəˈnetɪk ˈdɪfrəns/","tag":"pairwise wording","definition":"A difference between two particular genomes; the phrase genetic variation is collective and population-level.","definitionCN":"指两个具体基因组之间的差别；genetic variation 是集体的、群体层面的。"},{"word":"phenotypic variation","ipa":"/ˌfiːnəˈtɪpɪk ˌværiˈeɪʃn/","tag":"visible traits","definition":"Variation in observable traits, which may or may not be genetic; the two are often confused.","definitionCN":"指可观察性状的变异，可能来自基因也可能不是；两者常被混淆。"},{"word":"genetic mutation","ipa":"/dʒəˈnetɪk mjuːˈteɪʃn/","tag":"the source, not the pool","definition":"A single change in DNA; genetic variation is the accumulated differences that many mutations help create.","definitionCN":"指脱氧核糖核酸中的一次改变；genetic variation 是许多突变共同造成的累积差异。"}]},{"heading":"NEAR MEANING","entries":[{"word":"allele frequency","ipa":"/əˈliːl ˈfriːkwənsi/","tag":"the measure","definition":"The proportion of a particular allele in a population; it is how genetic variation is often quantified.","definitionCN":"指某个等位基因在群体中的比例，是量化遗传变异的常用方式。"},{"word":"gene pool","ipa":"/ˈdʒiːn puːl/","tag":"the store","definition":"The total set of alleles in a population; it is the container that holds the variation.","definitionCN":"指一个群体中全部等位基因的集合，是容纳变异的容器。"},{"word":"polymorphism","ipa":"/ˌpɒliˈmɔːfɪzəm/","tag":"two or more forms","definition":"The presence of two or more distinct forms in a population; it is a pattern, while variation is the general property.","definitionCN":"指群体中存在两种或更多明显形式；它是一种格局，而 variation 是一般属性。"},{"word":"heritability","ipa":"/ˌherɪtəˈbɪləti/","tag":"how much is inherited","definition":"The proportion of trait variation due to genetic differences; it measures the genetic share of variation.","definitionCN":"指性状变异中由基因差异造成的比例，衡量变异里遗传所占的份额。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"gen- 'birth, origin' + -etic 'relating to': relating to what is born from parents.","cn":"gen-「出生、起源」+ -etic「与……相关的」：与从亲代出生相关。"},{"en":"vari- 'different' + -ation 'the act of': the act of differing.","cn":"vari-「不同」+ -ation「……的行为」：表现出差异的行为。"},{"en":"Genetic variation is the raw material; mutation, recombination and gene flow supply it.","cn":"遗传变异是原材料；突变、重组与基因流动提供它。"},{"en":"The phrase pairs with selection: variation is what selection sorts.","cn":"这个短语与选择配对：变异正是选择所筛选的对象。"},{"en":"Measured by allele frequencies, it becomes a number for comparison.","cn":"通过等位基因频率测量，它成为可供比较的数值。"}],"abstract":[{"en":"Picture a field of seedlings of slightly different heights, all from one seed lot.","cn":"想象一块田里的苗高矮略有不同，却都来自同一批种子。"},{"en":"Picture a deck of cards where every hand is dealt a different combination.","cn":"想象一副牌，每一手都发到不同的组合。"},{"en":"Picture a library where each copy of a book has a few handwritten corrections.","cn":"想象一座图书馆，每本书都有几处手写修改。"}]},"examples":[{"en":"Genetic variation lets a population answer a new disease.","cn":"遗传变异让一个群体能够回应一种新疾病。"},{"en":"The island's genetic variation fell after a century of isolation.","cn":"经过一个世纪的隔离，这座岛的遗传变异减少了。"},{"en":"Conservation plans try to protect genetic variation, not just species numbers.","cn":"保护计划试图保护遗传变异，而不只是物种数量。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「基因的变样」——同一批种子长出的苗各有各的样子 → 遗传变异","word":"genetic variation"},"root":"希腊 genesis「起源、生成」（经 genetic）+ 拉丁 variare「改变」与 varius「多样的」；拉丁 genus「出生、族类」为同源词。","sensesIntro":{"en":"Eight senses follow one resource: differences written in genes are counted within individuals, populations and species, then read as evolution's material and as a breeding tool.","cn":"八个义项围绕同一种资源展开：写在基因里的差异，先在个体、群体与物种层面被计数，再被读成进化的材料与育种的工具。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seed lot growing into plants of different heights.","cn":"核心意象：同一批种子长成高低不同的植株。"},"chain":["GENES DIFFER","INDIVIDUALS DIFFER","POPULATION COUNTS","SPECIES STORES","SELECTION ACTS","BREEDING USES"],"branches":[{"senses":"S1 · S2","en":"INDIVIDUAL AND POPULATION: pairwise differences add up to a population property.","cn":"个体与群体：成对的差异累加为群体属性。"},{"senses":"S3 · S6","en":"SPECIES SCALE AND MEASURE: the stored diversity becomes a quantity estimated from samples.","cn":"物种尺度与测量：储存的多样性成为由样本估算的量。"},{"senses":"S4 · S5","en":"HERITABLE AND GENERATED: only inherited variation counts, and mutation plus recombination writes it.","cn":"可遗传与来源：只有可继承的变异才算数，突变与重组把它写入。"},{"senses":"S7","en":"EVOLUTION: selection needs alternatives, and this is the supply.","cn":"进化：选择需要备选，而这就是供应。"},{"senses":"S8","en":"BREEDING: artificial selection puts the same supply to work.","cn":"育种：人工选择让同一供应发挥作用。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek-derived adjective of origin to a Latin-derived noun of difference; both are free words, and the compound is a technical collocation rather than a prefixed root.","cn":"这个短语把希腊来源的「起源」形容词接在拉丁来源的「差异」名词上；两者都是自由词，整个短语是专业搭配，而非前缀加词根。"},"latinIntro":{"en":"The Greek family gives gene, genetics and genetic, while Latin gives variation, variable and vary; Latin genus is a cognate of Greek genos, not its source.","cn":"希腊词族提供 gene、genetics 与 genetic，拉丁词族提供 variation、variable 与 vary；拉丁 genus 与希腊 genos 同源，但不是后者的来源。"},"items":[{"word":"gen-","structure":"Greek genos (race, kind) / gignesthai (to be born)","meaning":"birth; origin; kind","meaningCN":"出生；起源；种类","example":"The element opens gene, genesis and genetics.","exampleCN":"这个成分出现在 gene、genesis 与 genetics 开头。"},{"word":"-etic","structure":"Greek -etikos (relating to)","meaning":"relating to","meaningCN":"与……相关的","example":"Genetic means relating to origin and inheritance.","exampleCN":"genetic 意为与起源和遗传相关。"},{"word":"gene","structure":"gen- + -e (noun ending)","meaning":"a unit of inheritance","meaningCN":"遗传单位","example":"One gene may have many alleles.","exampleCN":"一个基因可以有许多等位基因。"},{"word":"genetics","structure":"genetic + -s (field of study)","meaning":"the science of inheritance","meaningCN":"研究遗传的科学","example":"Genetics began with breeding experiments.","exampleCN":"遗传学始于育种实验。"},{"word":"geneticist","structure":"genetics + -ist (person)","meaning":"a specialist in inheritance","meaningCN":"遗传学专家","example":"The geneticist mapped the trait.","exampleCN":"遗传学家定位了该性状。"},{"word":"vari-","structure":"Latin varius (varied, different)","meaning":"different; varied","meaningCN":"不同的；多样的","example":"The element opens variation and variable.","exampleCN":"这个成分出现在 variation 与 variable 开头。"},{"word":"-ation","structure":"Latin -atio (action or result)","meaning":"the act or result of","meaningCN":"……的行为或结果","example":"Variation is the result of varying.","exampleCN":"variation 是变化的结果。"},{"word":"variation","structure":"vari- + -ation","meaning":"difference; the fact of changing","meaningCN":"差异；变化的事实","example":"Variation in height is easy to see.","exampleCN":"高度的差异很容易看见。"},{"word":"vary","structure":"vari- + verb ending -y","meaning":"to differ or change","meaningCN":"不同；变化","example":"Allele frequencies vary by region.","exampleCN":"等位基因频率因地区而异。"},{"word":"genetic variation","structure":"genetic + variation","meaning":"differences carried in genes","meaningCN":"携带在基因中的差异","example":"Genetic variation is the raw material of selection.","exampleCN":"遗传变异是选择的原材料。"}],"latinEntries":[{"word":"genus","structure":"genus, generis (noun, third declension)","meaning":"birth, origin, kind; a cognate of Greek genos","meaningCN":"出生；起源；种类；与希腊 genos 同源"},{"word":"gignere","structure":"gignere, gigno, genui, genitum (verb, third conjugation)","meaning":"to beget, bring forth","meaningCN":"生育；产生"},{"word":"variare","structure":"variare, vario, variavi, variatum (verb, first conjugation)","meaning":"to change, make different","meaningCN":"改变；使不同"},{"word":"varius","structure":"varius, varia, varium (adjective)","meaning":"varied, various","meaningCN":"多样的；不同的"}]}},{"word":"allele","ipa_uk":"/əˈliːl/","ipa_us":"/əˈliːl/","definition_zh":"等位基因；同一基因位置上的一种替代版本","definition_en":"one of two or more alternative forms of a gene at the same position on a chromosome","core_image":"同一把椅子上放着可替换的坐垫，位置不变，垫子的花色不同","scene":"遗传课上，同一朵花的花色由同一个位置上的两份遗传信息决定。老师说：This plant carries two different alleles for flower color.","sceneCN":"这里指「等位基因」（第 1 个义项：同一基因位置上的一种可替代版本）；句意为这株植物在花色这个基因上携带两个不同的等位基因。","pos":[{"tag":"n.","zh":"等位基因；同一基因座的替代版本（可数，复数 alleles）"}],"collocations":[{"phrase":"dominant allele","zh":"显性等位基因"},{"phrase":"recessive allele","zh":"隐性等位基因"},{"phrase":"mutant allele","zh":"突变等位基因"},{"phrase":"wild-type allele","zh":"野生型等位基因"},{"phrase":"allele frequency","zh":"等位基因频率"},{"phrase":"a pair of alleles","zh":"一对等位基因"},{"phrase":"multiple alleles","zh":"复等位基因"}],"forms":[{"label":"复数","form":"alleles"},{"label":"形容词（等位的）","form":"allelic（等位的；等位基因的）"},{"label":"名词（等位性）","form":"allelism（等位性）"},{"label":"旧称（等位基因）","form":"allelomorph（等位基因，早期术语）"},{"label":"复合名词（频率）","form":"allele frequency（等位基因频率）"},{"label":"复合形容词（多等位的）","form":"multiallelic（多等位的）"}],"derivatives":[{"word":"allelic","pos":"adj.","zh":"等位的；等位基因的"},{"word":"allelism","pos":"n.","zh":"等位性"},{"word":"allelomorph","pos":"n.","zh":"等位基因（早期术语）"},{"word":"multiallelic","pos":"adj.","zh":"多等位的"},{"word":"allele frequency","pos":"n.","zh":"等位基因频率"}],"senses":[{"no":"01","title":"One version of a gene","titleCN":"等位基因（基本义）","definition":"one of the alternative forms that a gene can take at a fixed position on a chromosome","definitionCN":"一个基因在染色体固定位置上可以采取的一种替代形式","example":"This plant carries two different alleles for flower color.","exampleCN":"这株植物在花色这个基因上携带两个不同的等位基因。","why":"The word names a version, not a place: the locus stays the same, while the sequence at that locus differs.","whyCN":"这个词命名的是一个版本，而不是一个位置：基因座不变，该位置上的序列却不同。"},{"no":"02","title":"One member of a pair","titleCN":"成对等位基因中的一方","definition":"one of the two copies of a gene that a diploid organism carries","definitionCN":"二倍体生物携带的两份基因拷贝中的一份","example":"Each parent contributed one allele to the child.","exampleCN":"每个亲代都向孩子贡献了一个等位基因。","why":"Because chromosomes come in pairs, alleles are usually discussed in pairs, one inherited from each parent.","whyCN":"因为染色体成对存在，等位基因通常也成对讨论，一份来自一个亲代。"},{"no":"03","title":"Multiple alleles in a population","titleCN":"复等位基因","definition":"any of three or more alternative forms of the same gene found in a population","definitionCN":"同一基因在群体中出现的三种或更多替代形式之一","example":"Human blood groups depend on multiple alleles at one locus.","exampleCN":"人类血型取决于同一基因座上的复等位基因。","why":"A single individual carries two copies, but a whole population can hold many versions, so the noun extends beyond the pair.","whyCN":"单个个体只携带两份，但整个群体可以拥有许多版本，因此这个名词超出成对的范围。"},{"no":"04","title":"A dominant allele","titleCN":"显性等位基因","definition":"an allele whose effect is visible even when only one copy is present","definitionCN":"只有一份拷贝也能表现出效果的等位基因","example":"The dominant allele produces a dark seed coat.","exampleCN":"这个显性等位基因产生深色种皮。","why":"The allele itself is neutral; 'dominant' describes what happens when it meets a different version in the same cell.","whyCN":"等位基因本身是中性的；「显性」描述的是它与另一版本在同一细胞中相遇时的结果。"},{"no":"05","title":"A recessive allele","titleCN":"隐性等位基因","definition":"an allele whose effect is hidden when a dominant allele is present","definitionCN":"与显性等位基因同时存在时效果被掩盖的等位基因","example":"The recessive allele reappears in the next generation.","exampleCN":"隐性等位基因在下一代重新出现。","why":"A recessive version is still present and still inherited; it is only its visible effect that is covered.","whyCN":"隐性版本仍然存在、仍然可遗传，被盖住的只是它可见的效果。"},{"no":"06","title":"A mutant allele","titleCN":"突变等位基因","definition":"an allele produced by a mutation and differing from the original sequence","definitionCN":"由突变产生、与原始序列不同的等位基因","example":"The mutant allele removes one base from the sequence.","exampleCN":"这个突变等位基因从序列中删去了一个碱基。","why":"New alleles arise by mutation, so the word is also used for the fresh version before it spreads in a population.","whyCN":"新的等位基因由突变产生，因此这个词也用来指在群体中扩散之前的那个新版本。"},{"no":"07","title":"A wild-type allele","titleCN":"野生型等位基因","definition":"the allele regarded as the standard or original form in a population","definitionCN":"在群体中被视为标准或原始形式的等位基因","example":"The wild-type allele restores the normal wing shape.","exampleCN":"野生型等位基因恢复了正常的翅形。","why":"Once a mutant is known, the common version needs a name, and 'wild type' marks the reference against which change is measured.","whyCN":"一旦已知某个突变，常见版本就需要一个名称，「野生型」标记出衡量变化的参照。"},{"no":"08","title":"Allele frequency","titleCN":"等位基因频率（群体层面）","definition":"the proportion of a particular allele among all copies of that gene in a population","definitionCN":"某一特定等位基因在群体中该基因全部拷贝里所占的比例","example":"The allele frequency rose after the drought.","exampleCN":"干旱之后该等位基因的频率上升了。","why":"Population genetics turns the version into a share, which is why the word appears in frequency counts and not only in pedigrees.","whyCN":"群体遗传学把这个版本变成一个占比，因此这个词不仅出现在系谱中，也出现在频率统计中。"}],"etymology":{"intro":{"en":"Allele is a shortened form of allelomorph, a term coined in the early twentieth century from Greek allelon 'one another' and morphe 'form'. It is Greek in origin, with no Latin source. Dates are approximate.","cn":"allele 是 allelomorph 的缩短形式；后者于 20 世纪初由希腊 allelon「彼此」与 morphe「形式」构成。它源自希腊语，没有拉丁语来源。年代均为约数。"},"items":[{"era":"GREEK ALLELON","en":"Allēlon means 'of one another, mutually'. It marks the relation between alternative versions that occupy the same place.","cn":"allēlon 意为「彼此的、相互的」，标记占据同一位置的不同版本之间的关系。"},{"era":"GREEK MORPHE","en":"Morphē meant 'form, shape'. In scientific compounds it names a physical or structural form.","cn":"morphē 意为「形式、形状」，在科学复合词中命名物理或结构形式。"},{"era":"ALLELOMORPH","en":"The compound allelomorph was coined in the early 1900s, generally associated with William Bateson, for alternative forms of a gene.","cn":"复合词 allelomorph 于 1900 年代初被造出，一般与 William Bateson 相关，用来指基因的替代形式。"},{"era":"ALLELE","en":"Allele is the shortened form and became the standard term in genetics; the longer allelomorph survives mainly in historical writing.","cn":"allele 是缩短形式，后来成为遗传学的标准术语；较长的 allelomorph 主要留在历史文献中。"},{"era":"MODERN USE","en":"Modern genetics extends the word to allele frequencies, multiple alleles and reference alleles such as the wild type.","cn":"现代遗传学把这个词扩展到等位基因频率、复等位基因以及野生型等参照版本。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and root): the exact coinage date of allelomorph is not settled, and the deeper origin of Greek allos 'other' is a reconstruction.","cn":"来源不确定（首见年代与词根）：allelomorph 的确切造词年代未有定论；希腊 allos「其他」的更深来源属重构形式。"}]},"similar":{"note":{"en":"Group one holds forms built on the same Greek elements that are easily confused; group two holds neighbouring genetic terms for position and version.","cn":"第一组是同出希腊成分、容易混淆的形式；第二组是表示位置与版本的邻近遗传学术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"allelomorph","ipa":"/ˈælələmɔːf/","tag":"the older term","definition":"The long historical word for an allele; it is the same concept, not a different kind of gene.","definitionCN":"指等位基因的早期长词；是同一概念，而非另一类基因。"},{"word":"allelic","ipa":"/əˈliːlɪk/","tag":"the adjective","definition":"Relating to an allele; it describes a relationship, while allele names the version itself.","definitionCN":"指与等位基因相关的；描述关系，而 allele 命名版本本身。"},{"word":"allelism","ipa":"/ˈæləlɪzəm/","tag":"the abstract state","definition":"The state of existing as alternative forms at one locus; it is the abstract noun, not a countable allele.","definitionCN":"指在同一基因座以替代形式存在的状态；是抽象名词，不是可数的等位基因。"},{"word":"allele frequency","ipa":"/əˈliːl ˈfriːkwənsi/","tag":"the measure","definition":"The share of one allele among all copies in a population; it is a number, not the allele.","definitionCN":"指某一等位基因在群体全部拷贝中的占比；是一个数值，不是等位基因本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gene","ipa":"/dʒiːn/","tag":"the unit, not its version","definition":"A unit of inheritance at a locus; an allele is one version of that unit.","definitionCN":"指一个基因座上的遗传单位；等位基因是该单位的一个版本。"},{"word":"locus","ipa":"/ˈləʊkəs/","tag":"the position","definition":"The fixed position on a chromosome; alleles occupy a locus but are not the locus.","definitionCN":"指染色体上的固定位置；等位基因占据基因座，但并不等于基因座。"},{"word":"genotype","ipa":"/ˈdʒiːnətaɪp/","tag":"the pair","definition":"The combination of alleles an individual carries; it is the pair, not either member.","definitionCN":"指个体携带的等位基因组合；是成对的组合，而非其中一方。"},{"word":"variant","ipa":"/ˈværiənt/","tag":"broader label","definition":"Any differing version of a sequence; allele is its standard term when the version sits at a known gene locus.","definitionCN":"指序列的任何不同版本；当该版本位于已知基因座时，标准术语就是等位基因。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"allelo- 'one another' + -morph 'form': alternative forms of one another.","cn":"allelo-「彼此」+ -morph「形式」：彼此替代的不同形式。"},{"en":"The family runs allele, allelic, allelism, allelomorph, multiallelic.","cn":"同族词包括 allele、allelic、allelism、allelomorph、multiallelic。"},{"en":"Fixed phrases pair it with dominance: dominant allele, recessive allele.","cn":"固定搭配把它与显隐性配对：显性等位基因、隐性等位基因。"},{"en":"A gene is the position; an allele is one text written at that position.","cn":"基因是位置，等位基因是写在该位置上的一版文字。"},{"en":"Population genetics counts allele frequencies, not individual alleles alone.","cn":"群体遗传学统计等位基因频率，而不只统计单个等位基因。"}],"abstract":[{"en":"Picture one parking space where different cars can park.","cn":"想象同一个车位，可以停不同的车。"},{"en":"Picture one role in a play played by different actors on different nights.","cn":"想象同一出戏里的一个角色，不同夜晚由不同演员扮演。"},{"en":"Picture one socket that accepts several interchangeable parts.","cn":"想象同一个插口可以接上几种可互换的零件。"}]},"examples":[{"en":"A child inherits one allele from each parent.","cn":"孩子从每个亲代各继承一个等位基因。"},{"en":"The two alleles differ by a single base pair.","cn":"这两个等位基因只差一个碱基对。"},{"en":"Selection changed the allele frequencies within a decade.","cn":"选择在十年内改变了等位基因频率。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿利尔」——同一个座位上轮流坐的另一个人 → 等位基因","word":"allele"},"root":"希腊 allelon「彼此」+ morphe「形式」，经早期术语 allelomorph 缩短而来；无拉丁语来源，属纯粹希腊来源的科学复合词。","sensesIntro":{"en":"Eight senses follow one position: a fixed locus accepts alternative versions, and those versions are then paired, counted across a population, and labelled by their effects.","cn":"八个义项围绕同一个位置展开：固定的基因座接受不同版本，这些版本再被成对讨论、在群体中计数，并按效果获得标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seat with interchangeable cushions.","cn":"核心意象：同一个座位上放着可替换的坐垫。"},"chain":["FIXED LOCUS","ALTERNATIVE VERSION","PAIR INHERITED","EFFECT EXPRESSED","POPULATION SHARE","REFERENCE FORM"],"branches":[{"senses":"S1 · S2","en":"VERSION AND PAIR: one alternative form, and the two copies a diploid organism carries.","cn":"版本与成对：一个替代形式，以及二倍体生物携带的两份拷贝。"},{"senses":"S3","en":"MANY VERSIONS: a population can hold more than two forms at one locus.","cn":"多个版本：一个群体在同一基因座可以拥有两种以上的形式。"},{"senses":"S4 · S5","en":"EXPRESSION: dominant and recessive describe what happens when two versions meet.","cn":"表现：显性与隐性描述两个版本相遇时发生什么。"},{"senses":"S6 · S7","en":"ORIGIN AND REFERENCE: mutant versions are new, wild-type versions are the standard.","cn":"来源与参照：突变版本是新的，野生型版本是标准。"},{"senses":"S8","en":"POPULATION: the version becomes a share in a gene pool.","cn":"群体：版本变成基因库中的一个占比。"}]},"affixes":{"intro":{"en":"Allele is built from two Greek combining elements, allelo- 'one another' and -morph 'form'; it is a scientific compound, not a Latin root with suffixes.","cn":"allele 由两个希腊组合成分构成：allelo-「彼此」与 -morph「形式」；它是科学复合词，而非拉丁词根加后缀。"},"latinIntro":{"en":"There is no Latin element here: allēlon and morphē are Greek, and the word was coined inside modern genetics from Greek materials.","cn":"这里没有拉丁成分：allēlon 与 morphē 都是希腊语，这个词是在现代遗传学内部用希腊语材料造出的。"},"items":[{"word":"allelo-","structure":"Greek allēlon (of one another) as a combining form","meaning":"one another; mutually","meaningCN":"彼此；相互","example":"The element marks versions that stand in place of one another.","exampleCN":"这个成分标记彼此替代的版本。"},{"word":"-morph","structure":"Greek morphē (form, shape)","meaning":"form; shape","meaningCN":"形式；形状","example":"The suffix also appears in polymorphic.","exampleCN":"这个后缀也出现在 polymorphic 中。"},{"word":"allele","structure":"allelo- + -morph, shortened","meaning":"an alternative form of a gene","meaningCN":"基因的替代形式","example":"Each allele sits at the same locus.","exampleCN":"每个等位基因都位于同一基因座。"},{"word":"allelic","structure":"allele + -ic (relating to)","meaning":"relating to an allele","meaningCN":"与等位基因相关的","example":"Allelic variation is common in wild populations.","exampleCN":"等位变异在野生群体中很常见。"},{"word":"allelism","structure":"allele + -ism (state or system)","meaning":"the state of being alternative forms","meaningCN":"作为替代形式的状态","example":"Allelism at one locus produces several phenotypes.","exampleCN":"同一基因座的等位性产生几种表型。"},{"word":"allelomorph","structure":"allelo- + -morph","meaning":"the older term for an allele","meaningCN":"等位基因的早期术语","example":"Allelomorph is now mainly historical.","exampleCN":"allelomorph 现在主要见于历史文献。"},{"word":"multiallelic","structure":"multi- (many) + allelic","meaning":"having many alleles","meaningCN":"具有多个等位基因的","example":"Multiallelic loci complicate diagnosis.","exampleCN":"多等位基因的基因座使诊断复杂化。"},{"word":"allele frequency","structure":"allele + frequency","meaning":"the share of one allele in a population","meaningCN":"某一等位基因在群体中的占比","example":"The allele frequency stayed near one half.","exampleCN":"该等位基因频率保持在二分之一附近。"}],"latinEntries":[]}},{"word":"dominant","ipa_uk":"/ˈdɒmɪnənt/","ipa_us":"/ˈdɑːmɪnənt/","definition_zh":"占主导地位的；支配的；显性的；优势种的；属音","definition_en":"ruling or most influential; in genetics, expressed even when only one copy is present","core_image":"一群人里最高的那个人站在前排，后面的人不自觉以他为参照","scene":"家族合影里，几乎每个人的耳垂都连着。祖母指着照片说：The dominant allele for attached earlobes runs through our family.","sceneCN":"这里指「显性的」（第 2 个义项：在杂合状态下仍能表现出来的）；句意为连生耳垂的显性等位基因贯穿我们家族。","pos":[{"tag":"adj.","zh":"占主导地位的；支配的；显性的；最突出的"},{"tag":"n.","zh":"显性性状；显性等位基因；属音（音乐）"}],"collocations":[{"phrase":"dominant allele","zh":"显性等位基因"},{"phrase":"dominant gene","zh":"显性基因"},{"phrase":"dominant trait","zh":"显性性状"},{"phrase":"dominant species","zh":"优势种"},{"phrase":"dominant position","zh":"主导地位"},{"phrase":"dominant role","zh":"主导作用"},{"phrase":"dominant hand","zh":"惯用手"}],"forms":[{"label":"比较级","form":"more dominant"},{"label":"最高级","form":"most dominant"},{"label":"名词（主导地位）","form":"dominance（主导；显性）"},{"label":"动词（支配）","form":"dominate（支配；占优势）"},{"label":"副词","form":"dominantly（主导地）"},{"label":"反义形容词","form":"recessive（隐性的）；subordinate（从属的）"}],"derivatives":[{"word":"dominance","pos":"n.","zh":"主导地位；显性"},{"word":"dominate","pos":"v.","zh":"支配；占优势"},{"word":"domination","pos":"n.","zh":"支配；统治"},{"word":"dominator","pos":"n.","zh":"支配者；优势个体"},{"word":"dominantly","pos":"adv.","zh":"主导地；占优势地"}],"senses":[{"no":"01","title":"Ruling or most influential","titleCN":"占主导地位的","definition":"most powerful, important or influential in a group or situation","definitionCN":"在一个群体或情境中最有力量、最重要或最有影响力的","example":"One firm became dominant in the regional market.","exampleCN":"一家公司在区域市场中占据了主导地位。","why":"The word begins with rule: a dominant thing sets the terms that others follow.","whyCN":"这个词从「统治」开始：占主导的事物设定规则，其他事物随之而行。"},{"no":"02","title":"Genetically dominant","titleCN":"显性的","definition":"expressed in the phenotype even when only one copy of the allele is present","definitionCN":"即使只有一份等位基因拷贝也能在表型中表现","example":"The dominant allele for attached earlobes runs through our family.","exampleCN":"连生耳垂的显性等位基因贯穿我们家族。","why":"In genetics the ruling idea narrows: one version visibly overrules the other in the same cell.","whyCN":"在遗传学中，「统治」的观念被收窄：一个版本在同一细胞中明显压过另一个。"},{"no":"03","title":"The dominant trait or allele","titleCN":"显性性状或显性基因（名词）","definition":"the trait or allele that shows itself when paired with a recessive one","definitionCN":"与隐性版本配对时仍表现自身的性状或等位基因","example":"The dominant appeared in every generation of the pedigree.","exampleCN":"这个显性性状在系谱的每一代都出现。","why":"As a noun the word names the winner of the pair, which is why it can stand alone with 'the'.","whyCN":"作名词时，这个词命名成对中的胜出者，因此可以单独与定冠词连用。"},{"no":"04","title":"The dominant species","titleCN":"优势种","definition":"the species that most affects the structure of a community because of its numbers or size","definitionCN":"因数量或体型而最影响群落结构的物种","example":"Kelp is the dominant species along this coast.","exampleCN":"海带是这一海岸的优势种。","why":"Ecology borrows the political idea of rule: one species shapes the community the way a leading group shapes a society.","whyCN":"生态学借用了政治上的「统治」观念：一个物种塑造群落，正如一个主导群体塑造社会。"},{"no":"05","title":"The majority or prevailing share","titleCN":"占多数的；普遍的","definition":"forming the largest part of a total","definitionCN":"构成总量中最大部分的","example":"Farming is still the dominant use of the valley.","exampleCN":"农业仍是这个山谷最主要的用途。","why":"Numbers replace power: whatever holds the largest share dominates the total.","whyCN":"数量取代了权力：占据最大份额的事物就主导了整体。"},{"no":"06","title":"Visually most prominent","titleCN":"视觉上最突出的","definition":"the feature that draws the eye first in a design or landscape","definitionCN":"在设计或景观中最先吸引视线的部分","example":"The dominant shape in the painting is a dark triangle.","exampleCN":"这幅画中最突出的形状是一个深色三角形。","why":"Attention behaves like a small society: one element takes the lead and organizes the rest.","whyCN":"注意力像一个小社会：一个元素取得领先，并组织其余部分。"},{"no":"07","title":"The dominant note in music","titleCN":"属音","definition":"the fifth degree of a diatonic scale, which strongly pulls toward the tonic","definitionCN":"自然音阶的第五级，强烈趋向主音","example":"The melody rests on the dominant before returning home.","exampleCN":"旋律停在属音上，然后回到主音。","why":"Music uses the same ruling metaphor: the fifth degree governs the pull back to the tonic.","whyCN":"音乐使用同一个「统治」隐喻：第五级主导着回到主音的拉力。"},{"no":"08","title":"Domineering in manner","titleCN":"专横的；好支配的","definition":"trying to control other people in an assertive or arrogant way","definitionCN":"以强势或傲慢的方式试图控制他人","example":"His dominant manner silenced the meeting.","exampleCN":"他专横的举止让会议安静下来。","why":"The adjective can describe a personal style, where rule becomes a habit of taking over.","whyCN":"这个形容词也能描述个人风格，此时「统治」变成一种接管他人的习惯。"}],"etymology":{"intro":{"en":"Dominant is the present participle of Latin dominari 'to rule', from dominus 'lord, master', whose own origin is debated. The genetic sense is early twentieth century. Dates are approximate.","cn":"dominant 是拉丁 dominari「统治」的现在分词，出自 dominus「主人、领主」，而 dominus 自身的来源有争议。遗传学义项属 20 世纪初。年代均为约数。"},"items":[{"era":"LATIN DOMINUS","en":"Dominus meant 'lord, master, owner'. It is the source of dominate, dominion, dominant and domineer.","cn":"dominus 意为「主人、领主、所有者」，是 dominate、dominion、dominant 与 domineer 的来源。"},{"era":"LATIN DOMINARI","en":"Dominari meant 'to rule, be master'. Its present participle dominans, dominant- gives English dominant directly.","cn":"dominari 意为「统治、做主人」。其现在分词 dominans（词干 dominant-）直接给出英语 dominant。"},{"era":"ORIGIN OF DOMINUS","en":"The link of dominus to domus 'house' is traditional, giving the picture of the master of the household, but the derivation is disputed and remains a reconstruction.","cn":"传统说法把 dominus 与 domus「房屋」联系起来，形成「一家之主」的图像，但这一派生有争议，仍属重构。"},{"era":"ENGLISH ADJECTIVE","en":"Dominant entered English in the sixteenth century with the sense 'ruling, governing'. The broader sense 'most prominent' followed.","cn":"dominant 在 16 世纪进入英语，义为「统治的、治理的」；更宽的「最突出的」义随后出现。"},{"era":"GENETIC SENSE","en":"Genetics adopted the word around 1900 for an allele that shows its effect despite a rival, extending the old idea of one power over another.","cn":"遗传学约在 1900 年采用这个词，指不顾对手仍表现效果的等位基因，把旧的「一方压过另一方」观念延伸过来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the derivation of dominus from domus is one hypothesis among several, and the first use of dominant in genetics is dated only approximately.","cn":"来源不确定（词根）：把 dominus 派生自 domus 只是若干假说之一；dominant 在遗传学中的最早使用也只有大致年代。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin rule-family that are easily confused; group two holds near meanings that also describe power or prevalence.","cn":"第一组是同出拉丁「统治」词族、容易混淆的词；第二组是同样描述力量或普遍性的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dominate","ipa":"/ˈdɒmɪneɪt/","tag":"the verb","definition":"To rule or control, or to be the most prominent feature. Dominant is the adjective or the noun.","definitionCN":"指统治、控制，或成为最突出的特征；dominant 是形容词或名词。"},{"word":"dominance","ipa":"/ˈdɒmɪnəns/","tag":"the abstract noun","definition":"The state of being dominant; in genetics it is the relation between alleles, not an allele itself.","definitionCN":"指占主导的状态；在遗传学中指等位基因之间的关系，而非某个等位基因。"},{"word":"dominion","ipa":"/dəˈmɪniən/","tag":"territory or rule","definition":"A territory or the power to rule it; it is political, not biological.","definitionCN":"指领土或统治权；属政治领域，而非生物领域。"},{"word":"domineering","ipa":"/ˌdɒmɪˈnɪərɪŋ/","tag":"personal style","definition":"Controlling others in an arrogant way; it is close to the personal sense of dominant but more negative.","definitionCN":"指以傲慢方式控制他人；接近 dominant 的个人义，但更带贬义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"recessive","ipa":"/rɪˈsesɪv/","tag":"the genetic opposite","definition":"Hidden when a dominant allele is present; it is the exact counterpart in inheritance.","definitionCN":"指与显性等位基因同时存在时被掩盖；是遗传中的正相对概念。"},{"word":"predominant","ipa":"/ˌpriːˈdɒmɪnənt/","tag":"most common","definition":"Present as the largest or most noticeable element; it stresses prevalence rather than control.","definitionCN":"指作为最大或最显眼的部分存在；强调普遍性，而非控制。"},{"word":"prevalent","ipa":"/ˈprevələnt/","tag":"widespread","definition":"Common in a place or time; it says nothing about power or genetic expression.","definitionCN":"指在某地或某时普遍；不涉及权力或基因表现。"},{"word":"controlling","ipa":"/kənˈtrəʊlɪŋ/","tag":"active control","definition":"Actively directing something; dominant can be a standing position, while controlling implies ongoing action.","definitionCN":"指主动支配某事；dominant 可以是所处地位，controlling 则暗示持续行动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"domin- 'lord, master' + -ant 'being so': the one acting as master.","cn":"domin-「主人、领主」+ -ant「处于某种状态」：像主人一样的那一个。"},{"en":"The family runs dominate, dominance, domination, dominator, dominion.","cn":"同族词包括 dominate、dominance、domination、dominator、dominion。"},{"en":"In genetics the pair is fixed: dominant versus recessive.","cn":"遗传学中这一对是固定的：显性对隐性。"},{"en":"The same word names the fifth degree of a scale, the dominant.","cn":"同一个词也命名音阶的第五级，即属音。"},{"en":"Fixed phrases: dominant allele, dominant species, dominant role.","cn":"固定搭配：显性等位基因、优势种、主导作用。"}],"abstract":[{"en":"Picture one tall tree whose shade decides which seedlings survive.","cn":"想象一棵高树，它的阴影决定哪些幼苗能活。"},{"en":"Picture one voice in a choir that the others follow.","cn":"想象合唱中有一个声部，其余声部跟着它走。"},{"en":"Picture one color that sets the tone of an entire room.","cn":"想象一种颜色定下整个房间的色调。"}]},"examples":[{"en":"The dominant allele can mask a recessive one completely.","cn":"显性等位基因可以完全掩盖隐性等位基因。"},{"en":"Grasses are dominant in the first years after the fire.","cn":"火灾后的最初几年里，草本植物占优势。"},{"en":"The dominant theme of the report is uncertainty.","cn":"这份报告最突出的主题是不确定性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多敏能特」——人多、显眼、说了算的那一个 → 占主导的、显性的","word":"dominant"},"root":"拉丁 dominus「主人、领主」→ dominari「统治」，现在分词 dominans（词干 dominant-）；dominus 与 domus「房屋」的联系属传统假说，仍有争议。","sensesIntro":{"en":"Eight senses follow one relation: one thing overrules another, whether in politics, genes, ecology, numbers, design, music or personality.","cn":"八个义项围绕同一种关系展开：一个事物压过另一个，可用于政治、基因、生态、数量、设计、音乐或性格。"},"semanticMap":{"core":{"en":"CORE IMAGE: the tallest person standing in front, with the group arranged behind.","cn":"核心意象：最高的人站在前排，其余人排在他身后。"},"chain":["ONE RULES","OTHERS FOLLOW","POSITION HELD","TRAIT EXPRESSED","SHARE LARGEST","ATTENTION CAUGHT"],"branches":[{"senses":"S1 · S8","en":"POWER AND PERSONALITY: rule as a social position, and rule as a personal habit.","cn":"权力与性格：作为社会地位的统治，以及作为个人习惯的支配。"},{"senses":"S2 · S3","en":"GENETICS: one allele overrules another, and the winner is named as a noun.","cn":"遗传：一个等位基因压过另一个，胜出者再被名词化。"},{"senses":"S4 · S5","en":"ECOLOGY AND PROPORTION: one species shapes a community, one use holds the largest share.","cn":"生态与比例：一个物种塑造群落，一种用途占据最大份额。"},{"senses":"S6","en":"PERCEPTION: the element that organizes what the eye sees first.","cn":"感知：组织视线最先落点的那个元素。"},{"senses":"S7","en":"MUSIC: the fifth degree governs the pull back to the tonic.","cn":"音乐：第五级主导回到主音的拉力。"}]},"affixes":{"intro":{"en":"Dominant is a Latin participial adjective: domin- 'master' plus -ant 'being so'. The same stem builds the whole rule-family.","cn":"dominant 是拉丁分词形容词：domin-「主人」加 -ant「处于某种状态」。同一词干构成整个「统治」词族。"},"latinIntro":{"en":"Latin dominus and dominari supply dominate, dominance, dominator and dominion; all keep the core idea of a master.","cn":"拉丁 dominus 与 dominari 提供 dominate、dominance、dominator 与 dominion；它们都保留「主人」的核心观念。"},"items":[{"word":"domin-","structure":"Latin dominus (lord, master) as a root","meaning":"master; rule","meaningCN":"主人；统治","example":"The root opens dominate and dominion.","exampleCN":"这个词根出现在 dominate 与 dominion 开头。"},{"word":"-ant","structure":"Latin present participle ending -ans, -ant-","meaning":"being in a state or doing an action","meaningCN":"处于某状态或做某动作","example":"Dominant literally means 'being master'.","exampleCN":"dominant 字面义为「处于主人状态」。"},{"word":"dominate","structure":"domin- + -ate (verb)","meaning":"to rule or control","meaningCN":"统治；支配","example":"One team dominated the match.","exampleCN":"一支队伍控制了整场比赛。"},{"word":"dominance","structure":"dominant + -ce (state)","meaning":"the state of being dominant","meaningCN":"占主导的状态","example":"Dominance between alleles is not always complete.","exampleCN":"等位基因之间的显性并不总是完全的。"},{"word":"domination","structure":"dominat- + -ion (action or result)","meaning":"the act of ruling","meaningCN":"统治的行为","example":"The empire's domination lasted two centuries.","exampleCN":"这个帝国的统治持续了两个世纪。"},{"word":"dominator","structure":"dominat- + -or (person or thing)","meaning":"one that dominates","meaningCN":"支配者","example":"The stronger male became the dominator.","exampleCN":"较强的雄性成了支配者。"},{"word":"dominion","structure":"domin- + -ion (state or territory)","meaning":"territory under rule","meaningCN":"统治下的领土","example":"The island was a distant dominion.","exampleCN":"这座岛曾是一块遥远的领地。"},{"word":"dominantly","structure":"dominant + -ly (manner)","meaning":"in a dominant manner","meaningCN":"以主导的方式","example":"The gene is dominantly expressed.","exampleCN":"该基因显性表达。"},{"word":"dominant","structure":"domin- + -ant","meaning":"ruling; genetically expressed","meaningCN":"统治的；遗传上显性的","example":"The dominant trait appears in the hybrid.","exampleCN":"显性性状出现在杂交后代中。"}],"latinEntries":[{"word":"dominus","structure":"dominus, domini (noun, second declension)","meaning":"lord, master, owner","meaningCN":"主人；领主；所有者"},{"word":"dominari","structure":"dominari, dominor, dominatus sum (verb, first conjugation, deponent)","meaning":"to rule, be master","meaningCN":"统治；做主人"},{"word":"dominans","structure":"dominans, dominantis (present participle of dominari)","meaning":"ruling","meaningCN":"统治的"},{"word":"domus","structure":"domus, domus (noun, fourth declension)","meaning":"house, household","meaningCN":"房屋；家庭"}]}},{"word":"recessive","ipa_uk":"/rɪˈsesɪv/","ipa_us":"/rɪˈsesɪv/","definition_zh":"隐性的；隐性性状；后退的；不显眼的","definition_en":"not expressed when a dominant allele is present; also tending to recede","core_image":"两个人并排站着，一个向前一步，另一个退进阴影里","scene":"两个携带者都表现正常，却在孩子身上看到了隐藏的特征。医生解释：The recessive allele only shows when both copies are the same.","sceneCN":"这里指「隐性的」（第 1 个义项：与显性等位基因同时存在时被掩盖、不表现）；句意为隐性等位基因只有在两份拷贝相同时才表现。","pos":[{"tag":"adj.","zh":"隐性的；后退的；不显眼的"},{"tag":"n.","zh":"隐性性状；隐性等位基因"}],"collocations":[{"phrase":"recessive allele","zh":"隐性等位基因"},{"phrase":"recessive gene","zh":"隐性基因"},{"phrase":"recessive trait","zh":"隐性性状"},{"phrase":"recessive inheritance","zh":"隐性遗传"},{"phrase":"recessive mutation","zh":"隐性突变"},{"phrase":"autosomal recessive","zh":"常染色体隐性"},{"phrase":"recessive condition","zh":"隐性遗传病"}],"forms":[{"label":"名词（隐性）","form":"recessiveness（隐性）"},{"label":"副词","form":"recessively（隐性地）"},{"label":"比较级","form":"more recessive"},{"label":"最高级","form":"most recessive"},{"label":"反义形容词","form":"dominant（显性的）"},{"label":"相关动词（后退）","form":"recede（后退；减弱）"}],"derivatives":[{"word":"recessiveness","pos":"n.","zh":"隐性；隐性状态"},{"word":"recessively","pos":"adv.","zh":"隐性地"},{"word":"recede","pos":"v.","zh":"后退；减弱"},{"word":"recession","pos":"n.","zh":"后退；衰退"},{"word":"recess","pos":"n./v.","zh":"凹处；休息 / 使凹进"}],"senses":[{"no":"01","title":"Genetically recessive","titleCN":"隐性的（基本义）","definition":"not expressed in the phenotype when a dominant allele is also present","definitionCN":"当显性等位基因同时存在时不在表型中表现","example":"The recessive allele only shows when both copies are the same.","exampleCN":"隐性等位基因只有在两份拷贝相同时才表现。","why":"The word pictures stepping back: one version yields the foreground to the other and stays in the background.","whyCN":"这个词描绘后退：一个版本把前景让给另一个，自己留在背景里。"},{"no":"02","title":"A recessive allele","titleCN":"隐性等位基因（名词）","definition":"an allele whose effect is masked by a dominant allele","definitionCN":"效果被显性等位基因掩盖的等位基因","example":"She carries one recessive allele without showing the trait.","exampleCN":"她携带一个隐性等位基因，却没有表现出该性状。","why":"As a noun the word names the version that loses the foreground, not the person who carries it.","whyCN":"作名词时，这个词命名失去前景的那个版本，而不是携带它的人。"},{"no":"03","title":"A recessive trait","titleCN":"隐性性状","definition":"a trait that appears only when both alleles are recessive","definitionCN":"只有在两个等位基因都为隐性时才出现的性状","example":"Blue eyes are often described as a recessive trait.","exampleCN":"蓝眼常被描述为一种隐性性状。","why":"The adjective moves from the gene to the visible feature, naming the trait that waits for a matching copy.","whyCN":"这个形容词从基因移到可见特征，命名那种等待配对拷贝的性状。"},{"no":"04","title":"Recessive inheritance","titleCN":"隐性遗传（方式）","definition":"a pattern in which the trait appears only in homozygotes","definitionCN":"性状只在纯合个体中出现的遗传模式","example":"The disease follows a recessive pattern in this family.","exampleCN":"这种病在这个家族中遵循隐性遗传模式。","why":"Genetics turns the adjective into a label for a transmission pattern, useful in counselling.","whyCN":"遗传学把这个形容词变成一种传递模式的标签，在遗传咨询中很有用。"},{"no":"05","title":"Hidden or unexpressed generally","titleCN":"被掩盖的；不表现的（广义）","definition":"present but not showing, in a general or figurative sense","definitionCN":"存在却不显露，用于一般或比喻意义","example":"A recessive fear shaped her silence.","exampleCN":"一种隐而不显的恐惧造成了她的沉默。","why":"The genetic picture of a hidden version is borrowed for anything present but out of sight.","whyCN":"「隐藏版本」的遗传图像被借用来形容任何存在却看不见的事物。"},{"no":"06","title":"Receding or moving back","titleCN":"后退的；向后走的","definition":"moving or tending to move backward","definitionCN":"向后移动或有向后趋势的","example":"The recessive shoreline moved inland each year.","exampleCN":"后退的海岸线每年都向内陆移动。","why":"The older spatial sense survives beside the genetic one: recede means to go back, and the adjective inherits that direction.","whyCN":"较旧的空间义与遗传义并存：recede 意为后退，形容词继承了这个方向。"},{"no":"07","title":"Expressed only in homozygotes","titleCN":"只在纯合时表现","definition":"showing its effect only when two identical recessive copies are present","definitionCN":"只有两份相同的隐性拷贝存在时才表现效果","example":"The recessive form appears in one quarter of the offspring.","exampleCN":"隐性类型出现在四分之一的后代中。","why":"The word describes a condition of expression, so it also names the rule that governs when the trait can be seen.","whyCN":"这个词描述表现条件，因此也命名决定该性状何时可见的规则。"},{"no":"08","title":"A recessive mutation","titleCN":"隐性突变","definition":"a mutation whose effect is hidden unless no dominant version is present","definitionCN":"除非没有显性版本存在、否则效果被隐藏的突变","example":"A recessive mutation can spread unnoticed for generations.","exampleCN":"隐性突变可以在无人察觉的情况下传播数代。","why":"At the molecular level the adjective marks changes that do not alter the visible phenotype while a normal copy remains.","whyCN":"在分子层面，这个形容词标记那些在正常拷贝仍存在时不改变可见表型的改变。"}],"etymology":{"intro":{"en":"Recessive comes from Latin recessus, the past participle of recedere 'to go back', built from re- 'back' and cedere 'to go'. The genetic sense arose around 1900. Dates are approximate.","cn":"recessive 来自拉丁 recessus，即 recedere「后退」的过去分词，由 re-「向后」与 cedere「走」构成。遗传学义项约在 1900 年出现。年代均为约数。"},"items":[{"era":"LATIN CEDERE","en":"Cedere meant 'to go, yield, withdraw'. It is the source of proceed, concede, precede and recede, and carries the idea of stepping.","cn":"cedere 意为「走、让、退」，是 proceed、concede、precede 与 recede 的来源，带有「迈步」的意味。"},{"era":"LATIN RECEDERE","en":"Recedere combined re- 'back' with cedere 'to go': to go back, withdraw, retreat. Its past participle recessus gives English recess and recession as well as recessive.","cn":"recedere 把 re-「向后」与 cedere「走」结合，意为后退、退出、撤退。其过去分词 recessus 衍生英语 recess、recession 与 recessive。"},{"era":"ENGLISH ADJECTIVE","en":"Recessive entered English in the seventeenth century with the spatial sense 'tending to recede'. That sense remains rare but survives.","cn":"recessive 在 17 世纪进入英语，带空间义「有后退趋势」。这个义项虽少见，仍然存在。"},{"era":"GENETIC SENSE","en":"Around 1900 genetics took the word for an allele that steps back when a dominant partner is present; the metaphor is one of yielding the foreground.","cn":"约 1900 年，遗传学用这个词指在显性伙伴存在时退让的等位基因；这个隐喻就是让出前景。"},{"era":"MODERN ENGLISH","en":"Modern English uses recessive mainly in genetics, with fixed phrases such as autosomal recessive and recessive inheritance.","cn":"现代英语中 recessive 主要用于遗传学，常见固定说法有常染色体隐性、隐性遗传。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest English use of recessive is dated only to the seventeenth century, and the exact adoption of the genetic sense around 1900 is not fixed.","cn":"来源不确定（首见年代）：recessive 在英语中的最早使用只能定在 17 世纪；遗传义项在 1900 年前后的确切采用时间未有定论。"}]},"similar":{"note":{"en":"Group one holds words from the same recede-family that look similar; group two holds near meanings of hiddenness or withdrawal.","cn":"第一组是同出 recede 词族、外形相近的词；第二组是表示隐藏或退让的邻近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"recess","ipa":"/rɪˈses/","tag":"a break or hollow","definition":"A pause in work, or a hollow space in a wall; it is a noun of withdrawal, not a genetic term.","definitionCN":"指工作暂停，或墙上的凹处；是表示退缩的名词，并非遗传术语。"},{"word":"recession","ipa":"/rɪˈseʃn/","tag":"economic decline","definition":"A period when the economy shrinks; it shares the going-back picture but belongs to economics.","definitionCN":"指经济萎缩的时期；共享「后退」图像，但属经济领域。"},{"word":"recede","ipa":"/rɪˈsiːd/","tag":"the verb","definition":"To move back or become weaker; the adjective recessive describes what has that tendency.","definitionCN":"指向后退或变弱；形容词 recessive 描述具有这种趋势的事物。"},{"word":"recessional","ipa":"/rɪˈseʃənl/","tag":"going out","definition":"Relating to a departure, especially a hymn sung as clergy leave; the shape is similar but the use is ceremonial.","definitionCN":"指与退场相关的，尤指神职人员退场时唱的赞美诗；外形相似，用途属礼仪。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dominant","ipa":"/ˈdɒmɪnənt/","tag":"the genetic opposite","definition":"Expressed even when paired with a different allele; recessive is its exact counterpart.","definitionCN":"指即使与不同等位基因配对也表现；recessive 是其正相对概念。"},{"word":"hidden","ipa":"/ˈhɪdn/","tag":"general word","definition":"Not visible or not known; it is broader and carries no genetic mechanism.","definitionCN":"指不可见或未知；范围更广，不含遗传机制。"},{"word":"latent","ipa":"/ˈleɪtnt/","tag":"present but inactive","definition":"Existing but not yet active or expressed; disease and talent can be latent, but recessive is specific to alleles.","definitionCN":"指存在但尚未活动或表现；疾病与才能都可以是潜在的，而 recessive 专指等位基因。"},{"word":"subordinate","ipa":"/səˈbɔːdɪnət/","tag":"lower in rank","definition":"Lower in position or importance; it is social, while recessive is about expression.","definitionCN":"指地位或重要性较低；属社会层面，而 recessive 关乎表现。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- 'back' + cedere 'go' + -ive: tending to go back.","cn":"re-「向后」+ cedere「走」+ -ive：有后退趋势的。"},{"en":"The family runs recede, recession, recess, recessive, recessiveness.","cn":"同族词包括 recede、recession、recess、recessive、recessiveness。"},{"en":"The genetic pair is fixed: dominant versus recessive.","cn":"遗传学中的配对是固定的：显性对隐性。"},{"en":"A recessive allele steps back but is still inherited.","cn":"隐性等位基因退到后面，却仍可被继承。"},{"en":"Fixed phrases: recessive allele, recessive trait, autosomal recessive.","cn":"固定搭配：隐性等位基因、隐性性状、常染色体隐性。"}],"abstract":[{"en":"Picture one actor standing behind another, waiting for the same cue.","cn":"想象一个演员站在另一个身后，等同一个提示。"},{"en":"Picture a tide moving away from the shore.","cn":"想象潮水从岸边退走。"},{"en":"Picture a light dimmed by a brighter lamp beside it.","cn":"想象一盏灯被旁边更亮的灯压暗。"}]},"examples":[{"en":"Two carrier parents can have a child with the recessive disease.","cn":"两个携带者亲代可能生出患隐性遗传病的孩子。"},{"en":"The recessive allele remained hidden for three generations.","cn":"这个隐性等位基因隐藏了三代。"},{"en":"Recessive traits reappear when relatives marry.","cn":"亲属通婚时隐性性状会重新出现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞塞西夫」——站在后面、把位置让出去的那一个 → 隐性的","word":"recessive"},"root":"拉丁 recedere「后退」（re-「向后」+ cedere「走」）的过去分词 recessus + -ive；遗传学义项约始于 1900 年。","sensesIntro":{"en":"Eight senses follow one step back: a version yields the foreground, and the same yielding picture extends to traits, inheritance, hidden things, shorelines and mutations.","cn":"八个义项围绕一次后退展开：一个版本让出前景，同一幅退让图像再延伸到性状、遗传、隐藏事物、海岸线与突变。"},"semanticMap":{"core":{"en":"CORE IMAGE: one figure steps forward while the other steps into the shade.","cn":"核心意象：一个人向前一步，另一个退进阴影。"},"chain":["STEP BACK","FOREGROUND YIELDED","ALLELE MASKED","TRAIT WAITS","PATTERN NAMED","DIRECTION EXTENDED"],"branches":[{"senses":"S1 · S2","en":"ALLELE AND NOUN: the basic masked version, and the same version named as a noun.","cn":"等位基因与名词：基本的被掩盖版本，以及被名词化的同一版本。"},{"senses":"S3 · S4 · S7","en":"TRAIT AND TRANSMISSION: the visible trait, the family pattern, and the homozygote condition that releases it.","cn":"性状与传递：可见性状、家族模式，以及让它显现的纯合条件。"},{"senses":"S5","en":"GENERAL MASKING: anything kept out of sight borrows the same image of a figure standing in shade.","cn":"广义掩盖：任何被藏在视线之外的事物，都借用同一个人退进阴影的意象。"},{"senses":"S8","en":"MOLECULAR MUTATION: a change that stays unseen for generations, never showing on the surface.","cn":"分子突变：一种可以数代不被看见、始终不显露于表面的改变。"},{"senses":"S6","en":"SPATIAL SURVIVAL: the old sense of moving backward still lives in the word.","cn":"空间义的留存：向后移动的旧义仍活在这个词里。"}]},"affixes":{"intro":{"en":"Recessive joins the Latin prefix re- 'back', the root ced- 'go', and the adjective suffix -ive: literally 'tending to go back'.","cn":"recessive 把拉丁前缀 re-「向后」、词根 ced-「走」与形容词后缀 -ive 结合，字面义为「有后退趋势的」。"},"latinIntro":{"en":"Latin recedere and its participle recessus supply recede, recess, recession and recessive; the same cedere root also builds proceed, concede and precede.","cn":"拉丁 recedere 及其分词 recessus 提供 recede、recess、recession 与 recessive；同一 cedere 词根还构成 proceed、concede 与 precede。"},"items":[{"word":"re-","structure":"Latin prefix re- (back, again)","meaning":"back; again","meaningCN":"向后；再","example":"The prefix turns going into going back.","exampleCN":"这个前缀把「走」变成「往回走」。"},{"word":"ced-","structure":"Latin cedere (to go, yield)","meaning":"go; yield","meaningCN":"走；让出","example":"The root also appears in precede and concede.","exampleCN":"这个词根也出现在 precede 与 concede 中。"},{"word":"-ive","structure":"Latin -ivus (tending to)","meaning":"tending to; having the quality of","meaningCN":"有……倾向的；具有……性质的","example":"Recessive means tending to recede.","exampleCN":"recessive 意为有后退倾向的。"},{"word":"recede","structure":"re- + cedere","meaning":"to go back, withdraw","meaningCN":"后退；退出","example":"The flood water receded at dawn.","exampleCN":"洪水在黎明时退去。"},{"word":"recess","structure":"re- + cess- (past participle stem)","meaning":"a withdrawal; a hollow; a break","meaningCN":"退隐；凹处；休会","example":"The court took a short recess.","exampleCN":"法庭短暂休庭。"},{"word":"recession","structure":"recess- + -ion (action or result)","meaning":"a going back; an economic decline","meaningCN":"后退；经济衰退","example":"The recession lasted eighteen months.","exampleCN":"这次衰退持续了十八个月。"},{"word":"recessive","structure":"recess- + -ive","meaning":"tending to recede; genetically masked","meaningCN":"有后退趋势的；遗传上隐性的","example":"The recessive form stays in the background.","exampleCN":"隐性类型留在背景中。"},{"word":"recessiveness","structure":"recessive + -ness (state)","meaning":"the state of being recessive","meaningCN":"隐性的状态","example":"Recessiveness depends on the partner allele.","exampleCN":"隐性状态取决于配对的等位基因。"},{"word":"recessively","structure":"recessive + -ly (manner)","meaning":"in a recessive manner","meaningCN":"以隐性方式","example":"The trait is recessively inherited.","exampleCN":"该性状以隐性方式遗传。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cedo, cessi, cessum (verb, third conjugation)","meaning":"to go, yield, withdraw","meaningCN":"走；让出；退"},{"word":"recedere","structure":"recedere, recedo, recessi, recessum (verb, third conjugation)","meaning":"to go back, retreat","meaningCN":"后退；撤退"},{"word":"recessus","structure":"recessus, recessus (noun, fourth declension)","meaning":"a going back, withdrawal","meaningCN":"后退；退隐"}]}},{"word":"recessiveness","ipa_uk":"/rɪˈsesɪvnəs/","ipa_us":"/rɪˈsesɪvnəs/","definition_zh":"隐性；隐性状态；被掩盖的性质","definition_en":"the quality or state of being recessive, especially of an allele or trait","core_image":"一盏灯被旁边更亮的灯盖住，只有亮灯熄灭时才看得见","scene":"课堂练习里，学生要判断一种性状为何会被掩盖。老师提示：Recessiveness explains why the hidden trait reappears in one quarter of the offspring.","sceneCN":"这里指「隐性」（第 1 个义项：等位基因或性状被显性版本掩盖的性质）；句意为隐性解释了为什么隐藏性状会在四分之一的后代中重新出现。","pos":[{"tag":"n.","zh":"隐性；隐性状态（不可数）"}],"collocations":[{"phrase":"the recessiveness of a trait","zh":"某一性状的隐性"},{"phrase":"complete recessiveness","zh":"完全隐性"},{"phrase":"relative recessiveness","zh":"相对隐性"},{"phrase":"pattern of recessiveness","zh":"隐性模式"},{"phrase":"recessiveness in inheritance","zh":"遗传中的隐性"},{"phrase":"degree of recessiveness","zh":"隐性程度"}],"forms":[{"label":"形容词","form":"recessive（隐性的）"},{"label":"副词","form":"recessively（隐性地）"},{"label":"反义名词","form":"dominance（显性；主导）"},{"label":"相关动词","form":"recede（后退；减弱）"},{"label":"复数（极少用）","form":"recessivenesses"}],"derivatives":[{"word":"recessive","pos":"adj./n.","zh":"隐性的 / 隐性性状"},{"word":"recessively","pos":"adv.","zh":"隐性地"},{"word":"recede","pos":"v.","zh":"后退；减弱"},{"word":"recession","pos":"n.","zh":"后退；衰退"},{"word":"recess","pos":"n./v.","zh":"凹处；休会 / 使凹进"}],"senses":[{"no":"01","title":"The state of being recessive","titleCN":"隐性（基本性质）","definition":"the state of being masked when a dominant allele is present","definitionCN":"显性等位基因存在时被掩盖的状态","example":"Recessiveness explains why the hidden trait reappears in one quarter of the offspring.","exampleCN":"隐性解释了为什么隐藏性状会在四分之一的后代中重新出现。","why":"The suffix -ness turns the adjective into a state: not a thing that hides, but the condition of being hidden.","whyCN":"后缀 -ness 把形容词变成状态：不是隐藏东西的事物，而是被隐藏的状况。"},{"no":"02","title":"The quality of a recessive allele","titleCN":"隐性等位基因的性质","definition":"the property of an allele that yields to a dominant partner","definitionCN":"等位基因向显性伙伴让步的性质","example":"Recessiveness is a relation, not a fixed feature of the allele.","exampleCN":"隐性是一种关系，而不是等位基因的固定特征。","why":"An allele is recessive only relative to a partner, so the noun names a relation that can change with context.","whyCN":"一个等位基因只有相对于伙伴才是隐性的，因此这个名词命名的是一种会随情境改变的关系。"},{"no":"03","title":"The condition of a hidden trait","titleCN":"隐性性状的隐藏状态","definition":"the condition in which a trait is present in the genes but absent from view","definitionCN":"性状存在于基因中却不显露于外的状况","example":"The recessiveness of the trait kept it out of family records.","exampleCN":"该性状的隐性使它长期不见于家族记录。","why":"The noun can describe the trait's situation rather than the allele's mechanism.","whyCN":"这个名词可以描述性状的处境，而不只是等位基因的机制。"},{"no":"04","title":"Recessive inheritance as a pattern","titleCN":"隐性遗传方式","definition":"the transmission pattern in which a trait appears only in homozygotes","definitionCN":"性状只在纯合个体中出现的传递模式","example":"Doctors recognized recessiveness from the pedigree.","exampleCN":"医生从系谱中辨认出隐性遗传。","why":"Clinical genetics turns the abstract quality into a diagnosable pattern visible in families.","whyCN":"临床遗传学把这一抽象性质变成家族中可见、可诊断的模式。"},{"no":"05","title":"The relation of being masked","titleCN":"被显性掩盖的关系","definition":"the relation in which one version's effect covers another's","definitionCN":"一个版本的效果覆盖另一个版本的关系","example":"Recessiveness depends on the presence of a dominant partner.","exampleCN":"隐性取决于显性伙伴的存在。","why":"The noun can name the covering relation itself, which is why it is often paired with dominance.","whyCN":"这个名词可以命名覆盖关系本身，因此常与显性并列使用。"},{"no":"06","title":"The homozygous condition","titleCN":"隐性纯合状态","definition":"the state in which two identical recessive copies are present and the trait shows","definitionCN":"两份相同的隐性拷贝存在、性状得以表现的状态","example":"Recessiveness ends when both copies carry the same hidden version.","exampleCN":"当两份拷贝都携带同一隐藏版本时，隐性状态就结束了。","why":"The same quality describes the genotype that finally lets the hidden effect appear.","whyCN":"同一性质也描述那个终于让隐藏效果出现的基因型。"},{"no":"07","title":"Low-frequency survival in a population","titleCN":"群体中的低频留存","definition":"the persistence of a recessive allele at low frequency because it is hidden in carriers","definitionCN":"隐性等位基因因藏在携带者中而以低频率持续存在","example":"Recessiveness allows a harmful allele to survive unseen.","exampleCN":"隐性让一个有害等位基因得以隐形地存续。","why":"Because carriers look normal, selection cannot easily remove the allele, and the noun explains its persistence.","whyCN":"由于携带者外观正常，选择难以清除该等位基因，这个名词解释了它的持续存在。"},{"no":"08","title":"A metaphor for staying in the background","titleCN":"比喻：不显眼、退居幕后","definition":"a figurative quality of remaining unnoticed or secondary","definitionCN":"不引人注意或处于次要地位的比喻性质","example":"The recessiveness of his role made the success look effortless.","exampleCN":"他角色的隐没让成功显得毫不费力。","why":"The genetic picture of a hidden version is borrowed for people and things that work out of sight.","whyCN":"「隐藏版本」的遗传图像被借用来形容在视线之外起作用的人与物。"}],"etymology":{"intro":{"en":"Recessiveness is an English formation: adjective recessive plus the native suffix -ness. Recessive itself comes from Latin recedere 'to go back'. Dates are approximate.","cn":"recessiveness 是英语内部构成的词：形容词 recessive 加本族后缀 -ness。recessive 本身来自拉丁 recedere「后退」。年代均为约数。"},"items":[{"era":"LATIN RECEDERE","en":"Recedere 'to go back' is built from re- 'back' and cedere 'to go'; its participle recessus gives the adjective recessive.","cn":"recedere「后退」由 re-「向后」与 cedere「走」构成；其分词 recessus 给出形容词 recessive。"},{"era":"ENGLISH -NESS","en":"The suffix -ness is native English and turns an adjective into a noun of state, as in darkness and openness.","cn":"后缀 -ness 是英语本族成分，把形容词变成表示状态的名词，如 darkness 与 openness。"},{"era":"GENETIC ADJECTIVE","en":"Recessive acquired its genetic sense around 1900, when the relation between dominant and hidden alleles needed names.","cn":"recessive 约在 1900 年获得遗传学义项，当时显性与隐藏的等位基因关系需要名称。"},{"era":"THE ABSTRACT NOUN","en":"Recessiveness is the late abstract noun of that adjective, used when the relation itself, rather than an allele, is the topic.","cn":"recessiveness 是该形容词较晚出现的抽象名词，用于讨论关系本身而非某个等位基因。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the first recorded use of recessiveness is not precisely dated, and its adoption in genetics is known only approximately.","cn":"来源不确定（首见年代）：recessiveness 的最早记录没有精确年代，它在遗传学中的采用也只有大致时间。"}]},"similar":{"note":{"en":"Group one holds forms from the same recede-family that look alike; group two holds abstract nouns for hidden or inactive states.","cn":"第一组是同出 recede 词族、外形相近的形式；第二组是表示隐藏或不活跃状态的抽象名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"recessive","ipa":"/rɪˈsesɪv/","tag":"the adjective","definition":"The adjective describing a masked allele or trait; recessiveness is the corresponding state noun.","definitionCN":"描述被掩盖的等位基因或性状的形容词；recessiveness 是对应的状态名词。"},{"word":"recession","ipa":"/rɪˈseʃn/","tag":"economic decline","definition":"A contraction of the economy; the spelling is close but the meaning is economic, not genetic.","definitionCN":"指经济收缩；拼写接近，但意义属经济，不是遗传。"},{"word":"recess","ipa":"/rɪˈses/","tag":"break or hollow","definition":"A pause or a hollow space; it is a concrete noun, not a state of being masked.","definitionCN":"指暂停或凹处；是具体名词，不是被掩盖的状态。"},{"word":"recede","ipa":"/rɪˈsiːd/","tag":"the verb","definition":"To move back; the noun recessiveness names the resulting quality in genetics.","definitionCN":"指向后退；名词 recessiveness 命名遗传中由此形成的性质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dominance","ipa":"/ˈdɒmɪnəns/","tag":"the opposite relation","definition":"The state of being expressed over a partner; it is the counterpart of recessiveness.","definitionCN":"指相对伙伴仍表现的状态；是 recessiveness 的对立关系。"},{"word":"latency","ipa":"/ˈleɪtənsi/","tag":"present but inactive","definition":"The state of existing without showing activity; it is broader than recessiveness and not tied to alleles.","definitionCN":"指存在但不表现活动的状态；范围比隐性更广，也不限于等位基因。"},{"word":"dormancy","ipa":"/ˈdɔːmənsi/","tag":"biological rest","definition":"A temporary inactive state in seeds or animals; recessiveness is about expression, not rest.","definitionCN":"指种子或动物的暂时不活跃状态；隐性关乎表现，而非休息。"},{"word":"suppression","ipa":"/səˈpreʃn/","tag":"active blocking","definition":"The act of holding something back; recessiveness can result from masking, but suppression suggests an active force.","definitionCN":"指压制某事物的行为；隐性可以源于掩盖，但 suppression 暗示主动力量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"recessive + -ness: the state of stepping back.","cn":"recessive + -ness：后退的状态。"},{"en":"The family runs recede, recession, recess, recessive, recessiveness.","cn":"同族词包括 recede、recession、recess、recessive、recessiveness。"},{"en":"The noun is used when the relation itself is the subject, not a particular allele.","cn":"当讨论关系本身而非某个等位基因时，就用这个名词。"},{"en":"It pairs naturally with dominance in genetics writing.","cn":"在遗传学写作中，它常与 dominance 配对。"},{"en":"Fixed phrases: complete recessiveness, relative recessiveness, degree of recessiveness.","cn":"固定搭配：完全隐性、相对隐性、隐性程度。"}],"abstract":[{"en":"Picture a lamp switched off while a brighter lamp burns beside it.","cn":"想象一盏灯关着，旁边更亮的灯燃着。"},{"en":"Picture a voice that waits until the lead singer stops.","cn":"想象一个声音等到主唱停下才出现。"},{"en":"Picture a word written in pale ink, legible only when held to the light.","cn":"想象一个字用浅色墨水写，只有对着光才看得清。"}]},"examples":[{"en":"Recessiveness is relative: the same allele can be dominant against another partner.","cn":"隐性是相对的：同一等位基因面对另一伙伴时可能是显性。"},{"en":"The recessiveness of the mutation delayed its detection.","cn":"该突变的隐性延误了它的发现。"},{"en":"Breeders watch recessiveness because hidden alleles return in later crosses.","cn":"育种者关注隐性，因为隐藏的等位基因会在后续杂交中重现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞塞西夫尼斯」——总站在后面、把光让出去的那种状态 → 隐性","word":"recessiveness"},"root":"recessive（拉丁 recedere「后退」的过去分词词干 + -ive）加英语本族后缀 -ness，表示「处于隐性的状态」。","sensesIntro":{"en":"Eight senses follow one state: an effect yields the foreground, and the state is then named for alleles, traits, inheritance, homozygotes, populations and metaphor.","cn":"八个义项围绕同一种状态展开：一种效果让出前景，这个状态再依次用于等位基因、性状、遗传、纯合个体、群体与比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dim lamp hidden by a brighter one beside it.","cn":"核心意象：一盏暗灯被旁边更亮的灯盖住。"},"chain":["EFFECT HIDDEN","PARTNER COVERS","ALLELE RECEDES","TRAIT WAITS","PATTERN SEEN","QUALITY NAMED"],"branches":[{"senses":"S1 · S2","en":"STATE AND ALLELE: the basic condition, and the property of a version that yields.","cn":"状态与等位基因：基本状况，以及让步版本的性质。"},{"senses":"S3 · S4 · S6","en":"TRAIT, PATTERN, HOMOZYGOTE: the hidden feature, the family pattern, and the genotype that reveals it.","cn":"性状、模式、纯合个体：隐藏的特征、家族模式，以及使其显现的基因型。"},{"senses":"S5","en":"RELATION: being masked is not a thing but a relation to the partner standing in front.","cn":"关系：被掩盖不是一种东西，而是与站在前面的伙伴之间的一种关系。"},{"senses":"S7","en":"SURVIVAL: because the relation hides it, an allele can persist at low frequency for many generations.","cn":"存续：正因为这种关系把它藏住，等位基因才能以低频存续许多代。"},{"senses":"S8","en":"METAPHOR: the same state describes people or things working out of sight.","cn":"比喻：同一状态也描述在视线之外起作用的人或物。"}]},"affixes":{"intro":{"en":"Recessiveness is a derived noun: the adjective recessive plus -ness. The adjective itself is re- 'back' + ced- 'go' + -ive.","cn":"recessiveness 是派生名词：形容词 recessive 加 -ness。形容词本身由 re-「向后」、ced-「走」与 -ive 构成。"},"latinIntro":{"en":"Latin recedere supplies the base of the adjective; the suffix -ness is native English, so the word is a Latin-derived stem with a native ending.","cn":"拉丁 recedere 提供形容词的词干；后缀 -ness 是英语本族成分，因此这个词是拉丁来源词干加本族词尾。"},"items":[{"word":"re-","structure":"Latin prefix re- (back, again)","meaning":"back; again","meaningCN":"向后；再","example":"The prefix marks the backward movement.","exampleCN":"这个前缀标记向后的运动。"},{"word":"ced-","structure":"Latin cedere (to go, yield)","meaning":"go; yield","meaningCN":"走；让出","example":"The root is shared with recede and concede.","exampleCN":"这个词根与 recede、concede 共享。"},{"word":"-ive","structure":"Latin -ivus (tending to)","meaning":"tending to","meaningCN":"有……倾向的","example":"The suffix makes an adjective of tendency.","exampleCN":"这个后缀构成表示倾向的形容词。"},{"word":"-ness","structure":"Old English -nes (state, quality)","meaning":"the state or quality of","meaningCN":"……的状态或性质","example":"Darkness and openness use the same native suffix.","exampleCN":"darkness 与 openness 使用同一本族后缀。"},{"word":"recede","structure":"re- + cedere","meaning":"to go back","meaningCN":"后退","example":"The water receded after the storm.","exampleCN":"暴风雨后水退去了。"},{"word":"recessive","structure":"recess- + -ive","meaning":"tending to recede; genetically masked","meaningCN":"有后退趋势的；遗传上隐性的","example":"The recessive trait stayed hidden.","exampleCN":"隐性性状保持隐藏。"},{"word":"recessively","structure":"recessive + -ly","meaning":"in a recessive way","meaningCN":"以隐性方式","example":"The condition is recessively transmitted.","exampleCN":"该病症以隐性方式传递。"},{"word":"recessiveness","structure":"recessive + -ness","meaning":"the state of being recessive","meaningCN":"隐性的状态","example":"Recessiveness is defined against a partner allele.","exampleCN":"隐性是相对于配对等位基因来定义的。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cedo, cessi, cessum (verb, third conjugation)","meaning":"to go, yield","meaningCN":"走；让出"},{"word":"recedere","structure":"recedere, recedo, recessi, recessum (verb, third conjugation)","meaning":"to go back, retreat","meaningCN":"后退；撤退"},{"word":"recessus","structure":"recessus, recessus (noun, fourth declension)","meaning":"a going back","meaningCN":"后退；退隐"}]}},{"word":"hybrid","ipa_uk":"/ˈhaɪbrɪd/","ipa_us":"/ˈhaɪbrɪd/","definition_zh":"杂种；杂交后代；混合体；混合动力的；混合词","definition_en":"an offspring of two different species or varieties, or something made by combining different elements","core_image":"两株不同品种的果树之间长出一棵新树，果实兼具两种风味","scene":"果园里两行不同品种的苹果树之间种了一排新树。园主介绍：This hybrid combines the sweetness of one parent with the hardiness of the other.","sceneCN":"这里指「杂交后代」（第 1 个义项：两个不同物种或品种交配产生的后代）；句意为这个杂交后代兼具一个亲本的甜味与另一个亲本的耐寒性。","pos":[{"tag":"n.","zh":"杂种；杂交后代；混合体（可数，复数 hybrids）"},{"tag":"adj.","zh":"杂交的；混合的；混合动力的"}],"collocations":[{"phrase":"hybrid species","zh":"杂交物种"},{"phrase":"hybrid variety","zh":"杂交品种"},{"phrase":"hybrid vigor","zh":"杂种优势"},{"phrase":"hybrid car","zh":"混合动力汽车"},{"phrase":"hybrid system","zh":"混合系统"},{"phrase":"hybrid model","zh":"混合模式"},{"phrase":"hybrid word","zh":"混合词"}],"forms":[{"label":"复数","form":"hybrids"},{"label":"动词（使杂交）","form":"hybridize（使杂交）"},{"label":"名词（杂交）","form":"hybridization（杂交）"},{"label":"名词（杂交状态）","form":"hybridism（杂交性）"},{"label":"名词（混合性）","form":"hybridity（混合性）"},{"label":"复合形容词（混合动力的）","form":"hybrid-electric（混合电动的）"}],"derivatives":[{"word":"hybridize","pos":"v.","zh":"使杂交；杂交"},{"word":"hybridization","pos":"n.","zh":"杂交；杂化"},{"word":"hybridism","pos":"n.","zh":"杂交性；混合性"},{"word":"hybridity","pos":"n.","zh":"混合性；杂合性"},{"word":"hybridoma","pos":"n.","zh":"杂交瘤"}],"senses":[{"no":"01","title":"An offspring of two kinds","titleCN":"动植物杂交后代","definition":"the offspring of two different species or varieties","definitionCN":"两个不同物种或品种交配产生的后代","example":"This hybrid combines the sweetness of one parent with the hardiness of the other.","exampleCN":"这个杂交后代兼具一个亲本的甜味与另一个亲本的耐寒性。","why":"Hybrid names the product of a cross: two lineages meet, and the offspring carries material from both.","whyCN":"hybrid 命名一次杂交的产物：两个世系相遇，后代同时携带双方的材料。"},{"no":"02","title":"A bred hybrid variety","titleCN":"农业杂交品种","definition":"a variety deliberately produced by crossing selected parents","definitionCN":"通过选配亲本有意培育出的品种","example":"Farmers planted a hybrid that resists two common diseases.","exampleCN":"农民种了一个能抗两种常见病的杂交品种。","why":"Once breeders repeat a cross, the offspring becomes a named product, and the word moves from a single plant to a commercial variety.","whyCN":"一旦育种者重复同一杂交，后代就成了有名称的产品，这个词也从单株植物转指商业品种。"},{"no":"03","title":"A genetically mixed individual","titleCN":"遗传学上的杂合个体","definition":"an individual carrying alleles from two distinct gene pools","definitionCN":"携带来自两个不同基因库的等位基因的个体","example":"The hybrid carries one allele from each parent species.","exampleCN":"这个杂合个体从每个亲本物种各携带一个等位基因。","why":"Genetics makes the crossing precise: the individual is mixed at the level of alleles, not just in appearance.","whyCN":"遗传学把杂交说得更精确：个体在等位基因层面就是混合的，而不只是外观混合。"},{"no":"04","title":"A general mixture","titleCN":"泛指混合体","definition":"anything made by combining two different things","definitionCN":"由两种不同事物组合而成的任何东西","example":"The festival is a hybrid of a concert and a street market.","exampleCN":"这个节庆是音乐会和街市的混合体。","why":"The biological picture of two parents producing one offspring is borrowed for any combination of two sources.","whyCN":"两个亲本产生一个后代的生物图像，被借用来形容任何两个来源的组合。"},{"no":"05","title":"A hybrid vehicle","titleCN":"混合动力汽车","definition":"a vehicle powered by two different energy sources, usually an engine and a battery","definitionCN":"由两种能源驱动的车辆，通常是发动机与电池","example":"The hybrid uses less fuel in city traffic.","exampleCN":"这辆混合动力车在城市交通中更省油。","why":"Engineering keeps the same structure: two power sources are combined in one machine.","whyCN":"工程保留了同一结构：两种动力源被组合进同一台机器。"},{"no":"06","title":"A combined technical system","titleCN":"混合系统或混合方案","definition":"a system or method that combines two approaches","definitionCN":"把两种方法组合起来的系统或方案","example":"The lab adopted a hybrid of field surveys and remote sensing.","exampleCN":"实验室采用了野外调查与遥感的混合方案。","why":"When two methods each cover part of a problem, joining them produces a hybrid method.","whyCN":"当两种方法各自覆盖问题的一部分，把它们接起来就产生混合方法。"},{"no":"07","title":"A hybrid word","titleCN":"混合词（语言学）","definition":"a word made of elements from different languages","definitionCN":"由不同语言的成分构成的词","example":"The term is a hybrid of a Greek root and a Latin suffix.","exampleCN":"这个术语是希腊词根与拉丁后缀的混合词。","why":"Language contact mixes material the way breeding mixes lineages, so linguists borrow the biological word.","whyCN":"语言接触混合材料，正如繁育混合世系，因此语言学家借用了这个生物词。"},{"no":"08","title":"A mixed culture or style","titleCN":"混合文化或混合风格","definition":"a culture, style or identity formed from two different traditions","definitionCN":"由两种不同传统形成的文化、风格或身份","example":"The neighborhood has a hybrid cuisine all its own.","exampleCN":"这个街区有自己独特的混合菜系。","why":"The word now describes cultural blending, where two traditions meet and produce something neither one alone could make.","whyCN":"这个词现在描述文化混合：两种传统相遇，产生任何一方单独都无法做出的东西。"}],"etymology":{"intro":{"en":"Hybrid comes from Latin hybrida, a word for the offspring of two different kinds, also applied to a person of mixed parentage. Its deeper origin is disputed. Dates are approximate.","cn":"hybrid 来自拉丁 hybrida，指两个不同种类的后代，也用于混合血统的人。它的更深来源有争议。年代均为约数。"},"items":[{"era":"LATIN HYBRIDA","en":"Hybrida named the offspring of a tame sow and a wild boar, and by extension a person of mixed parentage. The word already carried both the animal and the social sense.","cn":"hybrida 指家猪与野猪的后代，也引申指混合血统的人。这个词从一开始就同时带有动物义与社会义。"},{"era":"DISPUTED ORIGIN","en":"One common account links hybrida to Greek hybris 'insolence, violence, wantonness', but the connection is not established; other explanations have been proposed.","cn":"一种常见说法把 hybrida 与希腊 hybris「傲慢、暴烈、放纵」联系起来，但这一联系并未确立，另有其他解释。"},{"era":"ENGLISH ENTRY","en":"Hybrid entered English in the sixteenth century as a term for a mongrel or a person of mixed descent, then spread to plants and animals.","cn":"hybrid 在 16 世纪进入英语，指杂种或混合血统的人，随后扩展到植物与动物。"},{"era":"SCIENTIFIC HYBRID","en":"Eighteenth and nineteenth century naturalists fixed the word for the offspring of two species, and breeding made it a practical agricultural term.","cn":"18 至 19 世纪的自然学家把这个词固定为两个物种的后代，育种又使它成为实用的农业术语。"},{"era":"TECHNICAL EXTENSION","en":"The twentieth century extended hybrid to vehicles, systems and words, where two sources are combined in one unit.","cn":"20 世纪把 hybrid 扩展到车辆、系统与词语，指两个来源被组合进同一个单位。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the link of Latin hybrida to Greek hybris is one hypothesis among several, and the earliest English use is dated only to the sixteenth century.","cn":"来源不确定（词根）：把拉丁 hybrida 与希腊 hybris 联系起来只是若干假说之一；英语最早使用只能定在 16 世纪。"}]},"similar":{"note":{"en":"Group one holds forms from the same hybrid family that are easily swapped; group two holds words for crossed or mixed things.","cn":"第一组是同出 hybrid 词族、容易被替换的形式；第二组是表示杂交或混合事物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hybridize","ipa":"/ˈhaɪbrɪdaɪz/","tag":"the verb","definition":"To produce a hybrid; hybrid is the product or the adjective, hybridize is the action.","definitionCN":"指产生杂交后代；hybrid 是产物或形容词，hybridize 是动作。"},{"word":"hybridization","ipa":"/ˌhaɪbrɪdaɪˈzeɪʃn/","tag":"the process","definition":"The process or technique of making hybrids; it names the event, not the offspring.","definitionCN":"指制造杂交后代的过程或技术；命名事件，而非后代。"},{"word":"hybridism","ipa":"/ˈhaɪbrɪdɪzəm/","tag":"the state","definition":"The condition or quality of being hybrid; it is an abstract state noun.","definitionCN":"指作为杂交体的状况或性质；是抽象状态名词。"},{"word":"hybridity","ipa":"/haɪˈbrɪdəti/","tag":"mixedness","definition":"The quality of being mixed, especially in cultural studies; it is broader and more theoretical than hybrid.","definitionCN":"指混合的性质，尤用于文化研究；比 hybrid 更宽泛、更理论化。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crossbreed","ipa":"/ˈkrɒsbriːd/","tag":"breeding term","definition":"An animal or plant produced by crossing two breeds; it stresses deliberate breeding rather than any combination.","definitionCN":"指两个品种杂交产生的动植物；强调有意繁育，而非任何组合。"},{"word":"mongrel","ipa":"/ˈmɒŋɡrəl/","tag":"negative or informal","definition":"An animal of mixed breed, especially a dog; it often carries a negative tone that hybrid does not.","definitionCN":"指混血动物，尤指狗；常带贬义，而 hybrid 不带。"},{"word":"mixture","ipa":"/ˈmɪkstʃə/","tag":"general combination","definition":"A combination of substances or things; it does not imply that the parts produced a new individual.","definitionCN":"指物质或事物的组合；不暗示各部分产生了一个新个体。"},{"word":"composite","ipa":"/ˌkɒmˈpɒzɪt/","tag":"made of parts","definition":"Something assembled from distinct parts; it stresses structure, while hybrid stresses the crossing of sources.","definitionCN":"指由不同部分组装而成；强调结构，而 hybrid 强调来源的交叉。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base hybrid names a cross, and -ize and -ization build the action and the process.","cn":"词基 hybrid 命名一次杂交，-ize 与 -ization 构成动作与过程。"},{"en":"The family runs hybrid, hybridize, hybridization, hybridism, hybridity, hybridoma.","cn":"同族词包括 hybrid、hybridize、hybridization、hybridism、hybridity、hybridoma。"},{"en":"Fixed phrases mark the fields: hybrid species, hybrid car, hybrid system.","cn":"固定搭配标出领域：杂交物种、混合动力汽车、混合系统。"},{"en":"Two parents, one offspring: that is the core picture behind every sense.","cn":"两个亲本，一个后代：这就是所有义项背后的核心图像。"},{"en":"In agriculture, hybrid vigor means the cross grows better than either parent.","cn":"在农业中，杂种优势指杂交后代比任一亲本长得更好。"}],"abstract":[{"en":"Picture two rivers joining and carrying water from both valleys.","cn":"想象两条河汇合，同时带来两个山谷的水。"},{"en":"Picture a song that uses the melody of one tradition and the rhythm of another.","cn":"想象一首歌用一种传统的旋律、另一种传统的节奏。"},{"en":"Picture a machine with an engine and a battery sharing one body.","cn":"想象一台机器，发动机与电池共用同一个机身。"}]},"examples":[{"en":"The hybrid grew faster than either parent in the trial field.","cn":"在试验田里，这个杂交后代比任一亲本长得更快。"},{"en":"Hybrid rice helped raise yields across the region.","cn":"杂交水稻帮助提高了整个地区的产量。"},{"en":"The city's music is a hybrid of folk and electronic styles.","cn":"这座城市的音乐是民谣与电子风格的混合。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「海布里德」——两株不一样的树合出一棵新树 → 杂种、混合体","word":"hybrid"},"root":"拉丁 hybrida「不同种类的后代；混合血统的人」；其更深来源存疑，一说与希腊 hybris「傲慢、暴烈」相关，但未确立。","sensesIntro":{"en":"Eight senses follow one cross: two sources meet in one product, and that product is then named in biology, farming, genetics, engineering, language and culture.","cn":"八个义项围绕一次杂交展开：两个来源在一个产物中相遇，这个产物再在生物学、农业、遗传学、工程、语言与文化中获得名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new tree growing between two different varieties, carrying both flavours.","cn":"核心意象：两株不同品种之间长出一棵新树，兼具两种风味。"},"chain":["TWO SOURCES","ONE CROSS","OFFSPRING BORN","TRAITS MIXED","VARIETY NAMED","COMBINATION EXTENDED"],"branches":[{"senses":"S1 · S3","en":"ORGANISM AND GENES: the basic offspring, and the same individual seen as a mix of alleles.","cn":"生物体与基因：基本后代，以及从等位基因混合角度看同一只个体。"},{"senses":"S2","en":"AGRICULTURE: a repeated cross becomes a named variety sold as seed.","cn":"农业：重复的杂交成为有名称、可售卖的种子品种。"},{"senses":"S4 · S8","en":"GENERAL AND CULTURAL MIXTURE: any combination, including cultures and cuisines.","cn":"一般与文化混合：任何组合，包括文化与菜系。"},{"senses":"S5 · S6","en":"ENGINEERING: two power sources or two methods share one machine or plan.","cn":"工程：两种动力源或两种方法共用一台机器或一个方案。"},{"senses":"S7","en":"LANGUAGE: a word built from elements of different languages.","cn":"语言：由不同语言成分构成的词。"}]},"affixes":{"intro":{"en":"Hybrid is a bare Latin noun used as a base; -ize and -ization turn it into the verb and the process noun, while -ism and -ity name states.","cn":"hybrid 是作词基使用的拉丁名词；-ize 与 -ization 把它变成动词与过程名词，-ism 与 -ity 则命名状态。"},"latinIntro":{"en":"Latin hybrida is the source; the suffixes -ize and -ization came through French from Latin -izare and -izatio, themselves from Greek.","cn":"来源是拉丁 hybrida；后缀 -ize 与 -ization 经法语来自拉丁 -izare 与 -izatio，而后者又源自希腊语。"},"items":[{"word":"hybrid","structure":"Latin hybrida (offspring of two kinds)","meaning":"a crossbred individual or thing","meaningCN":"杂交个体或混合事物","example":"The hybrid carries traits from both parents.","exampleCN":"杂交后代携带两个亲本的性状。"},{"word":"-ize","structure":"Latin -izare, through French -iser","meaning":"to make or become","meaningCN":"使成为；使……化","example":"Hybridize means to make a hybrid.","exampleCN":"hybridize 意为使成为杂交体。"},{"word":"-ization","structure":"Latin -izatio, through French -isation","meaning":"the process of making","meaningCN":"使……化的过程","example":"Hybridization names the process.","exampleCN":"hybridization 命名这一过程。"},{"word":"hybridize","structure":"hybrid + -ize","meaning":"to produce a hybrid","meaningCN":"使杂交；产生杂交后代","example":"The two species hybridize in the wild.","exampleCN":"这两个物种在野外杂交。"},{"word":"hybridization","structure":"hybridize + -ation","meaning":"the process of crossing","meaningCN":"杂交的过程","example":"Hybridization produced fertile seeds.","exampleCN":"杂交产生了可育的种子。"},{"word":"hybridism","structure":"hybrid + -ism (state or practice)","meaning":"the state of being hybrid","meaningCN":"杂交的状态","example":"Hybridism is common where ranges overlap.","exampleCN":"在分布区重叠处，杂交状态很常见。"},{"word":"hybridity","structure":"hybrid + -ity (quality)","meaning":"mixed quality","meaningCN":"混合的性质","example":"Hybridity is a theme in cultural studies.","exampleCN":"混合性是文化研究的一个主题。"},{"word":"hybridoma","structure":"hybrid + -oma (tumour or mass)","meaning":"a fused cell line used to make antibodies","meaningCN":"用于制造抗体的融合细胞系","example":"The hybridoma produces one kind of antibody.","exampleCN":"杂交瘤产生一种抗体。"},{"word":"hybrid-electric","structure":"hybrid + electric","meaning":"using both fuel and electric power","meaningCN":"同时使用燃料与电力的","example":"Hybrid-electric buses cut fuel use.","exampleCN":"混合电动公交车降低了燃料消耗。"}],"latinEntries":[{"word":"hybrida","structure":"hybrida, hybridae (noun, first declension)","meaning":"offspring of two kinds; person of mixed parentage","meaningCN":"两个种类的后代；混合血统的人"},{"word":"ibrida","structure":"ibrida, ibridae (variant spelling of hybrida)","meaning":"a crossbred offspring","meaningCN":"杂交后代"},{"word":"-izare","structure":"Latin -izare, from Greek -izein","meaning":"verb-forming suffix 'to make, do'","meaningCN":"构成动词的后缀，表示「使、做」"}]}},{"word":"hybridization","ipa_uk":"/ˌhaɪbrɪdaɪˈzeɪʃn/","ipa_us":"/ˌhaɪbrɪdəˈzeɪʃn/","definition_zh":"杂交；杂交育种；分子杂交；轨道杂化","definition_en":"the process of producing hybrids, or the technique of combining complementary strands or orbitals","core_image":"两支不同颜色的线被捻成一股，接头处能看出两种颜色","scene":"实验台上两个亲缘很近的植物被人工授粉。记录员写道：Hybridization produced seeds that germinated faster than either parent.","sceneCN":"这里指「杂交过程」（第 1 个义项：让两个不同物种或品种产生后代的过程）；句意为杂交产生的种子比两个亲本都发芽更快。","pos":[{"tag":"n.","zh":"杂交；杂交育种；分子杂交；杂化（不可数，复数 hybridizations 指多次过程）"}],"collocations":[{"phrase":"plant hybridization","zh":"植物杂交"},{"phrase":"hybridization technique","zh":"杂交技术"},{"phrase":"DNA hybridization","zh":"脱氧核糖核酸杂交"},{"phrase":"in situ hybridization","zh":"原位杂交"},{"phrase":"orbital hybridization","zh":"轨道杂化"},{"phrase":"interspecific hybridization","zh":"种间杂交"},{"phrase":"hybridization breeding","zh":"杂交育种"}],"forms":[{"label":"复数（指多次过程）","form":"hybridizations"},{"label":"动词","form":"hybridize（使杂交）"},{"label":"名词（杂交后代）","form":"hybrid（杂种；杂交后代）"},{"label":"形容词","form":"hybrid（杂交的）"},{"label":"分词形容词（正在杂交的）","form":"hybridizing（杂交中的）"},{"label":"名词（杂交状态）","form":"hybridism（杂交性）"}],"derivatives":[{"word":"hybridize","pos":"v.","zh":"使杂交；杂交"},{"word":"hybrid","pos":"n./adj.","zh":"杂种；杂交后代 / 杂交的"},{"word":"hybridism","pos":"n.","zh":"杂交性；混合性"},{"word":"hybridity","pos":"n.","zh":"混合性；杂合性"},{"word":"hybridoma","pos":"n.","zh":"杂交瘤"}],"senses":[{"no":"01","title":"The process of crossing","titleCN":"杂交过程","definition":"the process by which individuals of different species or varieties produce offspring","definitionCN":"不同物种或品种的个体产生后代的过程","example":"Hybridization produced seeds that germinated faster than either parent.","exampleCN":"杂交产生的种子比两个亲本都发芽更快。","why":"The suffix -ization names a process, so the word looks at the crossing as an event rather than at the offspring.","whyCN":"后缀 -ization 命名过程，因此这个词把杂交看作事件，而不是看作后代。"},{"no":"02","title":"Hybridization breeding","titleCN":"杂交育种","definition":"the deliberate crossing of selected parents to produce improved varieties","definitionCN":"有意让选配的亲本杂交以产生改良品种","example":"Hybridization gave the farm a wheat that ripens earlier.","exampleCN":"杂交育种为农场带来了一个更早成熟的麦种。","why":"Agriculture turns the natural process into a planned method, repeated until a stable variety appears.","whyCN":"农业把自然过程变成有计划的方法，重复进行直到稳定品种出现。"},{"no":"03","title":"Molecular hybridization","titleCN":"分子杂交","definition":"the pairing of complementary nucleic acid strands from different sources","definitionCN":"来自不同来源的互补核酸链配对","example":"DNA hybridization showed that the two samples shared a sequence.","exampleCN":"脱氧核糖核酸杂交显示两个样本共享一段序列。","why":"The word is borrowed for molecules because two complementary strands also 'cross' and pair into one double structure.","whyCN":"这个词被借用于分子，因为两条互补链也会「交叉」并配对成一个双链结构。"},{"no":"04","title":"In situ hybridization","titleCN":"原位杂交（技术）","definition":"a technique that detects a specific sequence inside intact cells or tissue","definitionCN":"在完整细胞或组织内检测特定序列的技术","example":"In situ hybridization located the gene within the tissue.","exampleCN":"原位杂交在组织内定位了该基因。","why":"The method keeps the sample in place, so the pairing of probe and target is read exactly where it happens.","whyCN":"这种方法让样本保持原位，因此探针与靶标的配对就在发生处被读出。"},{"no":"05","title":"Somatic cell hybridization","titleCN":"体细胞杂交","definition":"the fusion of two cells from different sources into one hybrid cell","definitionCN":"把不同来源的两个细胞融合成一个杂交细胞","example":"Somatic hybridization joined the two cell lines in the dish.","exampleCN":"体细胞杂交在培养皿中把两个细胞系合在一起。","why":"Here the 'cross' is between whole cells rather than organisms, and the result is a single fused cell.","whyCN":"这里的「交叉」发生在整个细胞之间而非生物体之间，结果是一个融合细胞。"},{"no":"06","title":"Orbital hybridization","titleCN":"轨道杂化","definition":"the mixing of atomic orbitals into new equivalent orbitals","definitionCN":"原子轨道混合成新的等价轨道","example":"Orbital hybridization explains the shape of the methane molecule.","exampleCN":"轨道杂化解释了甲烷分子的形状。","why":"Chemistry borrows the word for the mixing of orbitals, where distinct shapes combine into new ones.","whyCN":"化学借用这个词指轨道的混合，不同的形状组合成新的形状。"},{"no":"07","title":"Interspecific hybridization","titleCN":"种间杂交（进化）","definition":"crossing between different species, which may transfer genes between them","definitionCN":"不同物种之间的杂交，可能在它们之间转移基因","example":"Interspecific hybridization can introduce new alleles into a species.","exampleCN":"种间杂交可以把新等位基因引入一个物种。","why":"In evolution the process is a channel for gene flow, and the word names the channel rather than the product.","whyCN":"在进化中，这一过程是基因流动的通道，这个词命名通道而非产物。"},{"no":"08","title":"Cultural hybridization","titleCN":"文化混合（比喻）","definition":"the blending of cultural forms into something new","definitionCN":"文化形式融合成新事物的过程","example":"Cultural hybridization shaped the city's food and music.","exampleCN":"文化混合塑造了这座城市的饮食与音乐。","why":"The biological process becomes a metaphor for traditions meeting and producing a new form.","whyCN":"生物过程变成隐喻，指传统相遇并产生新的形式。"}],"etymology":{"intro":{"en":"Hybridization is an English derivative: hybrid plus -ization. Hybrid comes from Latin hybrida. Dates are approximate.","cn":"hybridization 是英语派生词：hybrid 加 -ization。hybrid 来自拉丁 hybrida。年代均为约数。"},"items":[{"era":"LATIN HYBRIDA","en":"Hybrida named the offspring of two kinds; English hybrid descends from it and supplies the base of hybridization.","cn":"hybrida 指两个种类的后代；英语 hybrid 承自它，并提供 hybridization 的词基。"},{"era":"SUFFIX -IZATION","en":"The suffix -ization came through French from Latin -izatio, a noun of process built on -izare.","cn":"后缀 -ization 经法语来自拉丁 -izatio，是建立在 -izare 之上的过程名词。"},{"era":"NINETEENTH CENTURY","en":"Hybridization spread in the nineteenth century with scientific breeding and the new study of heredity.","cn":"hybridization 在 19 世纪随科学育种与新的遗传研究而传播。"},{"era":"MOLECULAR SENSE","en":"The twentieth century added molecular hybridization, once complementary nucleic acid strands could be paired in the lab.","cn":"20 世纪增添了分子杂交义，当时互补核酸链已能在实验室中配对。"},{"era":"CHEMICAL SENSE","en":"Orbital hybridization became a standard term in chemistry after the development of valence theory.","cn":"价键理论发展之后，轨道杂化成为化学的标准术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the first use of hybridization in each technical field is dated only approximately, and the origin of Latin hybrida remains disputed.","cn":"来源不确定（首见年代）：hybridization 在各专业领域的最早使用只有大致年代；拉丁 hybrida 的来源仍有争议。"}]},"similar":{"note":{"en":"Group one holds forms from the same hybrid family; group two holds other terms for crossing or combining.","cn":"第一组是同出 hybrid 词族的形式；第二组是表示杂交或组合的其他术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hybridize","ipa":"/ˈhaɪbrɪdaɪz/","tag":"the verb","definition":"To carry out a cross; hybridization is the process noun built from that verb.","definitionCN":"指实施杂交；hybridization 是由该动词构成的过程名词。"},{"word":"hybrid","ipa":"/ˈhaɪbrɪd/","tag":"the product","definition":"The offspring or the mixed thing itself; hybridization names the making of it.","definitionCN":"指后代或混合事物本身；hybridization 命名其制造过程。"},{"word":"hybridism","ipa":"/ˈhaɪbrɪdɪzəm/","tag":"the state","definition":"The condition of being hybrid; it is a state, not a process or technique.","definitionCN":"指作为杂交体的状况；是状态，不是过程或技术。"},{"word":"hybridity","ipa":"/haɪˈbrɪdəti/","tag":"cultural quality","definition":"The quality of mixed origin, common in cultural theory; it does not name a laboratory method.","definitionCN":"指混合来源的性质，常见于文化理论；不命名实验室方法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crossbreeding","ipa":"/ˈkrɒsbriːdɪŋ/","tag":"breeding practice","definition":"Deliberate breeding across breeds or varieties; it is close to hybridization but usually applied to farm stock.","definitionCN":"指跨品种或品系的有意繁育；接近 hybridization，但多用于畜禽。"},{"word":"crossing","ipa":"/ˈkrɒsɪŋ/","tag":"general act","definition":"The act of crossing two individuals; it is the plain word, while hybridization is the technical process noun.","definitionCN":"指让两个个体杂交的行为；是朴素说法，而 hybridization 是专业过程名词。"},{"word":"introgression","ipa":"/ˌɪntrəˈɡreʃn/","tag":"gene flow","definition":"The movement of genes from one species into another through repeated crossing; it names the genetic result.","definitionCN":"指基因通过反复杂交从一个物种流入另一个物种；命名遗传结果。"},{"word":"recombination","ipa":"/ˌriːkɒmbɪˈneɪʃn/","tag":"within a genome","definition":"The reshuffling of genes during reproduction; it happens inside a species and is not a cross between species.","definitionCN":"指繁殖过程中基因的重组；发生在物种内部，不是物种间的杂交。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"hybrid + -ization: the process of making a hybrid.","cn":"hybrid + -ization：制造杂交后代的过程。"},{"en":"The family runs hybrid, hybridize, hybridization, hybridism, hybridity.","cn":"同族词包括 hybrid、hybridize、hybridization、hybridism、hybridity。"},{"en":"Fixed phrases mark the fields: plant hybridization, DNA hybridization, orbital hybridization.","cn":"固定搭配标出领域：植物杂交、脱氧核糖核酸杂交、轨道杂化。"},{"en":"The suffix -ization always points to a process, not a product.","cn":"后缀 -ization 总是指向过程，而非产物。"},{"en":"In the lab, hybridization pairs complementary strands; in the field, it pairs parents.","cn":"在实验室里，杂交让互补链配对；在田间，它让亲本配对。"}],"abstract":[{"en":"Picture two colored threads twisted into one cord.","cn":"想象两根不同颜色的线被捻成一股绳。"},{"en":"Picture two recipes merged into one dish served at a single table.","cn":"想象两份菜谱合成一道菜，端上同一张桌子。"},{"en":"Picture two tunes played at once until a third melody emerges.","cn":"想象两支曲子同时演奏，直到浮现出第三段旋律。"}]},"examples":[{"en":"Hybridization between the two species produced fertile offspring.","cn":"两个物种之间的杂交产生了可育后代。"},{"en":"The lab uses hybridization to compare gene sequences.","cn":"实验室用杂交来比较基因序列。"},{"en":"Orbital hybridization explains why the bonds are equal.","cn":"轨道杂化解释了为什么这些键是等长的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「海布里代泽申」——把两种血脉接在一起的那道工序 → 杂交","word":"hybridization"},"root":"hybrid（拉丁 hybrida「不同种类的后代」）+ -ization（拉丁 -izatio，表示过程）；hybrida 的更深来源存疑。","sensesIntro":{"en":"Eight senses follow one process: two sources are crossed, and the process is then named in farming, molecular biology, cytology, chemistry, evolution and culture.","cn":"八个义项围绕同一个过程展开：两个来源被交叉，这个过程再在农业、分子生物学、细胞学、化学、进化与文化中获得名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: two differently colored threads twisted into one cord.","cn":"核心意象：两根不同颜色的线被捻成一股绳。"},"chain":["TWO SOURCES","CROSSING","OFFSPRING FORMED","METHOD REPEATED","STRANDS PAIRED","ORBITALS MIXED"],"branches":[{"senses":"S1 · S7","en":"ORGANISMS AND SPECIES: the basic crossing, and the same crossing between distinct species.","cn":"生物体与物种：基本杂交，以及不同物种之间的同一杂交。"},{"senses":"S2","en":"BREEDING: the process becomes a planned agricultural method.","cn":"育种：这个过程成为有计划的农业方法。"},{"senses":"S3 · S4","en":"MOLECULES: complementary strands pair, and the pairing can be read inside intact tissue.","cn":"分子：互补链配对，而且这种配对可在完整组织内被读出。"},{"senses":"S5","en":"CELLS: whole cells fuse into one hybrid cell.","cn":"细胞：整个细胞融合成一个杂交细胞。"},{"senses":"S6 · S8","en":"CHEMISTRY AND CULTURE: orbitals mix, and traditions blend.","cn":"化学与文化：轨道混合，传统融合。"}]},"affixes":{"intro":{"en":"Hybridization is hybrid plus the process suffix -ization; the base is Latin, the suffix came through French, and the word is a standard technical formation.","cn":"hybridization 是 hybrid 加过程后缀 -ization；词基为拉丁来源，后缀经法语而来，整体是标准的技术构词。"},"latinIntro":{"en":"Latin hybrida gives the base hybrid, and Latin -izatio (through French -isation) gives the suffix; the deeper origin of hybrida is disputed.","cn":"拉丁 hybrida 给出词基 hybrid，拉丁 -izatio（经法语 -isation）给出后缀；hybrida 的更深来源有争议。"},"items":[{"word":"hybrid","structure":"Latin hybrida (offspring of two kinds)","meaning":"a crossbred thing","meaningCN":"杂交事物","example":"The hybrid is the product of the process.","exampleCN":"hybrid 是这一过程的产物。"},{"word":"-ize","structure":"Latin -izare, through French -iser","meaning":"to make, cause","meaningCN":"使；使成为","example":"Hybridize is the verb behind the noun.","exampleCN":"hybridize 是这一名词背后的动词。"},{"word":"-ization","structure":"Latin -izatio, through French -isation","meaning":"the process of making","meaningCN":"使……化的过程","example":"The suffix marks a process, not a result.","exampleCN":"这个后缀标记过程，而非结果。"},{"word":"hybridize","structure":"hybrid + -ize","meaning":"to cross or combine","meaningCN":"使杂交；使组合","example":"The plants hybridize easily.","exampleCN":"这些植物容易杂交。"},{"word":"hybridization","structure":"hybridize + -ation","meaning":"the crossing process","meaningCN":"杂交过程","example":"Hybridization can transfer useful genes.","exampleCN":"杂交可以转移有用的基因。"},{"word":"hybridism","structure":"hybrid + -ism (state)","meaning":"the state of being hybrid","meaningCN":"杂交状态","example":"Hybridism appears where two ranges meet.","exampleCN":"两个分布区相接处会出现杂交状态。"},{"word":"hybridity","structure":"hybrid + -ity (quality)","meaning":"mixed quality","meaningCN":"混合性质","example":"Hybridity describes cultural mixing.","exampleCN":"hybridity 描述文化混合。"},{"word":"hybridoma","structure":"hybrid + -oma (mass)","meaning":"a fused antibody-producing cell line","meaningCN":"产生抗体的融合细胞系","example":"Hybridoma technology relies on cell fusion.","exampleCN":"杂交瘤技术依赖细胞融合。"}],"latinEntries":[{"word":"hybrida","structure":"hybrida, hybridae (noun, first declension)","meaning":"offspring of two kinds","meaningCN":"两个种类的后代"},{"word":"-izatio","structure":"Latin -izatio, -izationis (noun suffix)","meaning":"process of making","meaningCN":"使……化的过程"},{"word":"-izare","structure":"Latin -izare, from Greek -izein","meaning":"to make, do","meaningCN":"使；做"}]}},{"word":"hybridize","ipa_uk":"/ˈhaɪbrɪdaɪz/","ipa_us":"/ˈhaɪbrɪdaɪz/","definition_zh":"使杂交；杂交；培育杂交种；使杂化；使混合","definition_en":"to produce a hybrid by crossing different species or varieties, or to combine different elements","core_image":"两株不同的植物并排种下，风把花粉从一株带到另一株","scene":"育种计划把两种耐寒牧草种在同一块地，让它们自然授粉。负责人说：We hybridize the two grasses to get a stronger winter variety.","sceneCN":"这里指「使杂交」（第 1 个义项：让两个不同物种或品种交配产生后代）；句意为我们把两种草杂交，以获得更耐冬的品种。","pos":[{"tag":"vt.","zh":"使杂交；培育杂交种；使杂化；使混合"},{"tag":"vi.","zh":"杂交；与……杂交（常与 with 连用）"}],"collocations":[{"phrase":"hybridize plants","zh":"使植物杂交"},{"phrase":"hybridize species","zh":"使物种杂交"},{"phrase":"hybridize with","zh":"与……杂交"},{"phrase":"hybridize DNA","zh":"使脱氧核糖核酸杂交"},{"phrase":"hybridize orbitals","zh":"使轨道杂化"},{"phrase":"hybridize two varieties","zh":"使两个品种杂交"},{"phrase":"hybridize in the lab","zh":"在实验室中杂交"}],"forms":[{"label":"三单（he/she/it）","form":"hybridizes"},{"label":"过去式","form":"hybridized"},{"label":"过去分词","form":"hybridized"},{"label":"现在分词","form":"hybridizing"},{"label":"名词（杂交）","form":"hybridization（杂交）"},{"label":"名词（杂交后代）","form":"hybrid（杂种）"}],"derivatives":[{"word":"hybridization","pos":"n.","zh":"杂交；杂化"},{"word":"hybrid","pos":"n./adj.","zh":"杂种；杂交后代 / 杂交的"},{"word":"hybridism","pos":"n.","zh":"杂交性；混合性"},{"word":"hybridity","pos":"n.","zh":"混合性；杂合性"},{"word":"hybridizer","pos":"n.","zh":"从事杂交的人；杂交育种者"}],"senses":[{"no":"01","title":"To cross different kinds","titleCN":"使杂交（基本义）","definition":"to cause individuals of different species or varieties to produce offspring","definitionCN":"促使不同物种或品种的个体产生后代","example":"We hybridize the two grasses to get a stronger winter variety.","exampleCN":"我们把两种草杂交，以获得更耐冬的品种。","why":"The verb is the action behind the noun: two parents are brought together so that one offspring carries both.","whyCN":"这个动词是名词背后的动作：两个亲本被带到一起，使一个后代同时携带双方。"},{"no":"02","title":"To breed a hybrid variety","titleCN":"培育杂交品种","definition":"to produce a new variety by repeated planned crossing","definitionCN":"通过反复有计划杂交培育出新品种","example":"Breeders hybridized the lines for five seasons.","exampleCN":"育种者连续五个季节对这些品系进行杂交。","why":"In agriculture the verb names the whole breeding program, not just one mating.","whyCN":"在农业中，这个动词命名整个育种计划，而不只是一次交配。"},{"no":"03","title":"To cross with another kind","titleCN":"与……杂交（不及物）","definition":"to interbreed with a different species or variety","definitionCN":"与不同物种或品种相互交配","example":"The two species hybridize wherever their ranges overlap.","exampleCN":"两个物种在分布区重叠处都会杂交。","why":"Without an object, the verb describes what happens naturally where two kinds meet.","whyCN":"不带宾语时，这个动词描述两个种类相遇处自然发生的事。"},{"no":"04","title":"To hybridize nucleic acids","titleCN":"使核酸杂交（实验）","definition":"to allow complementary nucleic acid strands to pair","definitionCN":"让互补的核酸链配对","example":"The technician hybridized the probe with the sample.","exampleCN":"技术员让探针与样本杂交。","why":"Molecular biology uses the verb for the pairing of strands, because two complementary sequences also join into one double structure.","whyCN":"分子生物学用这个动词指链的配对，因为两段互补序列也会结合成一个双链结构。"},{"no":"05","title":"To hybridize orbitals","titleCN":"使轨道杂化（化学）","definition":"to mix atomic orbitals into new equivalent orbitals","definitionCN":"把原子轨道混合成新的等价轨道","example":"Carbon hybridizes its orbitals before forming four bonds.","exampleCN":"碳在形成四个键之前先使轨道杂化。","why":"Chemistry extends the verb to the mixing of orbital shapes, where distinct forms combine into new ones.","whyCN":"化学把这个动词扩展到轨道形状的混合，不同的形状组合成新的形状。"},{"no":"06","title":"To blend different elements","titleCN":"使混合；使融合（比喻）","definition":"to combine different styles, methods or traditions","definitionCN":"把不同风格、方法或传统组合起来","example":"The chef hybridizes southern and coastal recipes.","exampleCN":"这位厨师把南方与沿海的菜谱融合在一起。","why":"The crossing picture is borrowed for any deliberate blending of two sources into a new form.","whyCN":"杂交图像被借用来形容任何把两个来源有意融合成新形式的行为。"},{"no":"07","title":"To become a hybrid","titleCN":"成为杂合体","definition":"to take on a mixed genetic makeup","definitionCN":"形成混合的遗传组成","example":"The population hybridized after the barrier was removed.","exampleCN":"障碍移除后，这个群体变成了杂合群体。","why":"The verb can describe the result for a group: over time, mixing changes what the population is.","whyCN":"这个动词可以描述一个群体的结果：随着时间推移，混合改变了群体本身。"},{"no":"08","title":"To combine two systems","titleCN":"使两种系统结合（技术）","definition":"to join two technical systems into one working unit","definitionCN":"把两个技术系统接合成一个工作单元","example":"Engineers hybridized the battery system with the older engine.","exampleCN":"工程师把电池系统与较旧的发动机结合。","why":"Engineering keeps the biological structure of joining two sources, but the result is a machine rather than an organism.","whyCN":"工程保留「接合两个来源」的生物结构，但结果是一台机器，而不是生物体。"}],"etymology":{"intro":{"en":"Hybridize is an English verb formed from hybrid plus -ize. Hybrid comes from Latin hybrida, whose deeper origin is disputed. Dates are approximate.","cn":"hybridize 是由 hybrid 加 -ize 构成的英语动词。hybrid 来自拉丁 hybrida，其更深来源有争议。年代均为约数。"},"items":[{"era":"LATIN HYBRIDA","en":"Hybrida named the offspring of two kinds and supplies the base of the English verb.","cn":"hybrida 指两个种类的后代，并提供这个英语动词的词基。"},{"era":"SUFFIX -IZE","en":"The suffix -ize came through French from Latin -izare, itself from Greek -izein, and forms verbs meaning 'to make or cause'.","cn":"后缀 -ize 经法语来自拉丁 -izare，后者又出自希腊 -izein，构成表示「使、使成为」的动词。"},{"era":"NINETEENTH CENTURY","en":"Hybridize spread with scientific breeding in the nineteenth century, when crossing became an experimental practice.","cn":"hybridize 随 19 世纪的科学育种而传播，当时杂交成为一项实验操作。"},{"era":"MOLECULAR EXTENSION","en":"The twentieth century added the molecular sense, as complementary strands were made to pair in the laboratory.","cn":"20 世纪增添了分子义，当时互补链已能在实验室中配对。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and root): the first use of the verb is dated only approximately, and the origin of Latin hybrida is not settled.","cn":"来源不确定（首见年代与词根）：这个动词的最早使用只有大致年代；拉丁 hybrida 的来源未有定论。"}]},"similar":{"note":{"en":"Group one holds forms from the same hybrid family that are easily confused with the verb; group two holds verbs for crossing or combining.","cn":"第一组是同出 hybrid 词族、容易与动词混淆的形式；第二组是表示杂交或组合的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hybrid","ipa":"/ˈhaɪbrɪd/","tag":"the noun","definition":"The product or the adjective; hybridize is the action that produces it.","definitionCN":"指产物或形容词；hybridize 是产生它的动作。"},{"word":"hybridization","ipa":"/ˌhaɪbrɪdaɪˈzeɪʃn/","tag":"the process","definition":"The process noun; the verb names the act, the noun names the whole process or technique.","definitionCN":"指过程名词；动词命名行为，名词命名整个过程或技术。"},{"word":"hybridism","ipa":"/ˈhaɪbrɪdɪzəm/","tag":"the state","definition":"The state of being hybrid; it cannot take an object and is not an action.","definitionCN":"指杂交状态；不能带宾语，也不是动作。"},{"word":"hybridizer","ipa":"/ˈhaɪbrɪdaɪzə/","tag":"the person","definition":"A person who hybridizes; the -er suffix names the agent, not the action.","definitionCN":"指从事杂交的人；-er 后缀命名施动者，而非动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cross","ipa":"/krɒs/","tag":"plain verb","definition":"To breed one individual with another; it is the everyday verb, while hybridize is technical.","definitionCN":"指让一个个体与另一个繁育；是日常动词，而 hybridize 更专业。"},{"word":"crossbreed","ipa":"/ˈkrɒsbriːd/","tag":"breeding verb","definition":"To breed animals or plants from different breeds; it is usual in farming and less common in molecular contexts.","definitionCN":"指让不同品种的动植物繁育；常用于农业，较少用于分子语境。"},{"word":"interbreed","ipa":"/ˌɪntəˈbriːd/","tag":"population verb","definition":"To breed within or between populations; it often describes what happens naturally in a zone of contact.","definitionCN":"指在群体内部或群体之间繁育；常描述接触地带自然发生的事。"},{"word":"combine","ipa":"/kəmˈbaɪn/","tag":"general verb","definition":"To join two things into one; it is broader and carries no biological crossing.","definitionCN":"指把两个事物合成一个；范围更广，不含生物杂交。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"hybrid + -ize: to make a hybrid.","cn":"hybrid + -ize：使成为杂交体。"},{"en":"The family runs hybrid, hybridization, hybridism, hybridity, hybridizer.","cn":"同族词包括 hybrid、hybridization、hybridism、hybridity、hybridizer。"},{"en":"Fixed phrases mark the fields: hybridize plants, hybridize DNA, hybridize orbitals.","cn":"固定搭配标出领域：使植物杂交、使脱氧核糖核酸杂交、使轨道杂化。"},{"en":"The verb is transitive for a person's action and intransitive for a natural event.","cn":"这个动词用于人的操作时及物，用于自然事件时不及物。"},{"en":"In the lab, you hybridize a probe; in the field, two species hybridize.","cn":"在实验室里，你让探针杂交；在野外，两个物种自行杂交。"}],"abstract":[{"en":"Picture two hands clasping into one grip.","cn":"想象两只手扣成一个握姿。"},{"en":"Picture two languages borrowing words until a new slang appears.","cn":"想象两种语言互相借词，直到出现新的俚语。"},{"en":"Picture two roads merging into a single wider road.","cn":"想象两条路汇合成一条更宽的路。"}]},"examples":[{"en":"The two oak species hybridize where their forests meet.","cn":"两个栎树种在森林相接处发生杂交。"},{"en":"Scientists hybridized the crop with a wild relative for drought tolerance.","cn":"科学家让该作物与一个野生近缘种杂交以获得耐旱性。"},{"en":"The two methods were hybridized into a single workflow.","cn":"两种方法被融合成一套工作流程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「海布里代兹」——把两样东西接在一起，让它们生出一个新的 → 使杂交","word":"hybridize"},"root":"hybrid（拉丁 hybrida「不同种类的后代」）+ -ize（拉丁 -izare，经法语，表示「使」）；hybrida 的更深来源存疑。","sensesIntro":{"en":"Eight senses follow one action: two sources are made to cross, whether parents, species, strands, orbitals, styles or systems.","cn":"八个义项围绕同一个动作展开：两个来源被促使交叉，可以是亲本、物种、链、轨道、风格或系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: pollen carried from one plant to another.","cn":"核心意象：花粉从一株植物被带到另一株。"},"chain":["TWO KINDS MEET","CROSS PERFORMED","OFFSPRING PRODUCED","VARIETY BRED","STRANDS PAIRED","SYSTEMS JOINED"],"branches":[{"senses":"S1 · S2","en":"CROSSING AND BREEDING: one mating, and a repeated program that produces a variety.","cn":"杂交与育种：一次交配，以及产生品种的重复计划。"},{"senses":"S3 · S7","en":"NATURAL AND POPULATION: species cross on their own, and a whole population becomes mixed.","cn":"自然与群体：物种自行杂交，整个群体变得混合。"},{"senses":"S4","en":"MOLECULES: complementary strands are made to pair.","cn":"分子：互补链被促使配对。"},{"senses":"S5","en":"CHEMISTRY: orbitals are mixed into new shapes.","cn":"化学：轨道被混合成新形状。"},{"senses":"S6 · S8","en":"STYLES AND SYSTEMS: recipes, methods or machines are joined.","cn":"风格与系统：菜谱、方法或机器被接合。"}]},"affixes":{"intro":{"en":"Hybridize is a verb of the form base plus -ize; the base is the Latin noun hybrida, and the suffix marks making or causing.","cn":"hybridize 是「词基加 -ize」的动词；词基是拉丁名词 hybrida，后缀标记「使、使成为」。"},"latinIntro":{"en":"Latin hybrida supplies the base, and Latin -izare (through French -iser) supplies the verb ending; the deeper origin of hybrida is disputed.","cn":"拉丁 hybrida 提供词基，拉丁 -izare（经法语 -iser）提供动词词尾；hybrida 的更深来源有争议。"},"items":[{"word":"hybrid","structure":"Latin hybrida (offspring of two kinds)","meaning":"a crossbred thing","meaningCN":"杂交事物","example":"The hybrid carries both parents' traits.","exampleCN":"杂交后代携带双亲的性状。"},{"word":"-ize","structure":"Latin -izare, through French -iser","meaning":"to make, cause to be","meaningCN":"使；使成为","example":"The suffix turns a noun into a verb of making.","exampleCN":"这个后缀把名词变成表示「使成为」的动词。"},{"word":"hybridize","structure":"hybrid + -ize","meaning":"to produce a hybrid","meaningCN":"使杂交；产生杂交后代","example":"The species hybridize in contact zones.","exampleCN":"这些物种在接触地带杂交。"},{"word":"hybridization","structure":"hybridize + -ation (process)","meaning":"the process of crossing","meaningCN":"杂交过程","example":"Hybridization follows the cross.","exampleCN":"杂交过程紧随这次杂交之后。"},{"word":"hybrid","structure":"hybrid (noun used as adjective)","meaning":"crossbred; mixed","meaningCN":"杂交的；混合的","example":"A hybrid plant may be sterile.","exampleCN":"杂交植物可能不育。"},{"word":"hybridism","structure":"hybrid + -ism (state)","meaning":"the condition of being hybrid","meaningCN":"杂交状况","example":"Hybridism is common in disturbed habitats.","exampleCN":"在受扰动的生境中，杂交状况很常见。"},{"word":"hybridity","structure":"hybrid + -ity (quality)","meaning":"mixed quality","meaningCN":"混合性质","example":"Hybridity is valued in cultural studies.","exampleCN":"混合性在文化研究中受到重视。"},{"word":"hybridizer","structure":"hybridize + -er (agent)","meaning":"one who hybridizes","meaningCN":"从事杂交的人","example":"The hybridizer recorded every cross.","exampleCN":"杂交育种者记录了每一次杂交。"}],"latinEntries":[{"word":"hybrida","structure":"hybrida, hybridae (noun, first declension)","meaning":"offspring of two kinds","meaningCN":"两个种类的后代"},{"word":"-izare","structure":"Latin -izare, from Greek -izein","meaning":"to make, do","meaningCN":"使；做"}]}},{"word":"crossbreeding","ipa_uk":"/ˈkrɒsbriːdɪŋ/","ipa_us":"/ˈkrɑːsbriːdɪŋ/","definition_zh":"杂交；杂交育种；异系交配","definition_en":"the practice of breeding individuals from different breeds, varieties or species","core_image":"两个不同血统的畜群被分栏管理，再按计划配对","scene":"牧场把两种不同血统的牛分开管理，再按计划配种。技术员解释：Crossbreeding brings new traits into the herd without losing milk yield.","sceneCN":"这里指「杂交育种」（第 1 个义项：让不同品种或品系的个体交配繁育）；句意为杂交育种把新性状带入牛群，同时不损失产奶量。","pos":[{"tag":"n.","zh":"杂交；杂交育种；异系交配（不可数）"}],"collocations":[{"phrase":"crossbreeding of cattle","zh":"牛的杂交育种"},{"phrase":"crossbreeding program","zh":"杂交育种计划"},{"phrase":"crossbreeding experiments","zh":"杂交实验"},{"phrase":"crossbreeding between species","zh":"物种间的杂交"},{"phrase":"controlled crossbreeding","zh":"受控杂交"},{"phrase":"crossbreeding and inbreeding","zh":"杂交与近交"}],"forms":[{"label":"复数（指多次杂交）","form":"crossbreedings"},{"label":"动词","form":"crossbreed（使杂交）"},{"label":"过去式","form":"crossbred"},{"label":"过去分词","form":"crossbred"},{"label":"名词（杂交后代）","form":"crossbreed（杂交后代）"},{"label":"形容词（杂交的）","form":"crossbred（杂交的）"}],"derivatives":[{"word":"crossbreed","pos":"v./n.","zh":"使杂交 / 杂交后代"},{"word":"crossbred","pos":"adj./n.","zh":"杂交的 / 杂交后代"},{"word":"cross","pos":"v./n.","zh":"使杂交 / 杂交"},{"word":"outcrossing","pos":"n.","zh":"异系交配；远交"},{"word":"hybridization","pos":"n.","zh":"杂交；杂化"}],"senses":[{"no":"01","title":"Breeding across different kinds","titleCN":"杂交育种（基本义）","definition":"the practice of mating individuals from different breeds, varieties or species","definitionCN":"让不同品种、品系或物种的个体交配繁育的做法","example":"Crossbreeding brings new traits into the herd without losing milk yield.","exampleCN":"杂交育种把新性状带入牛群，同时不损失产奶量。","why":"Cross- marks the joining of two lineages, and breeding names the controlled production of offspring.","whyCN":"cross- 标记两个世系的接合，breeding 命名对后代的有控生产。"},{"no":"02","title":"The process of cross-breeding","titleCN":"杂交繁育过程","definition":"the repeated process of producing offspring from different lines","definitionCN":"由不同品系反复产生后代的过程","example":"Crossbreeding continued for four generations before selection began.","exampleCN":"杂交繁育持续了四代，之后才开始选择。","why":"The -ing form names the ongoing activity rather than a single mating.","whyCN":"-ing 形式命名持续的活动，而不是一次交配。"},{"no":"03","title":"Crossbreeding in livestock","titleCN":"畜牧中的杂交","definition":"the use of different cattle, sheep or pig breeds to combine production traits","definitionCN":"利用不同牛、羊或猪品种来组合生产性状","example":"Crossbreeding improved growth rate in the beef herd.","exampleCN":"杂交提高了肉牛群的生长速度。","why":"Farmers cross breeds to combine milk, meat or hardiness that no single breed supplies well.","whyCN":"农民让品种杂交，以组合任何单一品种都无法充分提供的产奶、产肉或耐性。"},{"no":"04","title":"Crossbreeding in plants","titleCN":"植物杂交","definition":"the crossing of plant varieties or lines to create new combinations","definitionCN":"让植物品种或品系杂交以产生新组合","example":"Crossbreeding two wheat lines produced a sturdier stem.","exampleCN":"两个小麦品系杂交产生了更粗壮的茎。","why":"Plants allow controlled pollination, so the same practice becomes a field technique.","whyCN":"植物可以人工控制授粉，因此同一做法成为田间技术。"},{"no":"05","title":"Crossbreeding in animals","titleCN":"动物杂交","definition":"the mating of animals from different breeds or populations","definitionCN":"不同品种或种群的动物交配","example":"Crossbreeding the two deer populations raised genetic diversity.","exampleCN":"两个鹿种群的杂交提高了遗传多样性。","why":"In animals the practice may be planned for production or allowed to restore diversity in small populations.","whyCN":"在动物中，这种做法可以是为生产而计划，也可以是为恢复小群体的多样性而允许发生。"},{"no":"06","title":"Crossbreeding with a wild relative","titleCN":"与野生近缘种杂交","definition":"crossing a domesticated line with a wild relative to transfer useful traits","definitionCN":"让家养品系与野生近缘种杂交以转移有用性状","example":"Crossbreeding with a wild grass added salt tolerance.","exampleCN":"与一种野生草杂交增添了耐盐性。","why":"Wild relatives hold traits that domestication lost, and crossing brings them back into the crop.","whyCN":"野生近缘种保留着驯化过程中丢失的性状，杂交把它们带回作物。"},{"no":"07","title":"The production of crossbred offspring","titleCN":"杂交后代的产生","definition":"the result of crossing, viewed as the appearance of mixed offspring","definitionCN":"杂交的结果，即混合后代的出现","example":"Crossbreeding produced calves that gained weight faster.","exampleCN":"杂交产生了增重更快的犊牛。","why":"The noun can focus on the outcome, where the mixed offspring are the point of the practice.","whyCN":"这个名词可以聚焦结果，此时混合后代才是做法的重点。"},{"no":"08","title":"A metaphor for mixing sources","titleCN":"比喻：不同来源的混合（少见）","definition":"a figurative blending of different traditions or sources","definitionCN":"不同传统或来源的比喻性融合","example":"The festival is a crossbreeding of rural and urban customs.","exampleCN":"这个节庆是乡村与城市习俗的混合。","why":"Outside farming the word is rare, but the picture of two lineages producing a new line can describe cultural mixing.","whyCN":"在农业之外这个词很少用，但两个世系产生新世系的图像可以描述文化混合。"}],"etymology":{"intro":{"en":"Crossbreeding joins cross, from Latin crux 'cross', to breeding, from Old English bredan 'to warm, cherish, produce offspring'. The compound is modern. Dates are approximate.","cn":"crossbreeding 把来自拉丁 crux「十字、交叉」的 cross 与来自古英语 bredan「保暖、抚育、生育」的 breeding 结合。这个复合词属近代。年代均为约数。"},"items":[{"era":"LATIN CRUX","en":"Crux meant 'cross, stake'. English cross came through Old Irish and Old Norse forms, and the verb cross developed the sense 'to pass or mix across'.","cn":"crux 意为「十字架、木桩」。英语 cross 经古爱尔兰语与古诺斯语形式传入，动词 cross 又发展出「横跨、交叉混合」的意思。"},{"era":"OLD ENGLISH BREDAN","en":"Bredan meant 'to warm, keep warm, cherish', and by extension 'to produce young'. It is related to brood and broth and belongs to native Germanic stock.","cn":"bredan 意为「保暖、抚育」，引申为「生育幼仔」。它与 brood、broth 相关，属本族日耳曼词。"},{"era":"BREEDING","en":"Breeding developed in Middle English as the noun for producing and raising offspring, and later for the controlled improvement of stock.","cn":"breeding 在中古英语中发展为表示生育与养育后代的名词，后来又指对畜禽的有控改良。"},{"era":"THE COMPOUND","en":"Crossbreeding became a standard term in the nineteenth century, when pedigree breeding and scientific agriculture separated crossing from inbreeding.","cn":"crossbreeding 在 19 世纪成为标准术语，当时谱系育种与科学农业把杂交与近交区分开来。"},{"era":"MODERN USE","en":"Modern use pairs it with inbreeding and outcrossing, and extends it to conservation and plant breeding.","cn":"现代用法把它与近交、远交并列，并扩展到保护生物学与植物育种。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the exact first use of crossbreeding as a single term is not recorded, and the early sense development of the verb cross is complex.","cn":"来源不确定（首见年代）：crossbreeding 作为单一术语的最早使用没有记录；动词 cross 的早期语义发展也很复杂。"}]},"similar":{"note":{"en":"Group one holds forms built on the same cross or breed stock; group two holds breeding terms that are close in meaning.","cn":"第一组是同出 cross 或 breed 词干的形式；第二组是意义接近的繁育术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"crossbreed","ipa":"/ˈkrɒsbriːd/","tag":"the verb or product","definition":"To perform the cross, or the offspring itself; crossbreeding is the practice or process.","definitionCN":"指实施杂交，或指杂交后代本身；crossbreeding 指做法或过程。"},{"word":"crossbred","ipa":"/ˈkrɒsbred/","tag":"the adjective","definition":"Describing an animal produced by crossing; it is a form of the verb, not the name of the practice.","definitionCN":"描述由杂交产生的动物；是动词形式，不是做法名称。"},{"word":"cross","ipa":"/krɒs/","tag":"the plain word","definition":"The plain verb or noun for crossing; crossbreeding is the specialized breeding compound.","definitionCN":"指杂交的普通动词或名词；crossbreeding 是专门的繁育复合词。"},{"word":"inbreeding","ipa":"/ɪnˈbriːdɪŋ/","tag":"the opposite practice","definition":"Breeding close relatives; it is the counterpart that crossbreeding is meant to avoid.","definitionCN":"指近亲繁育；是 crossbreeding 想要避免的对立做法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hybridization","ipa":"/ˌhaɪbrɪdaɪˈzeɪʃn/","tag":"technical process","definition":"The general technical process of making hybrids; crossbreeding is more common in farm stock.","definitionCN":"指制造杂交后代的一般技术过程；crossbreeding 多用于畜禽。"},{"word":"outcrossing","ipa":"/ˈaʊtkrɒsɪŋ/","tag":"bringing in outside stock","definition":"Crossing with an unrelated individual from outside the line; it is a narrower strategy.","definitionCN":"指与品系外无关个体杂交；是一种更窄的策略。"},{"word":"interbreeding","ipa":"/ˌɪntəˈbriːdɪŋ/","tag":"population mixing","definition":"Breeding between different populations or species where they meet; it often happens without planning.","definitionCN":"指不同群体或物种在相遇处的繁育；常无计划地发生。"},{"word":"crossing","ipa":"/ˈkrɒsɪŋ/","tag":"single act","definition":"One act of crossing two individuals; crossbreeding names a sustained practice.","definitionCN":"指让两个个体杂交的一次行为；crossbreeding 命名持续的做法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cross 'across' + breeding 'producing young': producing young across two lines.","cn":"cross「横跨」+ breeding「生育后代」：跨两个世系生育后代。"},{"en":"The family runs cross, crossbreed, crossbred, crossbreeding, outcrossing.","cn":"同族词包括 cross、crossbreed、crossbred、crossbreeding、outcrossing。"},{"en":"Fixed phrases: crossbreeding program, controlled crossbreeding, crossbreeding and inbreeding.","cn":"固定搭配：杂交育种计划、受控杂交、杂交与近交。"},{"en":"Crossbreeding is the opposite of inbreeding: outside lines versus close relatives.","cn":"杂交与近交相对：一个是外来世系，一个是近亲。"},{"en":"Farmers use it to combine traits that no single breed supplies.","cn":"农民用它来组合任何单一品种都无法提供的性状。"}],"abstract":[{"en":"Picture two herds in separate pens, then a gate opened between them.","cn":"想象两个畜群各在栏内，然后两栏之间的门被打开。"},{"en":"Picture two family trees grafted at one branch.","cn":"想象两棵家谱树在一个枝条上嫁接。"},{"en":"Picture two recipes from different regions cooked in one kitchen.","cn":"想象两个地区的菜谱在同一间厨房里烹制。"}]},"examples":[{"en":"Crossbreeding two local breeds raised both milk and heat tolerance.","cn":"两个本地品种的杂交同时提高了产奶量与耐热性。"},{"en":"The crossbreeding program lasted three generations.","cn":"这个杂交育种计划持续了三代。"},{"en":"Crossbreeding can rescue a small population from low diversity.","cn":"杂交可以把一个小群体从低多样性中挽救出来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「克罗斯布里丁」——两群不同的家畜跨过栏杆配到一起 → 杂交育种","word":"crossbreeding"},"root":"cross（拉丁 crux「十字、交叉」，经古爱尔兰语与古诺斯语进入英语）+ breeding（古英语 bredan「保暖、抚育、生育」）；本族日耳曼词与拉丁借词构成的复合词。","sensesIntro":{"en":"Eight senses follow one practice: two separate lines are brought together, and the practice is then named for livestock, crops, wild relatives, its offspring and occasionally culture.","cn":"八个义项围绕同一种做法展开：两个分开的世系被带到一起，这种做法再依次用于畜禽、作物、野生近缘种、其后代，偶尔也用于文化。"},"semanticMap":{"core":{"en":"CORE IMAGE: two herds in separate pens with a gate opened between them.","cn":"核心意象：两个畜群各在栏内，两栏之间的门被打开。"},"chain":["TWO LINES","GATE OPENED","MATING PLANNED","OFFSPRING MIXED","TRAITS COMBINED","PRACTICE NAMED"],"branches":[{"senses":"S1 · S2","en":"PRACTICE AND PROCESS: the general practice, and the ongoing activity over generations.","cn":"做法与过程：一般做法，以及跨世代的持续活动。"},{"senses":"S3 · S4 · S5","en":"FARM STOCK: cattle, crops and animals each apply the same practice.","cn":"农场畜禽：牛、作物与动物都应用同一做法。"},{"senses":"S6","en":"WILD RELATIVES: crossing brings lost traits back from wild lines.","cn":"野生近缘种：杂交把丢失的性状从野生世系带回。"},{"senses":"S7","en":"OFFSPRING: the mixed young are the visible result.","cn":"后代：混合的幼仔是可见的结果。"},{"senses":"S8","en":"METAPHOR: cultural traditions can be crossed like lines.","cn":"比喻：文化传统也可以像世系一样被杂交。"}]},"affixes":{"intro":{"en":"Crossbreeding is a compound of two free English words: cross, ultimately from Latin crux, and breeding, from native Old English bredan.","cn":"crossbreeding 是两个英语自由词的复合：cross 最终来自拉丁 crux，breeding 来自本族古英语 bredan。"},"latinIntro":{"en":"Only the first element is Latin: crux 'cross' supplies cross. Breeding and its suffix -ing are native English, not Latin.","cn":"只有第一个成分是拉丁语：crux「十字」提供 cross。breeding 及其后缀 -ing 是英语本族成分，不是拉丁语。"},"items":[{"word":"cross-","structure":"Latin crux (cross), through Irish and Norse forms","meaning":"across; crossing","meaningCN":"横跨；交叉","example":"The prefix marks two lines meeting.","exampleCN":"这个成分标记两个世系相遇。"},{"word":"breed","structure":"Old English bredan (to warm, cherish, produce young)","meaning":"to produce offspring","meaningCN":"生育后代","example":"The verb breed is native English.","exampleCN":"动词 breed 是英语本族词。"},{"word":"-ing","structure":"Old English -ing (action or process)","meaning":"the action or process of","meaningCN":"……的动作或过程","example":"Breeding is the process of producing young.","exampleCN":"breeding 是生育后代的过程。"},{"word":"crossbreed","structure":"cross- + breed","meaning":"to breed across lines","meaningCN":"跨世系繁育","example":"They crossbreed the two lines each spring.","exampleCN":"他们每年春天让两个品系杂交。"},{"word":"crossbred","structure":"cross- + bred (past participle)","meaning":"produced by crossing","meaningCN":"由杂交产生的","example":"The crossbred calves grew faster.","exampleCN":"杂交犊牛长得更快。"},{"word":"crossbreeding","structure":"crossbreed + -ing","meaning":"the practice of crossing lines","meaningCN":"让世系杂交的做法","example":"Crossbreeding raised the herd's diversity.","exampleCN":"杂交提高了牛群的多样性。"},{"word":"outcrossing","structure":"out- + crossing","meaning":"crossing with unrelated outside stock","meaningCN":"与无关的外来个体杂交","example":"Outcrossing avoids close relatives.","exampleCN":"远交避免使用近亲。"},{"word":"inbreeding","structure":"in- (within) + breeding","meaning":"breeding within a close group","meaningCN":"在近亲群体内繁育","example":"Inbreeding reduces vigor over time.","exampleCN":"近交会随时间降低活力。"}],"latinEntries":[{"word":"crux","structure":"crux, crucis (noun, third declension)","meaning":"cross, stake","meaningCN":"十字架；木桩"}]}},{"word":"breeding","ipa_uk":"/ˈbriːdɪŋ/","ipa_us":"/ˈbriːdɪŋ/","definition_zh":"繁殖；育种；饲养；教养；繁殖季","definition_en":"the process of producing offspring, or the controlled improvement of animals and plants","core_image":"春天的鱼塘里，工人忙着分池、配对、记录鱼卵","scene":"鱼塘在春天进入最忙的季节，工人忙着分池和配对。场长说：Breeding starts when the water warms above fifteen degrees.","sceneCN":"这里指「繁殖」（第 1 个义项：生物产生后代的过程）；句意为当水温升到十五度以上时，繁殖就开始了。","pos":[{"tag":"n.","zh":"繁殖；育种；饲养；教养；繁殖季（不可数）"}],"collocations":[{"phrase":"breeding season","zh":"繁殖季"},{"phrase":"breeding program","zh":"育种计划"},{"phrase":"captive breeding","zh":"圈养繁殖"},{"phrase":"selective breeding","zh":"选择育种"},{"phrase":"breeding stock","zh":"种畜"},{"phrase":"breeding ground","zh":"繁殖地；滋生地"},{"phrase":"breeding success","zh":"繁殖成功率"}],"forms":[{"label":"复数（指多次繁育，少见）","form":"breedings"},{"label":"动词","form":"breed（繁殖；饲养）"},{"label":"过去式","form":"bred"},{"label":"过去分词","form":"bred"},{"label":"名词（品种）","form":"breed（品种）"},{"label":"复合名词（杂交）","form":"crossbreeding（杂交）"}],"derivatives":[{"word":"breed","pos":"v./n.","zh":"繁殖；饲养 / 品种"},{"word":"breeder","pos":"n.","zh":"饲养者；育种者"},{"word":"bred","pos":"adj.","zh":"培育的；繁殖的"},{"word":"crossbreeding","pos":"n.","zh":"杂交；杂交育种"},{"word":"inbreeding","pos":"n.","zh":"近亲繁殖"}],"senses":[{"no":"01","title":"The production of offspring","titleCN":"繁殖（基本义）","definition":"the process by which animals or plants produce young","definitionCN":"动物或植物产生后代的过程","example":"Breeding starts when the water warms above fifteen degrees.","exampleCN":"当水温升到十五度以上时，繁殖就开始了。","why":"The core sense is biological: one generation produces the next, with or without human help.","whyCN":"核心义是生物的：一个世代产生下一个世代，无论有没有人帮助。"},{"no":"02","title":"Controlled breeding and improvement","titleCN":"育种（人工选择）","definition":"the deliberate selection of parents to improve a line or breed","definitionCN":"有意选择亲本以改良品系或品种","example":"Selective breeding raised the sugar content of the beets.","exampleCN":"选择育种提高了甜菜的含糖量。","why":"Humans take the natural process and steer it, so breeding becomes a planned method of improvement.","whyCN":"人类接手自然过程并操控方向，于是繁殖成为有计划的改良方法。"},{"no":"03","title":"Keeping and raising animals","titleCN":"饲养；养殖","definition":"the work of keeping animals for reproduction or production","definitionCN":"为繁殖或生产而饲养动物的工作","example":"Fish breeding requires clean water and steady temperature.","exampleCN":"鱼类养殖需要清洁的水与稳定的温度。","why":"Once animals are kept, breeding names the whole husbandry activity, not only the mating.","whyCN":"一旦动物被饲养，breeding 就命名整套养殖活动，而不只是交配。"},{"no":"04","title":"Good manners or upbringing","titleCN":"教养；举止","definition":"the manners and behaviour produced by upbringing","definitionCN":"由养育形成的举止与行为方式","example":"His calm breeding showed in every room he entered.","exampleCN":"他从容的教养在每走进一个房间时都显露出来。","why":"The old metaphor treats upbringing as cultivation: a person is 'bred' the way an animal is bred.","whyCN":"旧的隐喻把养育当作栽培：人像动物一样被「育」出来。"},{"no":"05","title":"The breeding season or behaviour","titleCN":"繁殖季或繁殖行为","definition":"the period or set of behaviours associated with mating","definitionCN":"与交配相关的时期或行为组合","example":"The birds return to the island for breeding in April.","exampleCN":"这些鸟在四月回到岛上繁殖。","why":"Animals breed in seasons, so the noun also names the time and the behaviour that go with reproduction.","whyCN":"动物在特定季节繁殖，因此这个名词也命名与繁殖相伴的时期与行为。"},{"no":"06","title":"Developing a new variety","titleCN":"品种培育","definition":"the long process of producing a stable new variety","definitionCN":"培育稳定新品种的长期过程","example":"The breeding of this rose took twelve years.","exampleCN":"培育这个月季品种花了十二年。","why":"A variety is not made in one cross; breeding names the repeated cycles that stabilize it.","whyCN":"一个品种不是一次杂交就能做成；breeding 命名使它稳定的反复循环。"},{"no":"07","title":"Mating arrangements","titleCN":"配种","definition":"the pairing of selected males and females","definitionCN":"把选定的雌雄个体配对","example":"The breeding of the two prize animals was arranged months ahead.","exampleCN":"两头获奖动物的配种提前几个月就安排好了。","why":"In practice breeding often means the specific pairing decisions a manager makes.","whyCN":"在实践中，breeding 常指管理者做出的具体配对决定。"},{"no":"08","title":"A place or source that fosters something","titleCN":"滋生地；产生源（比喻）","definition":"a situation or place that encourages something to develop","definitionCN":"促使某事物发展的情境或场所","example":"Stagnant water is a breeding ground for mosquitoes.","exampleCN":"积水是蚊子的滋生地。","why":"The picture of animals multiplying in a favorable place extends to anything that lets a problem multiply.","whyCN":"动物在有利场所大量繁殖的图像，被扩展到任何让问题滋生的地方。"}],"etymology":{"intro":{"en":"Breeding is the noun from breed, which comes from Old English bredan 'to warm, cherish, produce young'. The word is native Germanic, with no Latin source. Dates are approximate.","cn":"breeding 是 breed 的名词形式，而 breed 来自古英语 bredan「保暖、抚育、生育」。这个词是本族日耳曼词，没有拉丁语来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH BREDAN","en":"Bredan meant 'to warm, keep warm, cherish', especially young. The sense 'produce offspring' grew from the care given to young animals.","cn":"bredan 意为「保暖、保温、抚育」，尤指抚育幼仔。「生育后代」义从对幼仔的照料发展而来。"},{"era":"RELATED NATIVE WORDS","en":"Breed is related to brood 'a family of young' and broth 'liquid in which food is cooked', both going back to a Germanic root connected with warming.","cn":"breed 与 brood「一窝幼仔」、broth「煮食物的汤液」相关，它们都追溯到与「加温」有关的日耳曼词根。"},{"era":"MIDDLE ENGLISH","en":"In Middle English the verb extended from cherishing the young to producing them, and the noun breeding named the whole process.","cn":"在中古英语中，这个动词从抚育幼仔扩展到生育幼仔，名词 breeding 则命名整个过程。"},{"era":"BREEDING AS UPBRINGING","en":"By the sixteenth century breeding also meant the manners formed by upbringing, a metaphor of cultivation applied to people.","cn":"到 16 世纪，breeding 也指由养育形成的举止，这是把栽培隐喻用于人。"},{"era":"SCIENTIFIC BREEDING","en":"The nineteenth century made breeding a technical term for controlled improvement of plants and stock, alongside pedigree records and selection.","cn":"19 世纪使 breeding 成为有控改良动植物品种的技术术语，并与谱系记录和选择相伴。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the deeper Indo-European origin of the Germanic warming root is reconstructed with competing accounts, and the first use of breeding for manners is dated only approximately.","cn":"来源不确定（词根）：日耳曼「加温」词根的更深印欧来源属重构，存在不同假说；breeding 表示举止的最早使用也只有大致年代。"}]},"similar":{"note":{"en":"Group one holds forms from the same breed family that are easily confused; group two holds near terms for producing and raising young.","cn":"第一组是同出 breed 词族、容易混淆的形式；第二组是表示生育与养育的邻近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"breed","ipa":"/briːd/","tag":"the verb or type","definition":"To produce offspring, or a group of animals of one type; breeding is the process noun.","definitionCN":"指生育后代，或指一类动物；breeding 是过程名词。"},{"word":"bred","ipa":"/bred/","tag":"past form","definition":"The past tense and past participle of breed; it is a verb form, not the activity.","definitionCN":"breed 的过去式与过去分词；是动词形式，不是活动本身。"},{"word":"breeder","ipa":"/ˈbriːdə/","tag":"the person","definition":"A person who breeds animals or plants; the -er suffix names the agent.","definitionCN":"指从事动植物繁育的人；-er 后缀命名施动者。"},{"word":"brood","ipa":"/bruːd/","tag":"a family of young","definition":"The young of one hatching or birth, or to sit on eggs; it is related to breed but names the group or the sitting.","definitionCN":"指一次孵化或生产的一窝幼仔，或指孵蛋；与 breed 相关，但命名群体或孵卧行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"biological term","definition":"The biological process by which organisms make new organisms; it is wider and includes plants and microbes.","definitionCN":"指生物产生新个体的生物学过程；范围更广，包括植物与微生物。"},{"word":"rearing","ipa":"/ˈrɪərɪŋ/","tag":"raising the young","definition":"The care and feeding of young until they are independent; breeding is conception and birth, rearing comes after.","definitionCN":"指对幼体的照料与喂养直到独立；breeding 关乎受孕与出生，rearing 在其后。"},{"word":"propagation","ipa":"/ˌprɒpəˈɡeɪʃn/","tag":"plants and groups","definition":"Producing new plants or spreading a group; it is common in horticulture and can be asexual.","definitionCN":"指产生新植物或扩大群体；常用于园艺，也可以是无性的。"},{"word":"cultivation","ipa":"/ˌkʌltɪˈveɪʃn/","tag":"growing crops","definition":"Preparing land and growing crops; it is about tending plants, not producing offspring.","definitionCN":"指整地并种植作物；关乎照料植物，而非产生后代。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"breed + -ing: the process of producing young.","cn":"breed + -ing：产生后代的过程。"},{"en":"The family runs breed, bred, breeder, breeding, crossbreeding, inbreeding.","cn":"同族词包括 breed、bred、breeder、breeding、crossbreeding、inbreeding。"},{"en":"Fixed phrases: breeding season, breeding program, captive breeding.","cn":"固定搭配：繁殖季、育种计划、圈养繁殖。"},{"en":"Selective breeding is the human-guided version of natural reproduction.","cn":"选择育种是自然繁殖的人为指导版本。"},{"en":"The figurative breeding ground lets a problem multiply like animals.","cn":"比喻的滋生地让问题像动物一样大量繁殖。"}],"abstract":[{"en":"Picture a pond in spring full of eggs and tiny fish.","cn":"想象春天的池塘满是鱼卵与小鱼。"},{"en":"Picture a gardener choosing which plants to let seed.","cn":"想象园丁挑选让哪些植物结籽。"},{"en":"Picture a person whose calm manners were formed at home.","cn":"想象一个人从容的举止是在家里养成的。"}]},"examples":[{"en":"Captive breeding saved the species from extinction.","cn":"圈养繁殖把该物种从灭绝中救了回来。"},{"en":"The breeding program selects for drought tolerance.","cn":"这个育种计划选择耐旱性。"},{"en":"The marsh is a breeding ground for thousands of birds.","cn":"这片沼泽是成千上万只鸟的繁殖地。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「布里丁」——春天里忙着配对、下仔、育幼的那段事 → 繁殖、育种","word":"breeding"},"root":"breed（古英语 bredan「保暖、抚育、生育」）+ -ing；本族日耳曼词，与 brood「一窝幼仔」、broth「汤液」相关，无拉丁语来源。","sensesIntro":{"en":"Eight senses follow one process: animals produce young, humans guide the process, and the same word extends to husbandry, manners, seasons and places where things multiply.","cn":"八个义项围绕同一个过程展开：动物产生后代，人类引导这个过程，同一个词再延伸到养殖、举止、季节以及事物大量滋生的地方。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spring pond busy with eggs, fry and caretakers.","cn":"核心意象：春天的池塘里满是鱼卵、小鱼与忙碌的照料者。"},"chain":["YOUNG PRODUCED","PAIRING ARRANGED","STOCK KEPT","VARIETY IMPROVED","MANNERS FORMED","PLACE FOSTERS"],"branches":[{"senses":"S1 · S5","en":"BIOLOGY AND SEASON: producing young, and the time and behaviour that surround it.","cn":"生物学与季节：产生后代，以及围绕它的时期与行为。"},{"senses":"S2 · S6 · S7","en":"HUMAN GUIDANCE: selection, long variety development and specific pairing decisions.","cn":"人类引导：选择、长期的品种培育，以及具体配对决定。"},{"senses":"S3","en":"HUSBANDRY: keeping and raising animals becomes an occupation.","cn":"养殖：饲养与养育动物成为一种职业。"},{"senses":"S4","en":"UPBRINGING: cultivation as a metaphor for manners.","cn":"教养：把栽培用作举止的隐喻。"},{"senses":"S8","en":"METAPHOR: a place where something multiplies.","cn":"比喻：某事物大量滋生的地方。"}]},"affixes":{"intro":{"en":"Breeding is breed plus -ing. Both elements are native English, so the word has no Latin affix, though it belongs to the same Germanic family as brood.","cn":"breeding 是 breed 加 -ing。两个成分都是英语本族成分，因此这个词没有拉丁词缀，但它与 brood 同属日耳曼词族。"},"latinIntro":{"en":"There is no Latin element in breeding: breed comes from Old English bredan, and -ing is a native suffix. Latin has no share in this word.","cn":"breeding 中没有拉丁成分：breed 来自古英语 bredan，-ing 是本族后缀。拉丁语与这个词无关。"},"items":[{"word":"breed","structure":"Old English bredan (to warm, cherish, produce young)","meaning":"to produce offspring","meaningCN":"生育后代","example":"The rabbits breed twice a year.","exampleCN":"这些兔子一年繁殖两次。"},{"word":"-ing","structure":"Old English -ing (action or process)","meaning":"the action or process of","meaningCN":"……的动作或过程","example":"Breeding names the process.","exampleCN":"breeding 命名这个过程。"},{"word":"breeder","structure":"breed + -er (agent)","meaning":"one who breeds","meaningCN":"从事繁育的人","example":"The breeder keeps pedigree records.","exampleCN":"育种者保存谱系记录。"},{"word":"bred","structure":"past participle of breed","meaning":"produced or raised","meaningCN":"被繁育或养育的","example":"The birds were bred in captivity.","exampleCN":"这些鸟在圈养环境中繁育。"},{"word":"breeding","structure":"breed + -ing","meaning":"the process of producing young","meaningCN":"产生后代的过程","example":"Breeding requires steady conditions.","exampleCN":"繁殖需要稳定的条件。"},{"word":"crossbreeding","structure":"cross- + breeding","meaning":"breeding across different lines","meaningCN":"跨不同世系繁育","example":"Crossbreeding adds new traits.","exampleCN":"杂交增添新性状。"},{"word":"inbreeding","structure":"in- (within) + breeding","meaning":"breeding within a close group","meaningCN":"在近亲群体内繁育","example":"Inbreeding lowers vigor.","exampleCN":"近交降低活力。"},{"word":"breeding ground","structure":"breeding + ground","meaning":"a place where animals breed or problems multiply","meaningCN":"动物繁殖或问题滋生的地方","example":"Warm shallow water is a breeding ground.","exampleCN":"温暖的浅水是一处繁殖地。"}],"latinEntries":[]}},{"word":"breed","ipa_uk":"/briːd/","ipa_us":"/briːd/","definition_zh":"繁殖；饲养；培育；品种；类型；滋生","definition_en":"to produce offspring or raise animals and plants; also a group of animals of one type","core_image":"一窝幼兔在暖处挤成一团，母兔守在旁边","scene":"农场的兔子一窝接一窝地添丁。兽医笑着说：These rabbits breed quickly in warm weather.","sceneCN":"这里指「繁殖」（第 1 个义项：生物产生后代）；句意为这些兔子在温暖天气里繁殖很快。","pos":[{"tag":"v.","zh":"繁殖；生育；饲养；培育；滋生（三单 breeds，过去式与过去分词 bred）"},{"tag":"n.","zh":"品种；类型（可数，复数 breeds）"}],"collocations":[{"phrase":"breed animals","zh":"繁育动物"},{"phrase":"breed livestock","zh":"饲养畜禽"},{"phrase":"a breed of dog","zh":"一种狗"},{"phrase":"rare breed","zh":"稀有品种"},{"phrase":"breed contempt","zh":"滋生蔑视"},{"phrase":"breeding pair","zh":"繁殖对"},{"phrase":"breed true","zh":"稳定遗传；纯繁"}],"forms":[{"label":"三单（he/she/it）","form":"breeds"},{"label":"过去式","form":"bred"},{"label":"过去分词","form":"bred"},{"label":"现在分词","form":"breeding"},{"label":"复数（名词）","form":"breeds"},{"label":"名词（繁育者）","form":"breeder（育种者）"}],"derivatives":[{"word":"breeding","pos":"n.","zh":"繁殖；育种；教养"},{"word":"breeder","pos":"n.","zh":"育种者；饲养者"},{"word":"bred","pos":"adj.","zh":"培育的；繁殖的"},{"word":"crossbreed","pos":"v./n.","zh":"使杂交 / 杂交后代"},{"word":"inbreed","pos":"v.","zh":"使近亲繁殖"}],"senses":[{"no":"01","title":"To produce offspring","titleCN":"繁殖；生育（不及物）","definition":"to produce young, used especially of animals","definitionCN":"产生后代，尤用于动物","example":"These rabbits breed quickly in warm weather.","exampleCN":"这些兔子在温暖天气里繁殖很快。","why":"The oldest sense is biological: a generation produces the next, and the verb needs no object.","whyCN":"最古老的义项是生物的：一个世代产生下一个世代，动词不需要宾语。"},{"no":"02","title":"To keep and raise animals","titleCN":"饲养；培育（及物）","definition":"to keep animals or plants for reproduction or production","definitionCN":"为繁殖或生产而饲养动物或培植植物","example":"The farm breeds cattle for both milk and meat.","exampleCN":"这个农场饲养牛，既为产奶也为产肉。","why":"With an object, the verb shifts from the animals' own reproduction to human management of it.","whyCN":"带宾语时，动词从动物自身的繁殖转指人类对其繁殖的管理。"},{"no":"03","title":"A breed as a type of animal","titleCN":"品种（名词）","definition":"a group of animals with a shared appearance and ancestry","definitionCN":"具有共同外观与血统的一群动物","example":"The breed is known for its thick coat.","exampleCN":"这个品种以厚毛著称。","why":"As a noun the word names the stable result of generations of breeding, not a single animal.","whyCN":"作名词时，这个词命名多代繁育形成的稳定结果，而不是单个动物。"},{"no":"04","title":"A type or kind of person or thing","titleCN":"类型；种类（引申）","definition":"a kind or sort, often used in the phrase a breed of","definitionCN":"一种类型或类别，多用于表示某一类人或物的固定说法","example":"He is a rare breed of honest official.","exampleCN":"他是少见的诚实官员。","why":"The idea of a stable type extends from animals to people and things that share a recognizable character.","whyCN":"稳定类型的观念从动物扩展到具有可辨识性格的人与物。"},{"no":"05","title":"To cause or foster something","titleCN":"滋生；引起","definition":"to cause a feeling or situation to develop","definitionCN":"使某种情绪或情况发展起来","example":"Familiarity can breed contempt.","exampleCN":"过度熟悉可能滋生轻视。","why":"The picture of animals multiplying in a favorable place becomes a metaphor for feelings that grow.","whyCN":"动物在有利场所大量繁殖的图像，变成情绪滋长的隐喻。"},{"no":"06","title":"To improve a line by selection","titleCN":"育种；改良","definition":"to select parents over generations to improve a variety","definitionCN":"在多代中选择亲本以改良品种","example":"Plant breeders bred the wheat for shorter stems.","exampleCN":"植物育种者培育出茎更短的小麦。","why":"Controlled breeding turns the verb into a technical practice aimed at a desired trait.","whyCN":"有控繁育把这个动词变成一种以目标性状为目的的技术实践。"},{"no":"07","title":"To mate animals","titleCN":"交配；配种","definition":"to bring selected males and females together for mating","definitionCN":"把选定的雌雄个体带到一起交配","example":"They bred the stallion with the mare in spring.","exampleCN":"他们在春天让这匹公马与母马配种。","why":"The verb also names the specific act of pairing, which is the manager's decision rather than the animals'.","whyCN":"这个动词也命名具体的配对行为，这是管理者的决定，而非动物自己的行为。"},{"no":"08","title":"To bring up or educate","titleCN":"养育；教养（古义）","definition":"to raise and educate a person, an older sense now mainly literary","definitionCN":"养育并教育一个人，这一较旧义项现在主要用于书面语","example":"A poet bred in a quiet village wrote about the city.","exampleCN":"一个在安静村庄长大的诗人写下了关于城市的作品。","why":"The old sense treats upbringing as cultivation, the same metaphor that survives in well-bred.","whyCN":"旧义把养育当作栽培，这一隐喻仍留在 well-bred 中。"}],"etymology":{"intro":{"en":"Breed comes from Old English bredan 'to warm, cherish, produce young', a native Germanic verb related to brood and broth. Dates are approximate.","cn":"breed 来自古英语 bredan「保暖、抚育、生育」，是本族日耳曼动词，与 brood、broth 相关。年代均为约数。"},"items":[{"era":"OLD ENGLISH BREDAN","en":"Bredan meant 'to warm, keep warm, cherish', used especially of tending young. The sense 'produce offspring' developed from this care.","cn":"bredan 意为「保暖、保温、抚育」，尤用于照料幼仔。「生育后代」义从这种照料发展而来。"},{"era":"GERMANIC KIN","en":"The verb is related to brood 'a family of young' and broth 'liquid in which food is cooked', both from a root connected with warmth.","cn":"这个动词与 brood「一窝幼仔」、broth「煮食物的汤液」相关，它们都出自与「加温」有关的词根。"},{"era":"MIDDLE ENGLISH","en":"In Middle English the verb broadened from cherishing the young to producing them, and the noun breed appeared for a line of stock.","cn":"在中古英语中，动词从抚育幼仔扩展到生育幼仔，名词 breed 也出现，指一个品系。"},{"era":"NOUN SENSE","en":"The noun breed for a type of animal with shared ancestry became standard with pedigree keeping in the eighteenth and nineteenth centuries.","cn":"名词 breed 指具有共同血统的一类动物，在 18 至 19 世纪随谱系保存而成为标准用法。"},{"era":"METAPHOR","en":"The figurative senses 'a type of person' and 'to foster a feeling' developed from the same idea of a stock multiplying.","cn":"「一类人」与「滋生情绪」的比喻义，都从「一个种群大量增殖」的同一观念发展而来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root): the deeper Indo-European origin of the Germanic warming root is reconstructed with competing accounts, and the first use of the noun is dated only approximately.","cn":"来源不确定（词根）：日耳曼「加温」词根的更深印欧来源属重构，存在不同假说；名词的最早使用也只有大致年代。"}]},"similar":{"note":{"en":"Group one holds forms of the same verb that are easily confused; group two holds verbs for producing and raising young.","cn":"第一组是同一动词的各个形式，容易混淆；第二组是表示生育与养育的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"breeding","ipa":"/ˈbriːdɪŋ/","tag":"the process","definition":"The noun for the process; breed is the action or the type.","definitionCN":"指过程的名词；breed 是动作或类型。"},{"word":"bred","ipa":"/bred/","tag":"past form","definition":"The past tense and past participle; it is not a separate word with a new meaning.","definitionCN":"过去式与过去分词；不是另有新义的独立词。"},{"word":"breeder","ipa":"/ˈbriːdə/","tag":"the person","definition":"A person who breeds; the -er suffix names the agent.","definitionCN":"指从事繁育的人；-er 后缀命名施动者。"},{"word":"brood","ipa":"/bruːd/","tag":"the young or the sitting","definition":"A family of young, or to sit on eggs; it is a related word but not a form of breed.","definitionCN":"指一窝幼仔，或指孵蛋；是相关词，但不是 breed 的形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"biological term","definition":"To produce new organisms; it is broader and includes plants and microbes.","definitionCN":"指产生新生物体；范围更广，包括植物与微生物。"},{"word":"raise","ipa":"/reɪz/","tag":"care for the young","definition":"To care for young until they are grown; breeding starts the generation, raising follows it.","definitionCN":"指照料幼体直到长成；breeding 开始一个世代，raise 在其后。"},{"word":"propagate","ipa":"/ˈprɒpəɡeɪt/","tag":"plants","definition":"To produce new plants, often by cuttings or division; it can be asexual.","definitionCN":"指产生新植物，常用扦插或分株；可以无性。"},{"word":"rear","ipa":"/rɪə/","tag":"bring up","definition":"To bring up young animals or children; it is about care rather than mating.","definitionCN":"指养育幼兽或孩子；关乎照料，而非交配。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Old English bredan 'to warm, cherish' is the core: young are warmed into life.","cn":"古英语 bredan「保暖、抚育」是核心：幼仔被温暖地带到世上。"},{"en":"The family runs breed, bred, breeding, breeder, crossbreed, inbreed.","cn":"同族词包括 breed、bred、breeding、breeder、crossbreed、inbreed。"},{"en":"Fixed phrases: breed animals, a breed of dog, breed contempt.","cn":"固定搭配：繁育动物、一种狗、滋生蔑视。"},{"en":"The noun names a stable type; the verb names the action that produces it.","cn":"名词命名稳定的类型，动词命名产生它的动作。"},{"en":"Well-bred keeps the old metaphor of upbringing as cultivation.","cn":"well-bred 保留了「养育即栽培」的旧隐喻。"}],"abstract":[{"en":"Picture a nest of young animals huddled for warmth.","cn":"想象一窝幼兽挤在一起取暖。"},{"en":"Picture a gardener saving seed from the best plant.","cn":"想象园丁从最好的植株留种。"},{"en":"Picture a habit growing quietly until it becomes a problem.","cn":"想象一个习惯悄悄滋长，直到成为问题。"}]},"examples":[{"en":"Some birds breed only on remote islands.","cn":"有些鸟只在偏远岛屿上繁殖。"},{"en":"The center breeds endangered frogs for release.","cn":"该中心繁育濒危蛙类以供放归。"},{"en":"A hard climate can breed a hardy breed of sheep.","cn":"严酷的气候能育出一种耐寒的羊品种。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「布里德」——把幼仔暖在怀里、让它们一代代生下去 → 繁殖、品种","word":"breed"},"root":"古英语 bredan「保暖、抚育、生育」，本族日耳曼动词，与 brood「一窝幼仔」、broth「汤液」相关；更深印欧词根属重构。","sensesIntro":{"en":"Eight senses follow one act: a generation produces the next, and the same act extends to husbandry, stable types, fostering feelings and old-fashioned upbringing.","cn":"八个义项围绕同一个动作展开：一个世代产生下一个世代，这个动作再延伸到养殖、稳定类型、滋生情绪与旧式教养。"},"semanticMap":{"core":{"en":"CORE IMAGE: a litter of young huddled for warmth with the mother nearby.","cn":"核心意象：一窝幼仔挤在一起取暖，母兽守在旁边。"},"chain":["YOUNG BORN","PAIR MATED","STOCK RAISED","TYPE FIXED","FEELING FOSTERED","PERSON REARED"],"branches":[{"senses":"S1 · S7","en":"BIOLOGY AND MATING: producing young naturally, and the specific pairing a manager arranges.","cn":"生物学与配种：自然产生后代，以及管理者安排的具体配对。"},{"senses":"S2 · S6","en":"HUSBANDRY AND IMPROVEMENT: raising stock, and selecting parents to improve a line.","cn":"养殖与改良：饲养畜禽，以及选择亲本改良品系。"},{"senses":"S3 · S4","en":"TYPE: a stable animal breed, and a recognizable kind of person or thing.","cn":"类型：稳定的动物品种，以及可辨识的一类人或物。"},{"senses":"S5","en":"METAPHOR: a feeling grows as if it were stock multiplying.","cn":"比喻：情绪像种群增殖一样滋长。"},{"senses":"S8","en":"UPBRINGING: the old sense of rearing and educating a person.","cn":"教养：养育并教育一个人的旧义。"}]},"affixes":{"intro":{"en":"Breed is a native English verb with no derivational prefix; -ing, -er and the irregular past bred build its family.","cn":"breed 是英语本族动词，没有派生前缀；-ing、-er 与不规则过去式 bred 构成它的词族。"},"latinIntro":{"en":"No Latin element is involved: breed, bred, breeding and breeder are all native Germanic formations.","cn":"这里没有拉丁成分：breed、bred、breeding 与 breeder 都是本族日耳曼构词。"},"items":[{"word":"breed","structure":"Old English bredan (to warm, cherish, produce young)","meaning":"to produce offspring; a type of animal","meaningCN":"生育后代；一类动物","example":"The birds breed in spring.","exampleCN":"这些鸟在春天繁殖。"},{"word":"-ing","structure":"Old English -ing (action or process)","meaning":"the action or process","meaningCN":"动作或过程","example":"Breeding is the process noun.","exampleCN":"breeding 是过程名词。"},{"word":"-er","structure":"Old English -ere (agent)","meaning":"one who does","meaningCN":"做某事的人","example":"A breeder keeps the records.","exampleCN":"育种者保存记录。"},{"word":"bred","structure":"irregular past and past participle of breed","meaning":"produced or raised","meaningCN":"被繁育或养育的","example":"The horses were bred for endurance.","exampleCN":"这些马是为耐力而繁育的。"},{"word":"breeding","structure":"breed + -ing","meaning":"the process of producing young","meaningCN":"产生后代的过程","example":"Breeding takes place in shallow water.","exampleCN":"繁殖发生在浅水中。"},{"word":"crossbreed","structure":"cross- + breed","meaning":"to breed across lines","meaningCN":"跨世系繁育","example":"They crossbreed the two varieties.","exampleCN":"他们让两个品种杂交。"},{"word":"inbreed","structure":"in- (within) + breed","meaning":"to breed close relatives","meaningCN":"使近亲繁育","example":"Small populations inbreed.","exampleCN":"小群体发生近亲繁殖。"},{"word":"breeder","structure":"breed + -er","meaning":"a person who breeds","meaningCN":"从事繁育的人","example":"The breeder selected the parents.","exampleCN":"育种者选定了亲本。"}],"latinEntries":[]}},{"word":"inbreeding","ipa_uk":"/ɪnˈbriːdɪŋ/","ipa_us":"/ɪnˈbriːdɪŋ/","definition_zh":"近亲繁殖；近交；近交衰退","definition_en":"the breeding of closely related individuals, often leading to reduced fitness","core_image":"一座孤岛上的兽群多年没有外来个体加入","scene":"岛上的小种群多年没有外来个体加入。保护者警告：Inbreeding reduces the number of healthy offspring in the population.","sceneCN":"这里指「近亲繁殖」（第 1 个义项：亲缘关系很近的个体交配繁育）；句意为近亲繁殖减少了群体中健康后代的数量。","pos":[{"tag":"n.","zh":"近亲繁殖；近交（不可数）"}],"collocations":[{"phrase":"inbreeding depression","zh":"近交衰退"},{"phrase":"inbreeding coefficient","zh":"近交系数"},{"phrase":"avoid inbreeding","zh":"避免近亲繁殖"},{"phrase":"inbreeding in small populations","zh":"小群体中的近交"},{"phrase":"close inbreeding","zh":"紧密近交"},{"phrase":"inbreeding and crossbreeding","zh":"近交与杂交"}],"forms":[{"label":"复数（指多次近交，少见）","form":"inbreedings"},{"label":"动词","form":"inbreed（使近亲繁殖）"},{"label":"过去式","form":"inbred"},{"label":"过去分词","form":"inbred"},{"label":"形容词（近交的）","form":"inbred（近亲繁殖的）"},{"label":"名词（近交衰退）","form":"inbreeding depression（近交衰退）"}],"derivatives":[{"word":"inbreed","pos":"v.","zh":"使近亲繁殖"},{"word":"inbred","pos":"adj.","zh":"近亲繁殖的；近交的"},{"word":"linebreeding","pos":"n.","zh":"系谱内繁育；品系繁育"},{"word":"outbreeding","pos":"n.","zh":"远亲繁殖；远交"},{"word":"crossbreeding","pos":"n.","zh":"杂交；杂交育种"}],"senses":[{"no":"01","title":"Breeding close relatives","titleCN":"近亲繁殖（基本义）","definition":"the mating of individuals that are closely related by ancestry","definitionCN":"血缘关系很近的个体交配","example":"Inbreeding reduces the number of healthy offspring in the population.","exampleCN":"近亲繁殖减少了群体中健康后代的数量。","why":"In- marks breeding within a closed circle, and the word names the practice that keeps relatives as parents.","whyCN":"in- 标记在一个封闭圈子内繁育，这个词命名让亲属成为亲本的做法。"},{"no":"02","title":"Inbreeding in genetics","titleCN":"近交（遗传学术语）","definition":"the mating of individuals more closely related than the average of the population","definitionCN":"亲缘关系比群体平均更近的个体交配","example":"The inbreeding coefficient rose to one eighth in the herd.","exampleCN":"牛群的近交系数升到了八分之一。","why":"Genetics defines the term relative to the population average, so even a mild practice can count as inbreeding.","whyCN":"遗传学以群体平均为参照定义这个术语，因此即使较温和的做法也可能算近交。"},{"no":"03","title":"Inbreeding depression","titleCN":"近交衰退（结果）","definition":"the loss of fitness and vigor caused by continued close breeding","definitionCN":"持续近亲繁育造成的适合度与活力下降","example":"Inbreeding depression lowered the germination rate.","exampleCN":"近交衰退降低了发芽率。","why":"The noun is often used for the harmful consequence, because hidden harmful alleles become visible when relatives mate.","whyCN":"这个名词常指有害后果，因为亲属交配时隐藏的有害等位基因会显现。"},{"no":"04","title":"Breeding in a closed population","titleCN":"封闭群体内的交配","definition":"breeding within a group that has no immigration from outside","definitionCN":"在没有外来个体迁入的群体内繁育","example":"Island populations are vulnerable to inbreeding.","exampleCN":"岛屿群体容易陷入近亲繁殖。","why":"A closed group forces relatives to become mates, which is the structural cause of inbreeding.","whyCN":"封闭群体迫使亲属成为配偶，这是近亲繁殖的结构性原因。"},{"no":"05","title":"Inbreeding in plants","titleCN":"植物的自交与近交","definition":"self-pollination or crossing between closely related plants","definitionCN":"自花授粉或亲缘很近的植株之间杂交","example":"Self-pollinating crops show strong inbreeding in nature.","exampleCN":"自花授粉的作物在自然界表现出很强的近交。","why":"Plants that pollinate themselves are the extreme case: the two parents are the same individual.","whyCN":"自花授粉的植物是极端情形：两个亲本就是同一个个体。"},{"no":"06","title":"Inbred lines in breeding","titleCN":"育种中的近交系","definition":"lines maintained by close breeding to fix traits, often used for later crossing","definitionCN":"通过近亲繁育维持、以固定性状的品系，常用于后续杂交","example":"The lab keeps inbreeding lines for genetic studies.","exampleCN":"实验室保存近交系用于遗传研究。","why":"Breeders sometimes use inbreeding deliberately to make uniform lines, accepting the cost in vigor.","whyCN":"育种者有时有意使用近交来获得一致品系，并接受活力下降的代价。"},{"no":"07","title":"Marriage within a family","titleCN":"家族内部通婚（人类）","definition":"reproduction between close relatives in human populations","definitionCN":"人类群体中近亲之间的生育","example":"Historical records document inbreeding among isolated families.","exampleCN":"历史记录记载了孤立家族中的近亲通婚。","why":"The same biological term applies to people, where it also carries legal and social restrictions.","whyCN":"同一生物术语也适用于人，但在人身上还带有法律与社会限制。"},{"no":"08","title":"A metaphor for a closed circle","titleCN":"比喻：封闭圈子的内部循环","definition":"a figurative tendency of a group to draw only on itself","definitionCN":"一个群体只从自身内部取材的比喻性倾向","example":"The studio's inbreeding of ideas made its films repetitive.","exampleCN":"这家制片公司在观念上的自我循环使它的电影变得重复。","why":"The genetic picture of a closed group producing from itself describes any circle that stops bringing in new material.","whyCN":"封闭群体只从自身繁殖的遗传图像，用来描述任何停止引入新材料的圈子。"}],"etymology":{"intro":{"en":"Inbreeding is an English compound of in- 'within' and breeding. Inbred is recorded from the late sixteenth century, the noun inbreeding from the nineteenth. Dates are approximate.","cn":"inbreeding 是英语复合词，由 in-「在内」与 breeding 构成。inbred 的记录可追溯至 16 世纪后期，名词 inbreeding 则始于 19 世纪。年代均为约数。"},"items":[{"era":"NATIVE IN-","en":"The prefix in- here is the native English preposition and prefix meaning 'within', not the Latin negative in-.","cn":"这里的前缀 in- 是英语本族的介词与词缀，意为「在内」，而不是拉丁否定前缀 in-。"},{"era":"BREEDING","en":"Breeding comes from Old English bredan 'to warm, cherish, produce young', and names the production of offspring.","cn":"breeding 来自古英语 bredan「保暖、抚育、生育」，命名产生后代的过程。"},{"era":"INBRED","en":"The adjective inbred is recorded in the late sixteenth century, first describing animals produced within a close group.","cn":"形容词 inbred 在 16 世纪后期已有记录，最初描述在近亲群体内繁育的动物。"},{"era":"NINETEENTH CENTURY","en":"The noun inbreeding became common in the nineteenth century with pedigree breeding and the recognition of inbreeding depression.","cn":"名词 inbreeding 在 19 世纪随谱系育种与近交衰退的认识而常见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates): the earliest use of the noun inbreeding is dated only to the nineteenth century, and the exact first record of inbred is not fixed.","cn":"来源不确定（首见年代）：名词 inbreeding 的最早使用只能定在 19 世纪；inbred 的确切最早记录未有定论。"}]},"similar":{"note":{"en":"Group one holds forms from the same inbreed family that are easily confused; group two holds terms for related breeding strategies.","cn":"第一组是同出 inbreed 词族、容易混淆的形式；第二组是相关的繁育策略术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inbreed","ipa":"/ɪnˈbriːd/","tag":"the verb","definition":"To breed close relatives; inbreeding is the process noun.","definitionCN":"指让近亲繁育；inbreeding 是过程名词。"},{"word":"inbred","ipa":"/ɪnˈbred/","tag":"the adjective","definition":"Produced by close breeding; it describes the result, not the practice.","definitionCN":"指由近亲繁育产生的；描述结果，而非做法。"},{"word":"linebreeding","ipa":"/ˈlaɪnbriːdɪŋ/","tag":"a milder strategy","definition":"Breeding within one line while avoiding the closest relatives; it is a controlled compromise.","definitionCN":"指在一个品系内繁育但避免最近的亲属；是有控制的折中。"},{"word":"outbreeding","ipa":"/ˈaʊtbriːdɪŋ/","tag":"the opposite","definition":"Breeding unrelated individuals to increase diversity; it is the remedy for inbreeding.","definitionCN":"指繁育无关个体以提高多样性；是近交的补救办法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crossbreeding","ipa":"/ˈkrɒsbriːdɪŋ/","tag":"the opposite practice","definition":"Breeding different lines or breeds; it brings in new alleles instead of closing the circle.","definitionCN":"指让不同品系或品种繁育；引入新等位基因，而非封闭圈子。"},{"word":"consanguinity","ipa":"/kənˌsæŋˈɡwɪnəti/","tag":"relatedness","definition":"Blood relationship between individuals; it is the condition that makes a mating inbreeding.","definitionCN":"指个体之间的血缘关系；是使一次交配成为近亲繁殖的条件。"},{"word":"selfing","ipa":"/ˈselfɪŋ/","tag":"plant extreme","definition":"Self-pollination in plants; it is the most extreme form of inbreeding.","definitionCN":"指植物的自花授粉；是近亲繁殖的最极端形式。"},{"word":"interbreeding","ipa":"/ˌɪntəˈbriːdɪŋ/","tag":"between groups","definition":"Breeding between different groups or species; it is not necessarily close breeding.","definitionCN":"指不同群体或物种之间的繁育；不一定是近亲繁育。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'within' + breeding: breeding inside a closed circle.","cn":"in-「在内」+ breeding：在一个封闭圈子内繁育。"},{"en":"The family runs inbreed, inbred, inbreeding, linebreeding, outbreeding.","cn":"同族词包括 inbreed、inbred、inbreeding、linebreeding、outbreeding。"},{"en":"Fixed phrases: inbreeding depression, inbreeding coefficient, avoid inbreeding.","cn":"固定搭配：近交衰退、近交系数、避免近亲繁殖。"},{"en":"Inbreeding is the opposite of crossbreeding: inside relatives versus outside lines.","cn":"近交与杂交相对：一个是内部亲属，一个是外部世系。"},{"en":"Small populations inbreed because there are no outside mates.","cn":"小群体发生近交，因为没有外来配偶。"}],"abstract":[{"en":"Picture an island herd with no new animals arriving for generations.","cn":"想象一座岛上的兽群，几代都没有新个体到来。"},{"en":"Picture a family photograph where every face resembles the last.","cn":"想象一张家族合影，每张脸都像上一张。"},{"en":"Picture a closed club that only invites its own members.","cn":"想象一个封闭俱乐部，只邀请自己的成员。"}]},"examples":[{"en":"Inbreeding depression appeared after four generations of close mating.","cn":"四代近亲交配之后出现了近交衰退。"},{"en":"Conservationists introduce unrelated animals to reduce inbreeding.","cn":"保护工作者引入无关个体以减少近亲繁殖。"},{"en":"The population avoided inbreeding by crossing with a neighboring group.","cn":"这个群体通过与邻群杂交避免了近亲繁殖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因布里丁」——只在自家圈子里找配偶，不外娶也不外嫁 → 近亲繁殖","word":"inbreeding"},"root":"in-（英语本族前缀「在内」）+ breeding（古英语 bredan「保暖、抚育、生育」+ -ing）；无拉丁语来源。","sensesIntro":{"en":"Eight senses follow one closed circle: relatives become parents, and the consequences are named in genetics, conservation, crops, breeding lines, human families and metaphor.","cn":"八个义项围绕一个封闭圈子展开：亲属成为亲本，其后果再在遗传学、保护、作物、育种品系、人类家庭与比喻中获得名称。"},"semanticMap":{"core":{"en":"CORE IMAGE: an island herd with no newcomers for generations.","cn":"核心意象：一座岛上的兽群，几代都没有外来者。"},"chain":["CIRCLE CLOSED","RELATIVES MATE","ALLELES MEET","VIGOR FALLS","LINES FIXED","METAPHOR FORMED"],"branches":[{"senses":"S1 · S2","en":"PRACTICE AND DEFINITION: mating relatives, and the genetic definition relative to a population.","cn":"做法与定义：亲属交配，以及相对于群体的遗传学定义。"},{"senses":"S3 · S4","en":"CONSEQUENCE AND CAUSE: depression follows, and a closed population forces it.","cn":"后果与原因：衰退随之而来，封闭群体迫使它发生。"},{"senses":"S5 · S6","en":"PLANTS AND LINES: selfing is the extreme, and inbred lines are a deliberate tool.","cn":"植物与品系：自交是极端，近交系是有意的工具。"},{"senses":"S7","en":"HUMAN FAMILIES: the same biology applies to people.","cn":"人类家庭：同一生物学也适用于人。"},{"senses":"S8","en":"METAPHOR: any closed circle that draws only on itself.","cn":"比喻：任何只从自身取材的封闭圈子。"}]},"affixes":{"intro":{"en":"Inbreeding joins the native prefix in- 'within' to breeding; the prefix here is not the Latin negative in-.","cn":"inbreeding 把本族前缀 in-「在内」接到 breeding 上；这里的前缀不是拉丁否定前缀 in-。"},"latinIntro":{"en":"There is no Latin element: in- is native English 'within', and breeding comes from Old English bredan.","cn":"这里没有拉丁成分：in- 是英语本族表示「在内」的前缀，breeding 来自古英语 bredan。"},"items":[{"word":"in-","structure":"Old English in (within, inside)","meaning":"within; inside","meaningCN":"在内；向里","example":"The prefix keeps the breeding inside a group.","exampleCN":"这个前缀把繁育保持在群体内部。"},{"word":"breed","structure":"Old English bredan (to warm, cherish, produce young)","meaning":"to produce offspring","meaningCN":"生育后代","example":"The animals breed in spring.","exampleCN":"这些动物在春天繁殖。"},{"word":"-ing","structure":"Old English -ing (action or process)","meaning":"the action or process","meaningCN":"动作或过程","example":"The suffix makes a process noun.","exampleCN":"这个后缀构成过程名词。"},{"word":"inbreed","structure":"in- + breed","meaning":"to breed close relatives","meaningCN":"使近亲繁育","example":"Isolated groups inbreed.","exampleCN":"孤立群体发生近亲繁殖。"},{"word":"inbred","structure":"in- + bred","meaning":"produced by close breeding","meaningCN":"由近亲繁育产生的","example":"The inbred line is uniform but weak.","exampleCN":"这个近交系一致但弱小。"},{"word":"inbreeding","structure":"inbreed + -ing","meaning":"close breeding","meaningCN":"近亲繁育","example":"Inbreeding reduces diversity.","exampleCN":"近亲繁殖降低多样性。"},{"word":"linebreeding","structure":"line + breeding","meaning":"controlled breeding within one line","meaningCN":"在一个品系内有控制的繁育","example":"Linebreeding keeps a desired trait.","exampleCN":"品系繁育保留所需性状。"},{"word":"outbreeding","structure":"out- + breeding","meaning":"breeding unrelated individuals","meaningCN":"繁育无关个体","example":"Outbreeding restores vigor.","exampleCN":"远交恢复活力。"}],"latinEntries":[]}}]);
